	while(N < 2*n-1) N <<= 1;
	jc[0] = 1;
	for(i = 1; i <= N; i++) jc[i] = jc[i-1]*i%Mod;
	inv[0] = inv[1] =1;
	for(i = 2; i <= N; i++) inv[i] = inv[Mod%i]*(Mod-Mod/i)%Mod;
	invN = inv[N];
	for(i = 2; i <= N; i++) inv[i] = inv[i-1]*inv[i]%Mod;
	for(i = 1; i <= n-1; i++) A[i] = A[i]*jc[i]%Mod;
	for(i = n-1; i >= 0; i--) B[i] = inv[n-1-i];
	dft(A, 1); dft(B, 1);
	for(i = 0; i < N; i++) A[i] = A[i]*B[i]%Mod;
	dft(A, -1);
	for(i = 1; i <= n; i++){
