void ins(int x,int y)
{
	int t=++len;
	e[t].y=y;e[t].next=last[x];last[x]=t;
}
int Pow(int x,LL y)
{
    if(!y)return 1;
    int t=Pow(x,y>>1),re=(LL)t*t%mod;
    if(y&1)re=(LL)re*x%mod;
    return re;
}
int fac[Maxn],fin[Maxn];
void pre()
{
    fac[0]=1;for(int i=1;i<=n;i++)fac[i]=(LL)fac[i-1]*i%mod;
    fin[n]=Pow(fac[n],mod-2);for(int i=n-1;i>=0;i--)fin[i]=(LL)fin[i+1]*(i+1)%mod;
}
int C(int n,int m)
{
    if(n<m)return 0;
    return(LL)fac[n]*fin[m]%mod*fin[n-m]%mod;
}
int cnt[Maxn];
void dfs(int x,int ff)
{
	sz[x]=1;
	for(int i=last[x];i;i=e[i].next)
	{
		int y=e[i].y;
		if(y==ff)continue;
		dfs(y,x);
		sz[x]+=sz[y];cnt[sz[y]]++;
	}
	cnt[n-sz[x]]++;
}
int rev[(1<<19)+10],A[(1<<19)+10],B[(1<<19)+10];
void NTT(int *a,int n,int o)
{
	for(int i=0;i<n;i++)if(i<rev[i])swap(a[i],a[rev[i]]);
	for(int i=1;i<n;i<<=1)
	{
		int wn;
		if(o==1)wn=Pow(gn,(mod-1)/(i<<1));
		else wn=Pow(gn,mod-1-(mod-1)/(i<<1));
		for(int j=0;j<n;j+=(i<<1))
		{
			int w=1;
			for(int k=0;k<i;k++)
			{
				int t=(LL)a[i+j+k]*w%mod;w=(LL)w*wn%mod;
				a[i+j+k]=(a[j+k]-t+mod)%mod;
				a[j+k]=(a[j+k]+t)%mod;
			}
		}
	}
	if(o==-1)
	{
		int inv=Pow(n,mod-2);
		for(int i=0;i<n;i++)a[i]=(LL)a[i]*inv%mod;
	}
}
