void NTT(int *a, int n, int res) {
	for (int i = 0; i < n; ++i) if (i < R[i]) std :: swap(a[i], a[R[i]]);

	for (int k = 1; k < n; k <<= 1) {
		int x = w[res][n / k / 2];
