inline int Mul(int a, int b) {
  return (long long)a * b % mod;
}

inline int Add(int a) {
  return a >= mod ? a - mod : a;
}

inline int Sub(int a) {
  return a < 0 ? a + mod : a;
}

int Pow(int a, int b) {
  int c = 1;
  for (; b; b >>= 1) {
    if (b & 1) c = Mul(c, a);
    a = Mul(a, a);
  }
  return c;
}

void FFT(int *a, int n) {
  for (int i = 0; i < 1 << n; ++i) {
    int j = 0, x = i;
    for (int k = 0; k < n; ++k) {
      j = (j << 1) | (x & 1);
      x >>= 1;
    }
    if (i < j) {
      swap(a[i], a[j]);
    }
  }
  for (int i = 0; i < n; ++i) {
    int root = Pow(gen, (mod - 1) / (2 << i));
    for (int j = 0; j < 1 << n; j += 2 << i) {
      int *l = a + j, *r = l + (1 << i), w = 1;
      for (int k = 0; k < 1 << i; ++k, w = Mul(w, root)) {
        int t = Mul(w, r[k]);
        r[k] = Sub(l[k] - t);
        l[k] = Add(l[k] + t);
      }
    }
  }
}

void IFFT(int *a, int n) {
  reverse(a + 1, a + (1 << n));
  FFT(a, n);
  int inv = Pow(1 << n, mod - 2);
  for (int i = 0; i < 1 << n; ++i) {
    a[i] = Mul(a[i], inv);
  }
}

