	inline void polyinit(){
		const int wnv=fpow(proot,(p-1)/mxdg);
		const int iwnv=fpow(wnv,p-2);
		wn[0]=iwn[0]=1;
		for(int i=1,v=1,iv=1;i!=mxdg;++i){
			v=(int64)v*wnv%p;wn[i]=v;
			iv=(int64)iv*iwnv%p;iwn[i]=iv;
		}
	}

	void DFT(poly&A,const int&deg){
		for(int i=0,j=0;i!=deg;++i){
			if(i<j)swap(A[i],A[j]);
			for(int k=deg>>1;(j^=k)<k;k>>=1);
		}
		int*const td=A+deg;
		for(int l=1,tp=mxdg>>1;l!=deg;l+=l,tp>>=1)
			for(int*i=A,z;i<td;i+=l+l)
				for(int j=0,*w=wn;j!=l;++j,w+=tp)
					z=(int64)i[j+l]**w%p,
					i[j+l]=sub(i[j],z),
					inc(i[j],z);
	}
	void IDFT(poly&A,const int&deg){
		for(int i=0,j=0;i!=deg;++i){
			if(i<j)swap(A[i],A[j]);
			for(int k=deg>>1;(j^=k)<k;k>>=1);
		}
		int*const td=A+deg;
		for(int l=1,tp=mxdg>>1;l!=deg;l+=l,tp>>=1)
			for(int*i=A,z;i<td;i+=l+l)
				for(int j=0,*w=iwn;j!=l;++j,w+=tp)
					z=(int64)i[j+l]**w%p,
					i[j+l]=sub(i[j],z),
					inc(i[j],z);
	}
