int lgput( int x, int n ) {
    if( n == 0 )
        return 1;

    int y = lgput( x, n >> 1 );
    y = ( 1LL * y * y ) % MOD;

    if( n & 1 )
        y = ( 1LL * y * x ) % MOD;

    return y;
}

void dft( int pol[DIM], int sz, int sgn ) {
    int lg = 0;
    while( (1 << lg) < sz )
        lg ++;

    for( int i = 0; i < sz; i ++ ) {
        int x = 0;
        for( int j = 0; j < lg; j ++ )
            if( i & (1 << j) ) x |= (1 << (lg - j - 1));

        if( i < x )
            swap( pol[i], pol[x] );
    }

    for( int len = 2; len <= sz; len <<= 1 ) {
        int rot = lgput( 5, ( MOD - 1 + sgn * (MOD - 1) / len) % (MOD - 1) );

        for( int i = 0; i < sz; i += len ) {
            int stp = 1;

            for( int j = i; j < i + (len >> 1); j ++ ) {
                int x = pol[j], y = ( 1LL * stp * pol[j + (len >> 1)] ) % MOD;

                pol[j] = ( x + y ) % MOD;
                pol[j + (len >> 1)] = ( x - y + MOD ) % MOD;

                stp = ( 1LL * stp * rot ) % MOD;
            }
        }
    }

    if( sgn == -1 ) {
        int aux = lgput( sz, MOD - 2 );

        for( int i = 0; i < sz; i ++ )
            pol[i] = ( 1LL * pol[i] * aux ) % MOD;
    }

    return;
}

void ntt( int pol1[DIM], int pol2[DIM], int sz1, int sz2, int n ) {
    int sz = 1;
    while( sz < sz1 + sz2 - 1 )
        sz <<= 1;

    dft( pol1, sz, 1 );
    dft( pol2, sz, 1);

    for( int i = 0; i < sz; i ++ )
        pol1[i] = ( 1LL * pol1[i] * pol2[i] ) % MOD;
    dft( pol1, sz, -1 );

    return;
}

