		p++;
	a.resize((1 << p));
	b.resize((1 << p));
	nnt(a, 0);
	nnt(b, 0);
	for(int i = 0; i < (1 << p); ++i)
		a[i] = 1ll * a[i] * b[i] % mod;
	nnt(a, 1);
	return a;
}

