		for(int i=1;i<n;++i) if(i<rev[i]) swap(a[i], a[rev[i]]);
		for(int i=1;i<n;i<<=1){
			int gn = qpow(G,(p-1)/(i<<1));
			for(int j=0;j<n;j+=(i<<1)){
				int g = 1;
				for(int k=0;k<i;++k,g=(ll)g*gn%p){
					int x = a[j+k], y = (ll)g * a[j+k+i]%p;
					a[j+k] = qm(x+y), a[j+k+i] = qm(x-y+p);
				}
			}
		}
		if(!sgn){
			int iv = qpow(n,p-2); reverse(a+1,a+n);
			for(int i=0;i<n;++i) a[i] = (ll)iv * a[i]%p;
		}
	}
	void work(int*a,int*b,int n){
		int nn = 1, len = -1;
		while(nn <= n+n) nn <<= 1, ++len;
		for(int i=1;i<nn;++i) rev[i] = (rev[i>>1]>>1)|((i&1)<<len);
		ntt(a,nn,1), ntt(b,nn,1);
		for(int i=0;i<nn;++i) a[i] = (ll)a[i] * b[i]%p;
		ntt(a,nn,0);
	}
}

