		w[p] = size[to[p]];
		w[p ^ 1] = n - size[to[p]];
	}
}

int qp (int a, int b) { int c = 1; for (; b; b >>= 1, a = 1ll * a * a % P) if (b & 1) c = 1ll * c * a % P; return c; }

void bit_reverse (int *x, int n) {
	for (int i = 0, j = 0; i < n; ++i) {
		if (i < j) swap(x[i], x[j]);
		for (int l = n >> 1; (j ^= l) < l; l >>= 1) ;
	}
}

void NTT (int *buffer, int f, int n) {
	bit_reverse(buffer, n);
	int inv = qp(n, P - 2), i, j, k, x, y, wn, w;

	for (i = 1; i != n; i <<= 1) {
		wn = qp(5, (P - 1) / (i << 1));
		if (f == -1) wn = qp(wn, P - 2);
		for (j = 0; j != n; j += i << 1) {
			w = 1;
			for (k = j; k < j + i; ++k) {
				x = buffer[k]; y = 1ll * w * buffer[k + i] % P;
				buffer[k] = (x + y) % P;
				buffer[k + i] = (x - y) % P;
				w = 1ll * w * wn % P;
			}
		}
	}

	if (f == -1) for (int i = 1; i <= n; ++i) buffer[i] = 1ll * buffer[i] * inv % P;
}

void Mul (int *CC, const int *AA, const int *BB) {
	static int C[N], A[N], B[N];
	memset(C, 0, sizeof C);
	memset(A, 0, sizeof A);
	memset(B, 0, sizeof B);
	int m = (n + 1) << 1, t = 1;
	while (t < m) t <<= 1; m = t;
	for (int i = 0; i <= n; ++i) A[i] = AA[i], B[i] = BB[i];
//	for (int i = 0; i < m; ++i) for (int j = 0; j <= i; ++j) C[i] = (1ll * A[j] * B[i - j] + C[i]) % P;
	NTT(A, 1, m);
	NTT(B, 1, m);
	for (int i = 0; i < m; ++i) C[i] = 1ll * A[i] * B[i] % P;
	NTT(C, -1, m);
	for (int i = 0; i < m; ++i) CC[i] = C[i];
}

