typedef long long i64;
const int P=924844033,M=2e5+7;
int pw(int a,int n){
	if(n<0)n+=P-1;
	int v=1;
	for(;n;n>>=1,a=i64(a)*a%P)if(n&1)v=i64(v)*a%P;
	return v;
}
int A[533333],B[533333],r[533333],E[533333];
int n,ep=2,fac[M],fiv[M],e0[M],sz[M],t[M],N,K;
struct edge{
	int to,nx;
}e[M*2];
void f1(int w,int pa){
	sz[w]=1;
	for(int i=e0[w];i;i=e[i].nx){
		int u=e[i].to;
		if(u!=pa)f1(u,w),sz[w]+=sz[u];
	}
	++t[sz[w]];
	++t[n-sz[w]];
}
int fix(int x){return x+(x>>31&P);}
void ntt(int*a,int t){
	for(int i=1;i<N;++i)if(i<r[i])std::swap(a[i],a[r[i]]);
	for(int i=1;i<N;i<<=1){
		for(int j=0;j<N;j+=i<<1){
			i64 z=pw(5,(P-1)/(i<<1)*t);
			E[0]=1;
			for(int k=1;k<i;++k)E[k]=E[k-1]*z%P;
			int*b=a+j,*c=b+i;
			for(int k=0;k<i;++k){
				int x=b[k],y=c[k]*i64(E[k])%P;
				b[k]=fix(x+y-P);
				c[k]=fix(x-y);
			}
		}
	}
	if(t==-1){
		i64 I=pw(N,-1);
		for(int i=0;i<N;++i)a[i]=a[i]*I%P;
	}
}
int main(){
