	for(int i=1;i<N;++i)r[i]=r[i>>1]>>1|(i&1)<<K;
	for(int i=1;i<n;++i)A[n-i]=i64(t[i])*fac[i]%P;
	for(int i=0;i<=n;++i)B[i]=fiv[i];
	ntt(A,1),ntt(B,1);
