void fourie(int N,int d,vector<int> &vec ){// 1<<d == N
	// Uは順方向ではexp(2pi*I/N)逆だとexp(-2pi*I/N)
	if(N==1){
		return;
	}
	int gyaku=0;
	for(int i=1;i<N;i++){
		int e=1<<(d-1);
		while(gyaku&e){
			gyaku^=e;
			e>>=1;
		}
		gyaku^=e;
		if(i<gyaku)swap(vec[i],vec[gyaku]);	
	}
	for(int c=0;c<d;c++){
		int f=1<<c;
		for(int i=0;i<N;i+=(f<<1)){
			for(int j=i;j<i+f;j++){
				int A1=(vec[j]+vec[j+f]*D[(j-i)<<(d-c-1)])%MOD;
				int A2=(vec[j]-(vec[j+f]*D[(j-i)<<(d-c-1)]%MOD)+MOD)%MOD;
				vec[j]=A1;
				vec[j+f]=A2;
			}
		}
	}

	return;
}

