long long pw(long long x,long long y)
{
	long long res=1;
	while (y)
	{
		if (y&1)
		{
			res=res*x%Mod;
		}
		x=x*x%Mod;
		y>>=1;
	}
	return res;
}
void pre()
{
	long long inv5=pw(5,Mod-2);
	for (int i=1;i<=n;i<<=1)
	{
		pw5[i]=pw(5,(Mod-1)/i);
		pwinv5[i]=pw(inv5,(Mod-1)/i);
	}
}
void rader(long long *a)
{
	for (int i=0,j=0;i<n;i++)
	{
		if (i>j)
		{
			swap(a[i],a[j]);
		}
		int k=n;
		do
		{
			k>>=1;
			j^=k;
		}while (j<k);
	}
}
void ntt(long long *a,long long f)
{
	rader(a);
	for (int i=2;i<=n;i<<=1)
	{
		int m=i>>1;
		for (int j=0;j<n;j+=i)
		{
			long long w=1,wn=pw5[i];
			if (f==-1)
			{
				wn=pwinv5[i];
			}
			for (int k=0;k<m;k++)
			{
				long long x=a[j+k+m]*w%Mod;
				a[j+k+m]=(a[j+k]-x+Mod)%Mod;
				a[j+k]=(a[j+k]+x)%Mod;
				w=w*wn%Mod;
			}
		}
	}
	if (f==-1)
	{
		long long inv=pw(n,Mod-2);
		for (int i=0;i<n;i++)
		{
			a[i]=a[i]*inv%Mod;
		}
	}
}
void conv(long long *a,long long *b)
{
	ntt(a,1);
	ntt(b,1);
	for (int i=0;i<n;i++)
	{
		a[i]=a[i]*b[i]%Mod;
	}
	ntt(a,-1);
}
