const int maxN = 1 << 19;
const LL P = 924844033;
template<LL P, LL g>
struct FastFourierTransform {
    LL p[maxN], ip[maxN];
    int n, rev[maxN];
    LL qpow(LL a, LL b) {
        LL r = 1;
        while(b) {
            if(b & 1) (r *= a) %= P;
            (a *= a) %= P; b >>= 1;
        }
        return r;
    }
    void prepare(int n) {
        assert((n & (n - 1)) == 0);
        this->n = n;
        int width = 0;
        for(; (1 << width) < n; ++width);
        p[0] = ip[0] = 1;
        p[1] = qpow(g, (P - 1) / n); ip[1] = qpow(p[1], P - 2);
        for(int i = 2; i < n; ++i) p[i] = p[i - 1] * p[1] % P, ip[i] = ip[i - 1] * ip[1] % P;
        rev[0] = 0;
        for(int i = 1; i < n; ++i) rev[i] = rev[i >> 1] >> 1 | (i & 1) << (width - 1);
    }
    LL sum(LL x, LL y) { return x + y >= P ? x + y - P : x + y; }
    LL dif(LL x, LL y) { return x - y < 0 ? x - y + P : x - y; }
    void transform(LL a[], int n, int flag) {
        assert(flag == 1 || flag == -1);
        if(this->n != n) prepare(n);
        for(int i = 0; i < n; ++i) if(rev[i] < i) std::swap(a[i], a[rev[i]]);
        LL *wn = flag == 1 ? p : ip;
        for(int i = 1; i < n; i <<= 1) {
            int step = n / (i << 1);
