int pr(int a, int z) {
	int s = 1;
	while (z > 0) {
		if (z % 2 == 1) s = 1ll * s * a % mod;
		a = 1ll * a * a % mod;
		z /= 2;
	}
	return s;
}

void fft(int *a, int n, int ty) {
	for (int i = n >> 1, j = 1, k; j < n - 1; ++j) {
		if (i > j) swap(a[i], a[j]);
		for (k = n >> 1; k <= i; k >>= 1) i ^= k;
		i ^= k;
	}

	for (int m = 2; m <= n; m <<= 1) {
		int h = m >> 1, wm = pr(g, (mod - 1) / m * (ty == +1 ? 1 : (m - 1)));

		for (int i = 0; i < n; i += m) {
			int w = 1;
			for (int j = i; j < i + h; ++j) {
				int u = a[j], v = 1ll * w * a[j + h] % mod;
				a[j] = (u + v) % mod;
				a[j + h] = (u - v + mod) % mod;
				w = 1ll * w * wm % mod;
			}
		}
	}

	if (ty == -1) {
		int iv = pr(n, mod - 2);
		iter0(i, n) a[i] = 1ll * a[i] * iv % mod;
	}
}

void dfs(int x, int fa) {
	sz[x] = 1;
	for (int v : e[x]) if (v != fa) {
