inline int qpow(int a, int b) {
	static int res;
	for (res = 1; b; a = 1ll * a * a % mod, b >>= 1) 
		if (b & 1) res = 1ll * res * a % mod;
	return res;
}

inline void Init(int n) {
	fac[0] = inv[0] = 1;
	For(i, 1, n) fac[i] = 1ll * i * fac[i - 1] % mod;
	inv[n] = qpow(fac[n], mod - 2);
