	Fac[0] = Fac[1] = IFac[0] = IFac[1] = inv[0] = inv[1] = 1 ;
	for(int i = 2; i <= N; i ++) {
		Fac[i] = 1ll * i * Fac[i - 1] % mod ;
		inv[i] = 1ll * (mod - mod / i) * inv[mod % i] % mod ;
		IFac[i] = 1ll * IFac[i - 1] * inv[i] % mod ; 
	}
	return ;
}

IL void NTT(int *P , int op) {
	for(int i = 0; i < nn; i ++) if(rev[i] > i) swap(P[i] , P[rev[i]]) ;
	for(int i = 1,id = 0; i < nn; i <<= 1) {
		++ id ;
		for(int j = 0,p = (i << 1) ; j < nn ; j += p) {
			int w = 1 ;
			for(int k = 0; k < i; k ++, w = 1ll * w * wn[id] % mod) {
				int X = P[j + k] , Y = 1ll * w * P[j + k + i] % mod ;
				P[j + k] = (X + Y) % mod ;
				P[j + k + i] = (X - Y + mod) % mod ; 
			}
		}
	}if(op < 0) {
		for(int i = 1; i < nn / 2; i ++) swap(P[i] , P[nn - i]) ;
		int INV = Pow(nn , mod - 2) ;
		for(int i = 0; i < nn; i ++) P[i] = 1ll * P[i] * INV % mod ; 
	}return ; 
}

void Dfs(int u , int From) {
	sz[u] = 1 ;
	for(int e = head[u] ; e ; e = Edge[e].next) {
		int v = Edge[e].to ; if(v == From) continue ;
		Dfs(v , u) ;
		sz[u] = sz[u] + sz[v] ; cnt[sz[v]] = (cnt[sz[v]] + 1) % mod ; 
	}
	if(From) cnt[n - sz[u]] = (cnt[n - sz[u]] + 1) % mod ; 
	return ; 
}

