		int wn = flag ? powg[i] : invg[i];
		for (int j = 0; j < siz; j += i) {
			int w = 1;
			for (int k = 0; k < (i >> 1); ++ k, w = 1ll * w * wn % mod) {
				int x = a[j + k], y = 1ll * w * a[j + k + (i >> 1)] % mod;
				a[j + k] = (x + y) % mod, a[j + k + (i >> 1)] = (x - y + mod) % mod; 
			}
		}
	}
	if (!flag) {
		int g = qpow(siz, mod - 2);
		For(i, 0, siz - 1) a[i] = 1ll * g * a[i] % mod;
	}
}

