	for(int i = 0; i <= n; i++) b[i] = invf[n - i];
	vector<int> res = mul(a, b); // ans_k = [x^{k + n}]res
	while(res.size() <= n + n + 1) res.push_back(0);

	for(int i = 0; i <= n; i++) ans[i] = 1LL * res[i + n] * invf[i] % kMod;
	for(int i = 1; i <= n; i++) {
