	sz[u] = 1;
	for(int i = h[u];~ i;i = e[i].n) {
		int v = e[i].v;
		if(v == fa) continue;
		dfs1(v,u);
		sz[u] += sz[v];
	}
}

void dfs2(int u, int fa, int sum) {
