void FFT(cp *x,int op)
{
	int i,j,k; cp p,q,w,wn;
	for(i=0;i<e;i++) tmp[i]=x[i];
	for(i=0;i<e;i++) x[i]=tmp[rev(i)];
	for(i=1;i<=e;i<<=1){
		wn=cp(cos(2*Pi*op/i),sin(2*Pi*op/i));
		for(j=0;j<e;j+=i){
			w=cp(1,0);
			for(k=0;k<i/2;k++){
				p=x[j+k],q=x[j+k+i/2]*w;
				x[j+k]=p+q,x[j+k+i/2]=p-q;
				w=w*wn;
			  }
		  }
	  }
}
