    g[a].push_back(b);
    g[b].push_back(a);
  }
  dfs(0);
  fac(n);
  vector<int> ans=solve(0, n-1);
  for(ll i=1; i<n; i++){
    cout<<(comb(n, i)*(ll)n-(ll)ans[i]+MOD)%MOD<<endl;
  }
  cout<<n<<endl;
	return 0;
}

