int lim=1,len,pos[262145<<1],gpow[262145<<1],invp[262145<<1];
inline void NTT(int *A,int sign){
    for(reg int i=0;i<lim;i++)if(i<pos[i])swap(A[i],A[pos[i]]);
    for(reg int mid=1;mid<lim;mid<<=1){
        static int urt,rt,x,y;urt=(~sign)?gpow[mid<<1]:invp[mid<<1];
