    for(reg int i=1;i<=lim;i<<=1)invp[i]=qpow(Inv,(p-1)/i);
    for(reg int i=0;i<lim;i++)pos[i]=(pos[i>>1]>>1)|((i&1)<<(len-1));
    NTT(A,1);NTT(B,1);for(reg int i=0;i<=lim;i++)A[i]=1ll*A[i]*B[i]%p;
    NTT(A,-1);for(reg int i=1;i<=n;i++)ans[i]=(1ll*inv[i]*A[n-i]%p+p)%p;
    for(reg int i=1;i<=n;i++)IO::write(ans[i]),IO::pc('\n');
    IO::end();
    return 0;
}

