	fac[0] = inv[0] = 1;
	For(i, 1, n) fac[i] = 1ll * i * fac[i - 1] % mod;
	inv[n] = qpow(fac[n], mod - 2);
	Forr(i, n - 1, 0) inv[i] = 1ll * inv[i + 1] * (i + 1) % mod;
}

