Poly operator * (Poly A, Poly B)
{
    int n = A.ti(), m = B.ti(); 
    if(n <= 128||m <= 128)
    {
        Poly C; C.set(n+m);
        int *c = &C[0], *a = &A[0], *b = &B[0];
        for(int i = 0; i <= n; ++i)
        {
