            for(int j = 0; j <= m; ++j) f[j] = (f[j]+x*b[j]%P)%P;
        }
        return C;
    }
    prepare(n+m), NTT(A, 0), NTT(B, 0);
    for(int i = 0; i < lim; ++i) A[i] = 1ll*A[i]*B[i]%P;
    NTT(A, 1); A.set(n+m);
