        j --;
        for (int k = 1; k <= j; k++)
        {
            ans[k] = ((long long) ans[k] - 1LL * ap[i] * (comb (j + 1, k + 1) - comb (i, k + 1))) % mod;
            if (ans[k] < 0) ans[k] += mod;
        }
        i = j;
    }
for (int i=1; i<=N; i++)
    printf ("%d\n", ans[i]);
return 0;
}

