	rep(i,0,N){
		int j=i?N-i:0;
		t[i]=(!f[j]-f[i])*(!g[j]-g[i])*(cp){-0.25,0}+(cp){0,0.25}*(f[i]+!f[j])*(g[i]+!g[j]);
	}
	dft(t,N,-1);
	rep(i,0,n+m+1)upmo(c[i],ll(t[i].a+0.5)+(ll(t[i].b+0.5)%mo<<30));
}
