inline void chk(ll &a){if(a<0)a+=md;}

inline ll qpow(ll a,ll b)
{
	ll ret=1ll;
	while(b)
	{
		if(b&1ll)
			ret=ret*a%md;
		a=a*a%md;
		b>>=1;
	}
	return ret;
}

