			chk(--a[siz[to[i]]]);
		}
	chk(--a[n-siz[u]]);
}

inline void NTT(ll *a,int n,bool f)
{
	for(int i=0;i<n;i++)
		if(i<rev[i])
			swap(a[i],a[rev[i]]);
	for(int h=2;h<=n;h<<=1)
	{
		ll w=qpow(5,(md-1)/h);
		if(f)w=qpow(w,md-2);
		for(int j=0;j<n;j+=h)
		{
			ll wn=1;
			for(int k=j;k<j+(h>>1);k++)
			{
				ll x=a[k],y=wn*a[k+(h>>1)]%md;
				a[k]=(x+y)%md;
				a[k+(h>>1)]=(x-y+md)%md;
				wn=wn*w%md;
			}
		}
	}

	if(f)
		for(ll i=0,invn=qpow(n,md-2);i<n;i++)
			a[i]=a[i]*invn%md;
}

