namespace ModCalc{
	In void Inc(ll &x,ll y){
		x += y;if(x >= mod)x -= mod;
	}
	In void Dec(ll &x,ll y){
		x -= y;if(x < 0)x += mod;
	}
	In ll Add(ll x,ll y){
		Inc(x,y);return x;
	}
	In ll Sub(ll x,ll y){
		Dec(x,y);return x;
	}
}
using namespace ModCalc;

//polycalc
ll power(ll a,ll n){
	ll s = 1,x = a;
	while(n){
		if(n & 1)s = s * x % mod;
		x = x * x % mod;
		n >>= 1;		
	}
	return s;
}

int bit_rev[N+5];
ll p[N+5],jc[N+5],iv[N+5];

void NTT(ll a[],int deg,int L,int opt){
	for(rg int i = 1;i < deg;i++){
		bit_rev[i] = (bit_rev[i>>1]>>1) ^ ((i&1)<<(L-1));
		if(i < bit_rev[i])swap(a[i],a[bit_rev[i]]);
	}
	int x = opt == 1 ? g : vg;
	for(rg int n = 2;n <= deg;n <<= 1){
		int m = n >> 1;
		ll wm = power(x,(mod-1) / n);
		for(rg int i = 0;i < deg;i += n){
			ll w = 1;
			for(rg int j = 0;j < m;j++,w = w * wm % mod){
				ll u = a[i+j],v = a[i+j+m] * w % mod;
				a[i+j] = Add(u,v);
				a[i+j+m] = Sub(u,v);
			}
		}
	}
	if(opt == -1){
		ll inv = power(deg,mod - 2);
		for(rg int i = 0;i < deg;i++)a[i] = a[i] * inv % mod;
	}
}

ll f[N+5],c[N+5];

void prepro(){
	jc[0] = 1;
	for(rg int i = 1;i <= N;i++)jc[i] = jc[i-1] * i % mod;
	iv[N] = power(jc[N],mod - 2);
	for(rg int i = N - 1;i >= 0;i--)iv[i] = iv[i+1] * (i + 1) % mod;
}

//tree
vector<int>E[N+5];
int sz[N+5];
int n;

void dfs(int u,int fa){
	sz[u] = 1;
	for(rg int i = 0;i < E[u].size();i++){
		int v = E[u][i];
		if(v == fa)continue;		
		dfs(v,u);
		sz[u] += sz[v];
	}
	if(u != 1){
		Dec(p[sz[u]],1);
		Dec(p[n-sz[u]],1);
		p[n]++;
	}
}

