const int M = 924844033;
const int FFT_G = 5;

inline int modpow(int a, const int &n)
{
	int res = 1;
	for (int i = n; i; i >>= 1)
	{
		if (i & 1)
			res = (s64)res * a % M;
		a = (s64)a * a % M;
	}
	return res;
}

inline int add(int a, const int &b)
{
	a += b;
	return a >= M ? a - M : a;
}
inline int dec(int a, const int &b)
{
	a -= b;
	return a < 0 ? a + M : a;
}

int tn, tl, inv;
int bitRev[MaxTN];
int root[MaxTN];

inline void fft_init(int n)
{
	tn = 1, tl = 0;
	while (tn < n)
		tn <<= 1, ++tl;
	inv = modpow(tn, M - 2);

	for (int i = 1; i < tn; ++i)
	{
		int l = bitRev[i >> 1] >> 1;
		bitRev[i] = l | ((i & 1) << tl - 1);
	}

	int bn = tn >> 1;
	root[bn + 0] = 1;
	root[bn + 1] = modpow(FFT_G, (M - 1) / tn);
	for (int i = 2; i < bn; ++i)
		root[bn + i] = (s64)root[bn + i - 1] * root[bn + 1] % M;
	for (int i = bn - 1; i > 0; --i)
		root[i] = root[i << 1];
}

inline void fft(int *a, int type)
{
	if (type)
		reverse(a + 1, a + tn);

	for (int i = 0; i < tn; ++i)
	{
		int r = bitRev[i];
		if (i < r)
			swap(a[i], a[r]);
	}

	for (int k = 1; k < tn; k <<= 1)
	{
		int *g = root + k;
		for (int s = 0; s < tn; s += k << 1)
		{
			int *w = g;
			for (int i = s; i < s + k; ++i, ++w)
			{
				int o = a[i], e = (s64)a[i + k] * *w % M;
				a[i] = add(o, e);
				a[i + k] = dec(o, e);
			}
		}
	}

	if (type)
	{
		for (int i = 0; i < tn; ++i)
			a[i] = (s64)a[i] * inv % M;
	}
}

inline void polymul(int *a, int *b, int n)
{
	fft_init(n + n + 1);

	fft(a, 0);
	fft(b, 0);
	for (int i = 0; i < tn; ++i)
		a[i] = (s64)a[i] * b[i] % M;
	fft(a, 1);
}

