namespace fft {
#define NTT
const int mod = 998244353; // 2^23 * 119 + 1
const int gen = 3; // ord(3) = 2^23 * 119
vector<int> rev(1, 0), roots; // rev has [base] bits
int base = 0;
void precompute(int nbase) {
	if (nbase <= base) return;
	rev.resize(1 << nbase);
	for (int i = 0; i < (1 << nbase); ++i) {
		rev[i] = rev[i >> 1] >> 1 | ((i & 1) << nbase - 1);
	}
	roots.resize(1 << nbase);
	for (; base < nbase; ++base) {
		int len = 1 << base;
		ll root = modex(gen, (mod - 1) >> base + 1, mod);
		roots[len] = 1;
		for (int i = 1; i < len; ++i) roots[len + i] = roots[len + i - 1] * root % mod;
	}
}
void fft(vector<int>& a) {
	int n = a.size();
	assert((n & (n - 1)) == 0);
	int zeros = __builtin_ctz(n);
	precompute(zeros);
	int shift = base - zeros;
	for (int i = 0; i < n; ++i) {
		if (i < (rev[i] >> shift)) swap(a[i], a[rev[i] >> shift]);
	}
	for (int len = 1; len < n; len <<= 1)
		for (int i = 0; i < n; i += 2 * len)
			for (int j = 0; j < len; ++j) {
				int u = a[i + j], v = (ll)a[i + j + len] * roots[len + j] % mod;
				a[i + j] = u + v >= mod ? u + v - mod : u + v;
				a[i + j + len] = u - v < 0 ? u - v + mod : u - v;
			}
}
vector<int> multiply(vector<int> a, vector<int> b) {
	if (a.empty() || b.empty()) return {};
	int sz = a.size() + b.size() - 1;
	int n = sz == 1 ? 1 : 1 << (32 - __builtin_clz(sz - 1));
	bool eq = (a == b);
	a.resize(n);
	fft(a);
	if (eq) b = a;
	else {
		b.resize(n);
		fft(b);
	}
	ll inv = modex(n, mod - 2, mod);
	for (int i = 0; i < n; ++i) a[i] = (ll)a[i] * b[i] % mod * inv % mod;
	fft(a);
	reverse(a.begin() + 1, a.end());
	a.resize(sz);
	return a;
}
vector<int> multiply(const vector<int>& a, const vector<int>& b, int m) {
	assert(m == mod);
	return multiply(a, b);
}
