struct Mod
{
    static const auto P = 924844033;
    static const auto primitive_root = 116636802;
    static const auto log = 19;
    long long k;

    Mod() = default;
    Mod(const long long k) : k(k%P) {}
};

Mod operator+(const Mod a, const Mod b) { return a.k + b.k; }
Mod operator-(const Mod a, const Mod b) { return a.k - b.k + Mod::P; }
Mod operator*(const Mod a, const Mod b) { return a.k * b.k; }
Mod power(const Mod a, const int k)
{
    if (k == 0) return 1;
    else if (k % 2 == 0) return power(a*a, k/2);
    else return a * power(a*a, k/2);
}
Mod inverse(const Mod a) { return power(a, Mod::P-2); }
Mod& operator*=(Mod& a, const Mod b) { return a = a*b; }

namespace bit
{
    bool test(const int mask, const int k) { return mask & 1<<k; }
    int set(const int mask, const int k) { return mask | 1<<k; }
}

struct NTT
{
    int N;
    Mod N_inverse;
    vector<int> reverses;
    vector<Mod> roots;

    NTT() : N(1<<Mod::log), N_inverse(inverse(N)), reverses(N), roots(N/2)
    {
        for (auto i = 0; i < N; i++)
            for (auto k = 0; k < Mod::log; k++) if (bit::test(i, k))
                reverses[i] = bit::set(reverses[i], Mod::log-1-k);

        roots[0] = 1;
        for (auto i = 1; i < N/2; i++)
            roots[i] = roots[i-1] * Mod::primitive_root;
    }

    vector<Mod> transform(vector<Mod> a) const
    {
        for (auto i = 0; i < N; i++) if (i < reverses[i])
            swap(a[i], a[reverses[i]]);

        for (auto length = 2; length <= N; length *= 2)
        {
            const auto generator = N / length;
            for (auto i = 0; i < N; i += length)
            {
                auto l = begin(a)+i, r = begin(a)+i+(length/2);
                auto root = begin(roots);
                for (auto j = 0; j < length/2; j++)
                {
                    const auto u = *l, v = *root * *r;
                    *l = u + v;
                    *r = u - v;
                    l++, r++, root += generator;
                }
            }
        }

        return a;
    }

    vector<Mod> inverse_transform(vector<Mod> a) const
    {
        a = transform(move(a));
        for (auto& x : a) x *= N_inverse;
        reverse(begin(a)+1, end(a));
        return a;
    }

    vector<Mod> convolve(vector<Mod> a, vector<Mod> b) const
    {
        const auto Fa = transform(move(a));
        const auto Fb = transform(move(b));

        auto Fc = vector<Mod>(N);
        for (auto i = 0; i < N; i++)
            Fc[i] = Fa[i] * Fb[i];

        return inverse_transform(move(Fc));
    }
};

struct Tree
{
