        ans[i] = 1LL * comb(n,i+1) * n % MOD;
    }
    vector<int> v; for(int i=1;i<=n;i++) v.push_back(sz[i]); getAns(v);
    v.clear();   for(int i=1;i<=n;i++) v.push_back(n-sz[i]); getAns(v);
    for(int i=0;i<n;i++)  printf("%d\n", ans[i]);
}

