LL qpow(LL a, LL b)
{
    LL ret = 1, base = a;
    while (b) {
        if (b & 1) ret = ret * base % mod;
        base = base * base % mod, b >>= 1;
    }
    return ret;
}

void NTT(LL *a, int len, int f)
{
    for (int i = 0, j = 0; i < len; i ++) {
        if (i < j) swap(a[i], a[j]);
        for (int t = len >> 1; (j ^= t) < t; t >>= 1);
    }
    for (int i = 1; i < len; i <<= 1) {
        LL wn = f ? qpow(G, (mod - 1) / (i << 1)) : qpow(G, (mod - 1) - (mod - 1) / (i << 1));
        for (int j = 0; j < len; j += (i << 1)){
            LL w = 1;
            for (int k = 0; k < i; k ++, w = w * wn % mod){
                LL x = a[j + k], y = w * a[j + k + i] % mod;
                a[j + k] = (x + y) % mod;
                a[j + k + i] = (x - y + mod) % mod;
            }
        }
    }
    if (!f) for (int i = 0; i < len; i ++) a[i] = a[i] * qpow(len, mod - 2) % mod;
}

