template<int _MOD>
class ModInt {
public:
	static const int Mod = _MOD;

private:
	unsigned x;

public:
	ModInt() : x(0) {}
	ModInt(int sig) { int sigt = sig % Mod; if (sigt < 0) sigt += Mod; x = sigt; }
	ModInt(long long sig) { int sigt = sig % Mod; if (sigt < 0) sigt += Mod; x = sigt; }
	int get() const { return (int)x; }

	ModInt &operator+=(const ModInt& b) { if ((x += b.x) >= Mod) x -= Mod; return *this; }
	ModInt &operator-=(const ModInt& b) { if ((x += Mod - b.x) >= Mod) x -= Mod; return *this; }
	ModInt &operator*=(const ModInt& b) { x = (unsigned long long)x * b.x % Mod; return *this; }
	ModInt &operator/=(const ModInt& b) { return *this *= b.inverse(); }

	friend ModInt operator+ (const ModInt& a, const ModInt& b) { return ModInt(a) += b; }
	friend ModInt operator- (const ModInt& a, const ModInt& b) { return ModInt(a) -= b; }
	friend ModInt operator* (const ModInt& a, const ModInt& b) { return ModInt(a) *= b; }
	friend ModInt operator/ (const ModInt& a, const ModInt& b) { return ModInt(a) /= b; }
	friend bool operator== (const ModInt& a, const ModInt& b) { return a.get() == b.get(); }
	friend bool operator!= (const ModInt& a, const ModInt& b) { return a.get() != b.get(); }

	friend std::ostream& operator<<(std::ostream& ostr, const ModInt & a) { return ostr << a.get(); }
	friend std::istream& operator >> (std::ostream& istr, const ModInt & a) { long long t; if (istr >> t) a = t; return istr; }

	ModInt pow(unsigned long long p) const {
		ModInt a = *this;
		ModInt rst = 1;
		while (p) {
			if (p & 1) rst *= a;

			p >>= 1;
			a *= a;
		}
		return rst;
	}

	ModInt inverse() const {
		signed a = x, b = Mod, u = 1, v = 0;
		while (b) {
			signed t = a / b;
			a -= t * b; std::swap(a, b);
			u -= t * v; std::swap(u, v);
		}
		return ModInt(u);
	}
};

template<typename Type>
class FFT {
public:
	const int n;
	const Type w;

public:
	FFT(int n, Type w) : n(n), w(w) {
		assert(n > 0);
		Type wk = (Type)1;
		for (int i = 1; i < n; ++i) {
			wk *= w;
			assert(wk != (Type)1);
		}
		assert(wk * w == (Type)1);
		for (--n; n; n >>= 1) assert(n & 1);
	}

	void calc(std::vector<Type>& rst, const std::vector<Type>& p, int ope = 1) {
		assert(p.size() <= n);
		rst = p;

		calc(rst, inv);
	}

	void calc(vector<Type>& p, int ope = 1) {
		assert((int)p.size() <= n);
		p.resize(n, 0);

		Type ww = ope > 0 ? w : 1 / w;
		for (int m = n, mi = 0; m >= 2; m >>= 1, mi++) {
			int mh = m >> 1;

			Type wc = (Type)1;
			for (int i = 0; i < mh; ++i) {
				for (int j = i; j < n; j += m) {
					int k = j + mh;
					Type tmp = p[j] - p[k];
					p[j] += p[k];
					p[k] = wc * tmp;
				}
				wc *= ww;
			}
			ww *= ww;
		}
		int i = 0;
		for (int j = 1; j < n - 1; ++j) {
			for (int k = n >> 1; k >(i ^= k); k >>= 1);
			if (j < i) std::swap(p[i], p[j]);
		}
	}
};

