#include<bits/stdc++.h>
using namespace std;

const int R = 5, A = 441, B = 21;
const int mod = A * (1 << B) + 1;
const int MN = 200010;

int exp(int x, int n) {
    int ret = 1;
    while(n) {
        if(n & 1) ret = 1LL * ret * x % mod;
        x = 1LL * x * x % mod;
        n >>= 1;
    }
    return ret;
}
int inv(int x) {
    return exp(x, mod - 2);
}
int fact[MN], invf[MN];
int comb(int n, int k) {
    return 1LL * fact[n] * invf[k] % mod * invf[n - k] % mod;
}

void ntt(vector<int> &a, bool invert) {
    int n = a.size();
    for(int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for(;j >= bit; bit >>= 1) j -= bit;
        j += bit;
        if(i < j) swap(a[i], a[j]);
    }
    for(int len = 2; len <= n; len <<= 1) {
        int wlen = exp(invert? inv(R) : R, A * (1 << B) / len);
        for(int i = 0; i < n; i += len) {
            int w = 1;
            for(int j = 0; j < len / 2; j++) {
                int u = a[i + j], v = 1LL * a[i + j + len / 2] * w % mod;
                a[i + j] = (u + v) % mod;
                a[i + j + len / 2] = (u + mod - v) % mod;
                w = 1LL * w * wlen % mod;
            }
        }
    }
    if(invert) {
        int x = inv(n);
        for(int i = 0; i < n; i++) a[i] = 1LL * a[i] * x % mod;
    }
}
void multiply(vector<int> &a, vector<int> &b) {
    int n = 1;
    while(n < max(a.size(), b.size())) n <<= 1;
    n <<= 1;
    a.resize(n); ntt(a, false);
    b.resize(n); ntt(b, false);
