const int mod = 924844033;
void Inc(int &x, int y) { x += y, x -= x >= mod ? mod : 0; }
void Dec(int &x, int y) { x -= y, x += x < 0 ? mod : 0; }
int inc(int x, int y) { return x + y >= mod ? x + y - mod : x + y; }
int dec(int x, int y) { return x < y ? x - y + mod : x - y; }
int mul(int x, int y) { return 1LL * x * y % mod; }
int fastpow(int base, int x) {
  int res = 1;
  while (x) {
    if (x & 1) res = mul(res, base);
    base = mul(base, base), x >>= 1;
  }
  return res;
}

namespace Poly {
const int G = 5, IG = 554906420;
int lim, tim, rev[maxn << 3];
void init(int N) {
  lim = 1, tim = rev[0] = 0;
  while (lim <= N) lim <<= 1, tim++;
  for (int i = 0; i < lim; i++)
    rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (tim - 1));
}
void NTT(poly &arr, int type) {
  for (int i = 0; i < lim; i++)
    if (i < rev[i]) swap(arr[i], arr[rev[i]]);
  for (int mid = 1; mid < lim; mid <<= 1) {
    int Wn = fastpow(type == 1 ? G : IG, (mod - 1) / (mid << 1));
    for (int j = 0; j < lim; j += (mid << 1)) {
      for (int k = 0, w = 1; k < mid; k++, w = mul(w, Wn)) {
        int x = arr[j + k], y = mul(arr[j + k + mid], w);
        arr[j + k] = inc(x, y);
        arr[j + k + mid] = dec(x, y);
      }
    }
  }
  if (type == -1) {
    int Ny = fastpow(lim, mod - 2);
    for (int i = 0; i < lim; i++) arr[i] = mul(arr[i], Ny);
  }
}
poly operator*(poly f, poly g) {
  int len_f = f.size(), len_g = g.size();
  init(len_f - 1 + len_g - 1);
  f.resize(lim, 0), NTT(f, 1);
  g.resize(lim, 0), NTT(g, 1);
  for (int i = 0; i < lim; i++) f[i] = mul(f[i], g[i]);
  NTT(f, -1), f.resize(len_f + len_g - 1);
  return f;
}
