		if(i < rev[i]) 
			swap(a[i], a[rev[i]]);
	for(int limit = 2; limit <= n; limit <<= 1) {
		int Wn = qpow(fh == 1 ? 5 : Inv(5), (mod - 1) / limit), W = 1;
		for(int j = 0; j < n; j += limit, W = 1)
			for(int i = j; i < j + (limit >> 1); ++ i, W = (ll)W * Wn % mod) {
