lint power(lint a, int b) {
    lint res = 1;
    while (b) {
        if (b & 1)
            res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void NTT(lint* a, int n, int opt) {
    for (int i = 0; i < n; ++i)
        if (i < r[i])
            swap(a[i], a[r[i]]);
    for (int i = 1; i < n; i <<= 1) {
        lint gn = power(opt == 1 ? G : power(G, mod - 2), (mod - 1) / (i << 1));
        for (int j = 0; j < n; j += (i << 1)) {
            lint g = 1;
            for (int k = 0; k < i; ++k) {
                lint x = a[j + k], y = a[j + k + i] * g % mod;
                a[j + k] = (x + y) % mod;
                a[j + k + i] = (x - y + mod) % mod;
                g = g * gn % mod;
            }
        }
    }
    if (opt == -1) {
        lint inv = power(n, mod - 2);
        for (int i = 0; i < n; ++i)
            a[i] = inv * a[i] % mod;
    }
}

int getr(int n) {
    int limit = 1, size = 0;
    while (limit <= n) {
        limit <<= 1;
        ++size;
    }
    for (int i = 0; i < limit; ++i)
        r[i] = (r[i >> 1] >> 1) | ((i & 1) << (size - 1));
    return limit;
}

void init() {
    inf[0] = fac[0] = 1;
    for (int i = 1; i <= n; ++i)
        fac[i] = fac[i - 1] * i % mod;
    inf[n] = power(fac[n], mod - 2);
    for (int i = n - 1; i >= 1; --i)
        inf[i] = inf[i + 1] * (i + 1) % mod;
}

lint C(int n, int m) {
    return fac[n] * inf[n - m] % mod * inf[m] % mod;
}

