const int mod=924844033;
struct cpl{
	db a,b;
	cpl () {}
	cpl (db aa,db bb) {a=aa; b=bb;}
	cpl operator + (const cpl &B) { return cpl(a+B.a,b+B.b); }
	cpl operator - (const cpl &B) { return cpl(a-B.a,b-B.b); }
	cpl operator * (const cpl &B) { return cpl(a*B.a-b*B.b,a*B.b+B.a*b); }	
}A[N],B[N],C[N],a[N];
struct large{
	ll n,d[N];
	int pos(int x,int k)
	{
		int i,ret=0;
		rep(i,0,k-1)
			if (x&(1<<i)) ret+=1<<(k-i-1);
		return ret;
	}
	void FFT(cpl *A,int K,int sgn)
	{
		int len=1<<K,i,j,l,k,m;
		cpl bsc,w,L,R;
		rep(i,0,len-1) a[pos(i,K)]=A[i];
		for (k=2;k<=len;k<<=1)
		{
			bsc=cpl(cos(2*PI/k),sgn*sin(2*PI/k));
			m=k>>1;
			for (l=0;l<len;l+=k)
			{
				w=cpl(1.0,0);
				rep(i,0,m-1)
				{
					L=a[l+i]; R=a[l+m+i];
					a[l+i]=L+w*R;
					a[l+i+m]=L-w*R;
					w=w*bsc;
				}
			}
		}
		rep(i,0,len-1)
			if (sgn==1) A[i]=a[i];
			else A[i]=cpl((a[i].a+0.5)/len,0);
	}
	void mult(const large &Y,large &ret)
	{
		int i,k,len=n+Y.n-1;
		for (k=0;(1<<k)<len;k++);
		len=1<<k;
		rep(i,0,len-1) A[i]=B[i]=cpl(0,0);
		rep(i,0,n-1) A[i]=cpl(d[i],0);
		rep(i,0,Y.n-1) B[i]=cpl(Y.d[i],0);
		FFT(A,k,1);
		FFT(B,k,1);
		rep(i,0,len-1) C[i]=A[i]*B[i];
		FFT(C,k,-1);
		ret.n=len;
		rep(i,0,len-1) ret.d[i]=((ll)C[i].a)%mod;
	}
}x,y,z;
int n,i,u,v,size[N];
int En,fst[N],nxt[N*2],to[N*2];
ll num[N],fac[N],inv[N];
ll fgm(ll a,int n)
{
	ll ret=1,bsc=a;
	for (;n>0;n>>=1,bsc=bsc*bsc%mod)
	if (n&1) ret=ret*bsc%mod;
	return ret;
}
