#include <bits/stdc++.h>

const int MAXN = 524289;
const int mod = 998244353;
typedef long long LL;
void reduce(int & x) { x += x >> 31 & mod; }
int mul(int a, int b) { return (LL) a * b % mod; }
int pow(int a, int b, int res = 1) {
	for (; b; b >>= 1, a = mul(a, a)) if (b & 1) res = mul(res, a);
	return res;
}
int remod(LL x) { x %= mod; return x + (x >> 63 & mod); }

int wn[MAXN], wt[MAXN], rev[MAXN], lim, dig;
void init(int sz) {
	lim = 1, dig = -1;
	while (lim < sz) lim <<= 1, ++dig;
	for (int i = 0; i < lim; ++i) rev[i] = rev[i >> 1] >> 1 | (i & 1) << dig;
	const int W = pow(5, (mod - 1) / lim); *wn = 1;
	for (int i = 1; i <= lim; ++i) wn[i] = mul(wn[i - 1], W);
}
void NTT(int * A, int typ) {
	for (int i = 0; i < lim; ++i) if (i < rev[i]) std::swap(A[i], A[rev[i]]);
	for (int mid = 1; mid != lim; mid <<= 1) {
		const int Wn = lim / mid / 2;
		for (int i = 0, W = 0; i != mid; ++i, W += Wn)
			wt[i] = wn[typ == 1 ? W : lim - W];
		for (int k = 0; k != lim; k += mid << 1) {
			const int * W = wt;
			for (int l = 0; l != mid; ++l) {
				const int X = A[l + k], Y = mul(A[l + k + mid], *W++);
				reduce(A[l + k] = X + Y - mod);
				reduce(A[l + k + mid] = X - Y);
			}
		}
	}
	if (typ == -1) {
		const int liminv = pow(lim, mod - 2);
		for (int i = 0; i != lim; ++i) A[i] = mul(A[i], liminv);
	}
}

int A[MAXN], B[MAXN], n;
int head[MAXN], nxt[MAXN << 1], to[MAXN << 1], tot;
void addedge(int b, int e) {
	nxt[++tot] = head[b]; to[head[b] = tot] = e;
	nxt[++tot] = head[e]; to[head[e] = tot] = b;
}
int dfs(int u, int fa = 0) {
	int sz = 1;
	for (int i = head[u]; i; i = nxt[i])
		if (to[i] != fa)
			sz += dfs(to[i], u);
	if (fa) ++A[sz], ++A[n - sz];
	return sz;
}
int fac[MAXN], inv[MAXN];
int C(int a, int b) { return (LL) fac[a] * inv[b] % mod * inv[a - b] % mod; }
int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	fac[0] = fac[1] = inv[0] = inv[1] = 1;
	for (int i = 2; i != MAXN; ++i) {
		fac[i] = mul(fac[i - 1], i);
		inv[i] = mul(inv[mod % i], mod - mod / i);
	}
	for (int i = 2; i != MAXN; ++i) inv[i] = mul(inv[i - 1], inv[i]);
	std::cin >> n;
	for (int i = 1, t1, t2; i < n; ++i)
		std::cin >> t1 >> t2, addedge(t1, t2);
	dfs(1);
	for (int i = 0; i <= n; ++i)
		B[i] = inv[n - i], A[i] = mul(A[i], fac[i]);
	init(n * 2 + 1);
	NTT(A, 1); NTT(B, 1);
	for (int i = 0; i != lim; ++i) A[i] = mul(A[i], B[i]);
	NTT(A, -1);
	for (int i = 1; i <= n; ++i) {
		int t = 0;
		reduce(t -= mul(A[i + n], inv[i]));
		reduce(t += mul(C(n, i), n) - mod);
		std::cout << t << '\n';
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int mod = 924844033;
const int N = 2e5 + 11;
int f[N<<2], g[N<<2], fac[N], inv[N];
int n, sz[N], size, head[N], to[N<<1], nex[N<<1];
int lim, len = 1, rev[N<<2];
void add(int x, int y){
    to[++size] = y;
    nex[size] = head[x];
    head[x] = size;
}
int M(int x, int y){
    return x + y - (x + y >= mod ? mod : 0);
}
int C(int n, int m){
    if(n < m)return 0;
    return 1LL * fac[n] * inv[m] % mod * inv[n-m] % mod;
}
void get(){
    for(int i = 1;i < len; i++){
        rev[i] = (rev[i>>1] >> 1) | ((i & 1) << (lim - 1));
    }
}
int ksm(int base, int x){
    int ans = 1;
    while(x){
        if(x & 1)ans = 1LL * ans * base % mod;
        base = 1LL * base * base % mod;
        x >>= 1;
    }
    return ans;
}
void NTT(int *x, int fl){
    for(int i = 0;i < len; i++)if(rev[i] > i)swap(x[i], x[rev[i]]);
    for(int i = 1;i < len; i <<= 1){
        int g0 = ksm(5, (mod - 1) / (i << 1));
        if(fl == -1)g0 = ksm(g0, mod - 2);
        for(int j = 0;j < len; j += i << 1){
            for(int k = 0, gn = 1;k < i; k++){
                int x0 = x[j+k], x1 = 1LL * x[j+k+i] * gn % mod;
                x[j+k] = M(x0, x1);
                x[j+k+i] = M(x0, mod - x1);
                gn = 1LL * gn * g0 % mod;
            }
        }
    }
    if(fl == -1){
        int ni = ksm(len, mod - 2);
        for(int i = 0;i < len; i++)x[i] = 1LL * x[i] * ni % mod;
    }
}
void work(){
    while(len < 2 * n + 1)len <<= 1, lim++;
    get();
    //printf("len=%d lim=%d\n", len, lim);
    NTT(f, 1); NTT(g, 1);
    for(int i = 0;i < len; i++){
        f[i] = 1LL * f[i] * g[i] % mod;
    }
    NTT(f, -1);
    puts("");
    //for(int i = 0;i < len; i++)printf("i=%d f=%d\n", i, f[i]);
    for(int i = 1;i <= n; i++)f[i+n] = M(mod - 1LL * inv[i] * f[i+n] % mod , 1LL * n * C(n, i) % mod);
}
void dfs(int u, int fa){
    sz[u] = 1;
    //printf("u=%d fa=%d\n", u, fa);
    for(int i = head[u];i;i = nex[i]){
        int v = to[i];
        //printf("u=%d v=%d\n", u, v);
        if(v == fa)continue;
        dfs(v, u);
        sz[u] += sz[v];
    }
    if(u != fa)f[sz[u]]++, f[n-sz[u]]++;
    //printf("sz=%d n-sz=%d u=%d fa=%d\n", sz[u], n - sz[u], u, fa);
}
int main(){
    cin>>n;
    int u, v;
    for(int i = 1;i < n; i++){
        scanf("%d%d", &u, &v);
        add(v, u); add(u, v);
    }
    fac[0] = fac[1] = inv[1] = inv[0] = 1;
    for(int i = 2;i <= 2e5; i++){
        fac[i] = 1LL * fac[i-1] * i % mod;
        inv[i] = (mod - 1LL * mod / i * inv[mod%i] % mod) % mod;
    }
    g[0] = 1;
    for(int i = 1;i <= n; i++){
        inv[i] = 1LL * inv[i-1] * inv[i] % mod;
        g[i] = inv[i];
    }
    reverse(g, g + 1 + n);
    dfs(1, 1);
    for(int i = 0;i <= n; i++){
        f[i] = 1LL * f[i] * fac[i] % mod;
        //printf("i=%d f=%d g=%d\n", i, f[i], g[i]);
    }
    work();
    for(int i = 1;i <= n; i++)printf("%d\n", f[n+i]);
    return 0;
}

