typedef vector<int> Poly;
inline int Add(int x,int y){x+=y;return x>=P?x-P:x;}
inline int Dec(int x,int y){x-=y;return x<0?x+P:x;}
inline int Mul(int x,int y){return 1ll*x*y%P;}
int ksm(int a,int b){
	int ans=1;
	for(;b;b>>=1,a=Mul(a,a)) if(b&1) ans=Mul(ans,a);
	return ans;
}
void DFT(Poly &a,int k){
	rep(i,0,N-1){
		r[i]=(i&1)?(r[i^1]|(1<<l-1)):(r[i>>1]>>1);
		if(i<r[i]) swap(a[i],a[r[i]]);
	}
	for(int mid=1;mid<N;mid<<=1){
		int wn=ksm(k==1?G:iG,(P-1)/(mid<<1));
		for(int R=mid<<1,j=0;j<N;j+=R){
			int w=1,*l=&a[j],*r=&a[j+mid];
			for(int k=0;k<mid;++k,++l,++r,w=Mul(w,wn)){
				int x=*l,y=Mul(*r,w);
				*l=Add(x,y);*r=Dec(x,y);
			}
		}
	}
	if(k==-1){
		int inv=ksm(N,P-2);
		rep(i,0,N-1) a[i]=Mul(a[i],inv);
	}
}
Poly operator *(Poly a,Poly b){
	int n=a.size()+b.size()-1;
	for(N=1,l=0;N<=n;N<<=1,l++);a.resize(N);b.resize(N);
	DFT(a,1);DFT(b,1);
	rep(i,0,N-1) a[i]=Mul(a[i],b[i]);
	DFT(a,-1);a.resize(n);
	return a;
}
void pre(int n){
	fac[0]=1;
	rep(i,1,n) fac[i]=Mul(fac[i-1],i);
	ifac[n]=ksm(fac[n],P-2);
	per(i,n-1,0) ifac[i]=Mul(ifac[i+1],i+1);
}Poly a,b;
