	for(int v:H[u]) if(v^fa) dfs(v,u),sz[u]+=sz[v],++a[sz[v]];
	++a[n-sz[u]];
}
inline int C(int n,int k){return Mul(fac[n],Mul(ifac[k],ifac[n-k]));}
