  x += a;
  if (x >= MOD) {
    x -= MOD;
  }
}

int inv(int a) {
  return a == 1 ? 1 : static_cast<int64_t>(MOD - MOD / a) * inv(MOD % a) % MOD;
}

int dfs(int p, int u) {
  int size = 1;
  for (int v : tree[u]) {
    if (v != p) {
      int subsize = dfs(u, v);
      add(count[subsize], MOD - 1);
      add(count[n - subsize], MOD - 1);
      size += subsize;
    }
  }
  return size;
}

