void build(int x, int l, int r, int *px)
{
    if(l == r) return (void)(H[x].set(1), H[x][0] = P-px[l], H[x][1] = 1);
    int mid = (l+r)>>1; build(x<<1, l, mid, px), build(x<<1|1, mid+1, r, px);
    H[x] = H[x<<1]*H[x<<1|1];
}
void solve(int x, int l, int r, int* px, int* py, Poly F)
{
    if(r-l+1 <= 512)
    {
        int n = F.ti(), *f = &F[0];
        for(int k = l; k <= r; ++k)
        {
            int64 x = px[k], y = 0;
            for(int i = n; ~i; --i) y = (y*x%P+f[i])%P;
            py[k] = y;
        }
