int Pow(int a, int k)
{
	if (!k)
		return 1;
	int p = Pow(a, k / 2);
	if (k & 1)
		return (ll)p * p % mod * a % mod;
	return (ll)p * p % mod;
}
int Add(int a, int b){return a + b >= mod ? a + b - mod : a + b;}
int Sub(int a, int b){return a - b < 0 ? a - b + mod : a - b;}
void DFT(int *A, int w, int f)
{
	for (int i = 1, j = 0; i < w; i++)
	{
		for (int d = w >> 1; j ^= d, ~j & d; d >>= 1);
		if (i < j)
			swap(A[i], A[j]);
	}
	for (int i = 1; i < w; i <<= 1)
	{
		int wn = Pow(5, (mod - 1) / (i << 1));
		if (f == -1)
			wn = Pow(wn, mod - 2);
		for (int j = 0; j < w; j += i << 1)
		{
			int w1 = 1;
			for (int k = 0; k < i; k++)
			{
				int x = A[j + k], y = (ll)A[j + k + i] * w1 % mod;
				A[j + k] = Add(x, y);
				A[j + k + i] = Sub(x, y);
				w1 = (ll)w1 * wn % mod;
			}
		}
	}
	if (f == -1)
	{
		int x = Pow(w, mod - 2);
		for (int i = 0; i < w; i++)
			A[i] = (ll)A[i] * x % mod;
	}
}
void Link(int a, int b)
{
	++cnt;
	tar[cnt] = b;
	nex[cnt] = fir[a];
	fir[a] = cnt;
}
