typedef long long ll;
inline int sum(int x, int y)
{
	x += y;
	if (x >= MOD)
		x -= MOD;
	return x;
}
inline int sub(int x, int y)
{
	x -= y;
	if (x < 0)
		x += MOD;
	return x;
}
inline int quick_pow(int a, int n)
{
	int res = 1;
	while (n)
	{
		if (n & 1)
			res = (ll)res * a % MOD;
		a = (ll)a * a % MOD;
		n >>= 1;
	}
	return res;
}
int alpha[2][800005], poly_rev[800005], poly_ntt_lst = -1;
inline void poly_ntt_init(int n)
{
	if (poly_ntt_lst == n)
		return;
	poly_ntt_lst = n;
	alpha[0][0] = alpha[1][0] = 1;
	alpha[0][1] = quick_pow(GEN, (MOD - 1) / n);
	alpha[1][1] = quick_pow(alpha[0][1], MOD - 2);
	for (int i = 2; i <= n; i++)
	{
		for (int x = 0; x < 2; x++)
			alpha[x][i] = (ll)alpha[x][i - 1] * alpha[x][1] % MOD;
	}
	for (int i = 1, j = n >> 1; i + 1 < n; i++)
	{
		poly_rev[i] = j;
		int k = n >> 1;
		while (j & k)
		{
			j ^= k;
			k >>= 1;
		}
		j |= k;
	}
}
inline void poly_ntt(int *a, int n, bool f)
{
	poly_ntt_init(n);
	for (int i = 1; i + 1 < n; i++)
	{
		if (i < poly_rev[i])
			std::swap(a[i], a[poly_rev[i]]);
	}
	for (int i = 1; i < n; i <<= 1)
	{
		for (int j = 0, off = n / (i << 1); j < n; j += i << 1)
		{
			for (int k = j, cur = 0; k < j + i; k++, cur += off)
			{
				int x = (ll)a[k + i] * alpha[f][cur] % MOD;
				a[k + i] = sub(a[k], x);
				a[k] = sum(a[k], x);
			}
		}
	}
	if (f)
	{
		int x = quick_pow(n, MOD - 2);
		for (int i = 0; i < n; i++)
			a[i] = (ll)a[i] * x % MOD;
	}
}
inline void poly_mul(int *a, int *b, int n)
{
	int len = 1;
	while (len >> 1 <= n)
		len <<= 1;
	poly_ntt(a, len, false);
	poly_ntt(b, len, false);
	for (int i = 0; i < len; i++)
		a[i] = (ll)a[i] * b[i] % MOD;
	poly_ntt(a, len, true);
}
