void FFT(int *a,int n,int f){
	for (int i=0;i<n;i++)
		if (i<rev[i]) std::swap(a[i],a[rev[i]]);
	for (int i=1,t=0;i<n;i<<=1,t++){
		int wn=g[t][f];
		for (int j=0;j<n;j+=i<<1){
			int w=1;
			for (int k=0;k<i;k++,w=1ll*w*wn%mo){
				int x=a[j+k],y=1ll*w*a[j+k+i]%mo;
				a[j+k]=(x+y)%mo;
