			}
		}
	}
	if (f)
		for (int i=0;i<n;i++) a[i]=1ll*a[i]*invn%mo;
}

int ksm(int x,int y){
	int i=1;
	for (;y;y>>=1,x=1ll*x*x%mo)
		if (y&1) i=1ll*i*x%mo;
	return i;
}

