inline int Read()
{   rg int a=0,c=1;   rg char b=getchar();
	while(b!='-'&&(b<'0'||b>'9'))b=getchar();
	if(b=='-')c=-1,b=getchar();
	while(b>='0'&&b<='9')a=a*10+b-48,b=getchar();
	return a*c;
}
inline int Fast(rg int Di,rg int Mi)
{   rg int Back=1;
	for(;Mi>=1;Mi>>=1,Di=1ll*Di*Di%Mod)
		if(Mi&1) Back=1ll*Back*Di%Mod;
	return Back;
}
struct jin
{   int Rader[MAXN],Len,Ms,Inv;
	inline void NTT(int *P,rg int opt)
		{   for(rg int i=1;i<Len;i++)
				if(i<Rader[i]) swap(P[i],P[Rader[i]]);
			for(rg int i=1;i<Len;i<<=1)
			{   rg int Euler=Fast(5,(Mod-1)/(i<<1));
				if(opt<0) Euler=Fast(Euler,Mod-2);
				for(rg int Pos=i<<1,j=0;j<Len;j+=Pos)
				{   rg int Wi=1;
					for(rg int k=0;k<i;k++,Wi=1ll*Wi*Euler%Mod)
					{   rg int X=P[j+k],Y=1ll*P[i+j+k]*Wi%Mod;
						P[j+k]=(X+Y)%Mod,P[i+j+k]=(1ll*X-Y+Mod)%Mod;
					}
				}
			}
			if(opt>0) return ;   else Inv=Fast(Len,Mod-2);
			for(rg int i=0;i<Len;i++) P[i]=1ll*P[i]*Inv%Mod;
		}
	inline void Prepare(rg int Lx)
		{   Ms=-1;
			for(Len=1;Len<=Lx;Len<<=1) Ms++;
			for(rg int i=0;i<Len;i++) Rader[i]=(Rader[i>>1]>>1)|((i&1)<<Ms);
		}
}NTT;
inline int C(rg int A,rg int B){   return 1ll*Fac[A]*Invf[B]%Mod*Invf[A-B]%Mod;   }
inline void Link(rg int u,rg int v)
{   Edge[++Es]=(gao){u,v,First[u]},First[u]=Es;   }
inline void Dfs(rg int Now,rg int Ba)
{   Tot[Now]=1;
	for(rg int i=First[Now];i!=-1;i=Edge[i].Next)
	{	rg int v=Edge[i].v;   if(v==Ba) continue ;
		Dfs(v,Now),Tot[Now]+=Tot[v],Num[Tot[v]]++;
	}
	Num[n-Tot[Now]]++;
}
