                t[k + i] = (t1 - t2 + mod) % mod;
                W = 1LL * W * Wn % mod;
            }
        }
    }
    if (id == -1)
    {
        ll temp = qpow(n,mod - 2);
        for (ll i = 0; i < n; i++)
            t[i] = 1LL * t[i] * temp % mod;
