long long fast_pow(long long x, long long y)
{
	long long ans = 1, now = x;
	while (y)
	{
		if (y & 1) ans = ans * now % p;
		now = now * now % p;
		y >>= 1;
	}
	return ans;
}
void NTT(long long now[], int n, bool type = false)
{
	get_rev(n);
	for (int i = 0; i < n; i++)
		if (i < rev[i]) swap(now[i], now[rev[i]]);
