struct convolution {
  const int mod1 = 924844033;
  const int mod2 = 1004535809;

  typedef vector<int> vi;

  inline int loger(int v) {
    int res = 0;
    while (v) {
      res++;
      v >>= 1;
    }
    return res;
  }

  inline int po(int v, int u, const int mod) {
    int res = 1;
    for (int i = 30; ~i; i--) {
      res = (1ll * res * res) % mod;
      if (u & (1 << i)) res = (1ll * res * v) % mod;
    }
    return res;
  }

  inline void NTT(vi &a, const int mod, const int limit, bool inverse = false) {
    for (int i = 0; i < (1 << limit); i++) {
      int rev = 0;
      for (int j = 0; j < limit; j++)
        if ((i >> j) & 1) rev ^= 1 << (limit - j - 1);
      if (rev > i) swap(a[i], a[rev]);
    }
    for (int len = 1; len < (1 << limit); len <<= 1) {
      int w = po(5, (mod - 1) / (len << 1), mod);
      if (inverse) w = po(w, mod - 2, mod);
      for (int i = 0; i < (1 << limit); i += (len << 1)) {
        int step = 1;
        for (int j = 0; j < len; j++) {
          int u = a[i + j];
          int v = a[i + j + len];
          v = (1ll * v * step) % mod;
          a[i + j] = (u + v) % mod;
          a[i + j + len] = (u - v + mod) % mod;
          step = (1ll * step * w) % mod;
        }
      }
    }
    if (inverse) {
      int step = po(1 << limit, mod - 2, mod);
      for (int i = 0; i < (1 << limit); i++) a[i] = (1ll * a[i] * step) % mod;
    }
  }

  vi a, b, c;

  inline void conv(int a_[], const int la, int b_[], const int lb, int c_[]) {
    int lc = la + lb - 1;
    lc = loger(lc);
    a = vi(1 << lc);
    b = vi(1 << lc);
    c = vi(1 << lc);
    rep(i, 0, la) a[i] = a_[i];
    rep(i, 0, lb) b[i] = b_[i];
    NTT(a, mod1, lc);
    NTT(b, mod1, lc);
    c.resize(1 << lc);
    rep(i, 0, 1 << lc) c[i] = (1ll * a[i] * b[i]) % mod1;
    NTT(c, mod1, lc, true);
    rep(i, 0, la + lb - 1) c_[i] = c[i];
    return;
  }
} ziba;

