typedef long long LL;

LL Pow(LL x, LL e){
	LL ret = 1;
	while(e){
		if(e & 1) ret = ret * x % Mod;
		x = x * x % Mod;
		e >>= 1;
	}
	return ret;
}

int rev[N];

void DFT(LL* A, int n, bool inv){
	For(i, 0, n - 1) if(i < rev[i]) swap(A[i], A[rev[i]]);
	for(int i = 2; i <= n; i <<= 1){
		LL w = Pow(r, (Mod - 1) / i);
		if(inv) w = Pow(w, Mod - 2);
		for(int j = 0; j < n; j += i){
			LL cur = 1;
			for(int k = 0; k < (i >> 1); ++k){
				LL x = A[j + k], y = A[j + k + (i >> 1)] * cur % Mod;
				A[j + k] = (x + y) % Mod, A[j + k + (i >> 1)] = (x - y + Mod) % Mod;
				cur = cur * w % Mod;
			}
		}
	}
}

void NTT(LL *A, LL *B, int m){
	int n = 1;
	while(n <= m + 2) n <<= 1;
	For(i, 1, n - 1) rev[i] = (rev[i >> 1] >> 1) | (i & 1 ? n >> 1 : 0);
	DFT(A, n, 0), DFT(B, n, 0);
	For(i, 0, n - 1) A[i] = A[i] * B[i] % Mod;
	DFT(A, n, 1);
	LL inv = Pow(n, Mod - 2);
	For(i, 0, n - 1) A[i] = A[i] * inv % Mod;
}

