  for(int i=1;i<m;i++) rev[i]=(rev[i>>1]>>1)|((i&1)<<L);
  for(int i=1;i<=n;i++) A[i]=1LL*a[i]*fac[i]%P,B[m-i]=inv[i]; B[0]=1;
  NTT(A,m,1); NTT(B,m,1);
  for(int i=0;i<m;i++) A[i]=1LL*A[i]*B[i]%P;
  NTT(A,m,0);
  for(int i=1;i<=n;i++){
    int cur=1LL*n*C(n,i);
