inline ll power(ll a,ll n,ll mod){
	ll b = 1LL;
	while(n){
		if(n&1) b = b * a %mod;
		a = a * a % mod;
		n >>= 1;
	}
	return b;
}

inline ll inv(ll a,ll mod){
	return power(a,mod-2,mod);
}


void ntt(vector<ll> &a,bool inv_flag,ll mod){
	const int n=a.size();

	ll base=power(5LL,(mod-1)/n,mod);
	if(inv_flag) base=inv(base,mod); 

	int rj=0;
	rep(j,1,n-1){
		for(int k=n>>1;k>(rj^=k);k>>=1);
		if(j<rj) swap(a[j],a[rj]);
 	}

 	for(int m=1;m<n;m<<=1){
 		const ll wn=power(base,n/2/m,mod);
		ll w=1LL;

		rep(p,m){
			for(int s=p;s<n;s+=2*m){
				ll u=a[s],v=1LL * a[s+m] * w % mod;
				a[s]=(u+v)%mod,a[s+m]=(u+mod-v)%mod;
			}
			w=1LL * w * wn % mod;
		}
	}

	const ll n_inv=inv(n,mod);
	if(inv_flag) rep(i,n) a[i]=1LL*a[i]*n_inv%mod;
}



vector<ll> convolution(vector<ll> a,vector<ll> b,ll mod){
	int ntt_size=1;
	while (ntt_size < a.size()+b.size()) ntt_size <<= 1;

	a.resize(ntt_size),ntt(a,0,mod);
	b.resize(ntt_size),ntt(b,0,mod);

	vector<ll> c(ntt_size,0LL);
	rep(i,ntt_size) c[i]=1LL*a[i]*b[i]%mod;

	ntt(c,1,mod);
	return c;
}

