	for (int i = 0, j = 0; i < k; ++i) {
		if (i < j) swap(a[i], a[j]);
		for (int l = k / 2; (j ^= l) < l; l /= 2);
	}

	for (int i = 2; i <= k; i *= 2) {
		for (int j = 0; j < k; j += i) {
			for (int l = 0; l < i / 2; ++l) {
				long long t = a[j + i / 2 + l] * om[k / i * l] % MOD;
				a[j + i / 2 + l] = (a[j + l] + MOD - t) % MOD;
				a[j + l] = (a[j + l] + t) % MOD;
			}
		}
	}
}

int dfs(int x, int p) {
	int size = 1;
	for (auto y: edges[x]) if (y != p) {
		size += dfs(y, x);
	}

	if (p != 0) {
		--a[size];
		--a[n - size];
	}
	return size;
}

