	for (int i = 2; i <= n; ++i) inv[i] = (MOD - MOD / i) * inv[MOD % i] % MOD;

	long long fac = 1;
	b[n] = invfac[0] = 1;
	for (int i = 1; i <= n; ++i) {
		fac = fac * i % MOD;
		a[i] = a[i] * fac % MOD;
		b[n - i] = invfac[i] = invfac[i - 1] * inv[i] % MOD;
	}

	int k = 1;
	while (k < n * 2 + 1) k *= 2;

	long long r = qpow(g, (MOD - 1) / k);
	om[0] = invom[0] = 1;
	for (int i = 1; i < k; ++i) om[i] = invom[k - i] = om[i - 1] * r % MOD;

	fft(a, k, om);
