            for(int k=0;k<i;k++)
            {
                int x=1ll*w[i+k]*a[i+j+k]%mod;
                a[i+j+k]=(a[j+k]-x)%mod,a[j+k]=(a[j+k]+x)%mod;
            }
}
void IDFT(int a[])
{
    reverse(a+1,a+limn);DFT(a);int iv=mod-(mod-1)/limn;
    for(int i=0;i<limn;i++)a[i]=1ll*iv*a[i]%mod;
}
