	inv[N-1]=fpow(fac[N-1],mod-2);
	for(int i=N-1; i; --i) inv[i-1]=(lint)inv[i]*i%mod;
}

inline int C(const int x,const int y){
	if(x<y) return 0;
	return (lint)fac[x]*inv[y]%mod*inv[x-y]%mod;
}

namespace G{
