        for(int k=0,d=1;k<n;k++,d<<=1)
            for(int i=0;i<m;i+=d<<1){
                C *l=a+i,*r=a+i+d,*w=H[k];
                for(int j=0;j<d;++j,++l,++r){
                    const C t=(*w++)*(*r);
                    *r=*l-t,*l=*l+t;
                }
            }
