    void idft(C *a,int n){
        reverse(a+1,a+(1<<n));
        dft(a,n); ld pw=1<<n;
        REP(i,1<<n)a[i]=a[i]/pw;
    }
    void Idft(C *a,int n){
        static C b[N]; int m=1<<(n-1); C w=(C){1,0};
        C wn=(C){cos(pi/(1<<(n-1))),-sin(pi/(1<<(n-1)))};
        REP(i,m){
            b[i]=(a[i]+a[m+i]).mulR(0.5)
                +(a[i]-a[m+i]).mulI(0.5)*w;
            w=w*wn;
        }
        idft(b,n-1);
        REP(i,m){
            a[i<<1]=(C){b[i].r,0};
            a[i<<1|1]=(C){b[i].i,0};
        }
    }
    poly mul(poly A,poly B){
        int aim=A.size()+B.size()-1,n=1;
        while((1<<n)<=aim) n++;
        REP(i,1<<n) a[i]=b[i]=c[i]=d[i]=(C){0,0};
        REP(i,A.size()) a[i].r=A[i]>>15,b[i].r=A[i]&M;
        REP(i,B.size()) c[i].r=B[i]>>15,d[i].r=B[i]&M;
        Dft(a,b,n),Dft(c,d,n);
        REP(i,1<<n){
            C x=a[i]*c[i],y=a[i]*d[i]+b[i]*c[i],z=b[i]*d[i];
            a[i]=x,b[i]=y,c[i]=z;
        }
        Idft(a,n),Idft(b,n),Idft(c,n);
        poly res(aim);
        REP(i,aim){
            ll x=ll(a[i].r+0.5)%mod,y=ll(b[i].r+0.5)%mod,z=c[i].r+0.5;
            res[i]=((x<<30)+(y<<15)+z)%mod;
        }
        return res;
    }
}

