void dft(int *a, int n, int f) {
	for(int i = 0; i < n; ++ i)
		if(i < rev[i])
			swap(a[i], a[rev[i]]);
	for(int i = 1; i < n; i <<= 1) {
		int gn = qpow(G, (mod - 1) / (i << 1));
		if(f == - 1) gn = qpow(gn, mod - 2);
		for(int j = 0; j < n; j += (i << 1)) {
			int g = 1, x, y;
			for(int k = 0; k < i; ++ k, g = 1ll * g * gn % mod) {
				x = a[j + k]; y = 1ll * a[i + j + k] * g % mod;
				a[j + k] = (x + y) % mod;
				a[i + j + k] = (x - y + mod) % mod;
			}
		}
	}
	if(f == - 1) {
		int ny = qpow(n, mod - 2);
		for(int i = 0; i < n; ++ i)
			a[i] = 1ll * a[i] * ny % mod;
	}
}
