int dfs(int v, int p) {
	int sz = 1;
	for(auto &i : g[v]) if(i != p) {
		int t = dfs(i, v);
		sz += t;
		sub[t]+=1;
	}
	sub[n - sz]+=1;
	return sz;
}
modular fact[maxn], inv[maxn];
void setup() {
	fact[0] = inv[0] = 1;
	for(int i = 1; i < maxn; i++) {
		fact[i] = fact[i-1]*modular(i);
		inv[i] = fact[i].inv();
	}
}
modular nck(ll n, ll k) {
	if(k>n) return 0;
	return fact[n]*inv[k]*inv[n-k];
}

