	LL ret = 1;
	while(k){
		if(k&1) ret = ret*x%Mod;
		x = x*x%Mod;
		k >>= 1;
	}
	return ret;
}
void dft(LL *a, LL op) {
	LL i, j, k;
	j = 0;
	for(i = 0; i < N; i++){
		if(i < j) swap(a[i], a[j]);
		k = N>>1;
		while(j&k) j -= k, k >>= 1;
		j += k;
	}
	for(i = 2; i <= N; i <<= 1){
		LL wn = qpow(G, op == 1 ? (Mod-1)/i : Mod-1-(Mod-1)/i);
		for(j = 0; j < N; j += i){
			LL w = 1;
			for(k = j; k < j+i/2; k++){
				LL x = a[k], y = a[k+i/2]*w%Mod;
				a[k] = (x+y)%Mod; a[k+i/2] = (x-y+Mod)%Mod;
				w = w*wn%Mod;
			}
		}
	}
	if(op == -1) for(i = 0; i < N; i++) a[i] = a[i]*invN%Mod;
