const int N = (1 << 19) + 10;

const int maxn = 2e5 + 100;

const int mod = 924844033;

const int proot = 5;

struct edge {
	int to, next;

	edge(){}
	edge(int to, int next): to(to), next(next) {}
}e[maxn << 1];

int n, m;
int head[maxn], coef[maxn], siz[maxn];
int fac[N], ifac[N], a[N], b[N];

int Exp(int x, int n) {
	int y = 1;
	while(n) {
		if(n & 1) {
			y = 1ll * y * x % mod;
		}
		x = 1ll * x * x % mod;
		n >>= 1;
	}
	return y;
}

void pre() {
	fac[0] = 1;
	for (int i = 1; i < N; ++i) {
		fac[i] = 1ll * fac[i - 1] * i % mod;
	}
	ifac[N - 1] = Exp(fac[N - 1], mod - 2);
	for (int i = N - 1; i >= 1; --i) {
		ifac[i - 1] = 1ll * ifac[i] * i % mod;
	}
	return;
}

void dfs(int u = 1, int par = 0) {
	siz[u] = 1;
	for (int i = head[u]; ~i; i = e[i].next) {
		if(e[i].to != par) {
			dfs(e[i].to, u);
			--coef[siz[e[i].to]];
			siz[u] += siz[e[i].to];
		}
	}
	--coef[n - siz[u]];
	++coef[n];
	return;
}

void add_edge(int u, int v) {
	e[m] = edge(v, head[u]);
	head[u] = m++;
	return;
}

void add_biedge(int u, int v) {
	return add_edge(u, v), add_edge(v, u);
}

void dft(int *a, bool rev = 0) {
	for (int i = 0, j = 0; i < m; ++i) {
		if(i < j) {
			std::swap(a[i], a[j]);
		}
		for (int k = (m >> 1); (j ^= k) < k; k >>= 1);
	}
	for (int hl = 1, l = 2; hl < m; hl = l, l <<= 1) {
		int wn = Exp(proot, (mod - 1) / l);
		if(rev) {
			wn = Exp(wn, mod - 2);
		}
		for (int i = 0; i < m; i += l) {
			int w = 1;
			for (int j = i, k = (i | hl); j < (i | hl); ++j, ++k) {
				int x = a[j], y = 1ll * a[k] * w % mod;
				a[j] = (x + y) % mod;
				a[k] = (x - y) % mod;
				w = 1ll * w * wn % mod;
			}
		}
	}
	if(rev) {
		int inv = Exp(m, mod - 2);
		for (int i = 0; i < m; ++i) {
			a[i] = 1ll * a[i] * inv % mod;
		}
	}
	return;
}

int main() {
	pre();
	scanf("%d", &n);
	memset(head + 1, -1, sizeof(head[0]) * n);
	for (int i = 1; i < n; ++i) {
		int u, v;
		scanf("%d%d", &u, &v);
		add_biedge(u, v);
	}
	dfs();
	m = 1;
	while(m <= (n << 1)) {
		m <<= 1;
	}
	for (int i = 1; i <= n; ++i) {
		a[i] = 1ll * coef[i] * fac[i] % mod;
		b[i] = ifac[n - i];
	}
	dft(a);
	dft(b);
	for (int i = 0; i < m; ++i) {
		a[i] = 1ll * a[i] * b[i] % mod;
	}
	dft(a, 1);
	for (int i = 1; i <= n; ++i) {
		printf("%d\n", (1ll * a[i + n] * ifac[i] % mod + mod) % mod);
	}
	return 0;
}

