int calcg(int p)
{
	int m=p-1,tot=0;
	for (int i=2;i<=sqrt(p);i++)
		if (m%i==0)
		{
			pr[++tot]=i;
			while (m%i==0) m/=i;
		}
	if (m>1) pr[++tot]=m;
	for (int i=2;;i++)
	{
