                r = r * a % mod;
        return r;
    }
    int rev(int x, int n) {
        int res = 0;
        for(int i = 0 ; (1 << i) < n ; ++ i) {
            res = (res << 1) | ((x >> i) & 1);
        }
        return res;
    }
    void ntt(ll *a, int ty, int n) {
        for(int i = 0 ; i < n ; ++ i) f[rev(i, n)] = a[i];
        for(int i = 2 ; i <= n ; i <<= 1) {
            ll wn = pw(g[ty], (mod - 1) / i);
            for(int j = 0 ; j < n ; j += i) {
                ll w = 1;
                for(int k = j ; k < j + i / 2 ; ++ k) {
                    ll u = f[k], v = w * f[k + i / 2] % mod;
                    f[k] = (u + v) % mod;
                    f[k + i / 2] = (u - v) % mod;
                    w = w * wn % mod;
                }
            }
        }
        for(int i = 0 ; i < n ; ++ i) {
            a[i] = f[i];
            if(ty) a[i] = a[i] * inv % mod;
        }
    }

    void init() {
        len = 1; while(len < 4 * n) len <<= 1;
        for(int i = 0 ; i <= 2 * n ; ++ i) Y[i] = invfac[2 * n - i];
        inv = pw(len, mod - 2);
        ntt(Y, 0, len);
    }
    void sol() {
        int mx = 0;
        for(int i = 0 ; i < len ; ++ i) X[i] = 0;
        for(int i = 1 ; i <= n ; ++ i) if(a[i] >= 0) ++ X[a[i]], mx = max(mx, a[i]);
        for(int i = 0 ; i <= mx ; ++ i) if(X[i]) (X[i] *= fac[i]) %= mod;
        ntt(X, 0, len);
        for(int i = 0 ; i < len ; ++ i) (X[i] *= Y[i]) %= mod;
        ntt(X, 1, len);
        for(int k = 1 ; k <= m ; ++ k) p[k] = X[2 * n + k] * invfac[k] % mod;
    }
}

void solf() {
    CALC :: a[1] = -1;
    for(int i = 2 ; i <= n ; ++ i) {
        CALC :: a[i] = a[i];
    }
    CALC :: sol();
    for(int k = 1 ; k <= m ; ++ k) {
        (f[k] -= CALC :: p[k]) %= mod;
    }

    for(int i = 1 ; i <= n ; ++ i) {
        CALC :: a[i] = n - a[i];
    }
    CALC :: sol();
    for(int k = 1 ; k <= m ; ++ k) {
        (f[k] -= CALC :: p[k]) %= mod;
    }
}

