ll w, invw, M;
ll pw[MAXN], pinvw[MAXN];
ll fta[MAXN], ftb[MAXN], ftans[MAXN];
ll fta1[MAXN], ftb1[MAXN], ftans1[MAXN];
int ct = 0;

ll exp(ll x, ll k) {
    if (k == 0)
        return 1;
    ll y = exp(x, k/2);
    return (k%2 == 0) ? y*y%p : y*y%p*x%p;
}

ll inv(ll x) { return exp(x, p-2); }

vector<ll> pmult(vector<ll> a, vector<ll> b) {
    vector<ll> c;
    c.resize(max(a.size(), b.size()));
    for (int i = 0; i < c.size(); ++i)
        c[i] = 1;
    for (int i = 0; i < a.size(); ++i)
        c[i] = a[i];
    for (int i = 0; i < b.size(); ++i)
        c[i] = c[i]*b[i]%p;
    return c;
}

vector<ll> plusv(vector<ll> a, vector<ll> b) {
    vector<ll> c;
    c.resize(max(a.size(), b.size()));
    for (int i = 0; i < a.size(); ++i)
        c[i] = a[i];
    for (int i = 0; i < b.size(); ++i)
        c[i] = (c[i]+b[i])%p;
    return c;
}

void process(ll M) {
    //order of w is M
    w = exp(g, (p-1)/M);
    invw = inv(w);

    pw[0] = pinvw[0] = 1;
    for (int i = 1; i < M; ++i) {
        pw[i] = w*pw[i-1]%p;
        pinvw[i] = invw*pinvw[i-1]%p;
    }
}

vector<ll> fft(vector<ll> a, bool inverse) {
    M = 1; ct = 0;

    while (M < a.size())
        M *= 2, ct++;
    if (!inverse)
        M *= 2, ct++;

    assert(M <= MAXN);
    process(M);

    memset(fta, 0, sizeof(fta));

    for (int i = 0; i < a.size(); ++i)
        fta[i] = a[i];

    for (int i = ct-1; i >= 0; --i) {
        int l = (1<<i);
        for (int j = 0; j < (1<<i); ++j) {
            for (int k = 0; k < (1<<(ct-1-i)); ++k) {
                ll y = (inverse ? pinvw[k*l] : pw[k*l]);
                fta1[j+k*l] = (fta[j+2*k*l]+y*fta[j+l+2*k*l])%p;
                fta1[j+k*l+(1<<(ct-1))] = (fta[j+2*k*l]+p-y*fta[j+l+2*k*l]%p)%p;
            }
        }

        memcpy(fta, fta1, sizeof(fta));
    }

    vector<ll> ans;
    for (int i = 0; i < M; ++i)
        ans.push_back(fta[i]);
    if (inverse) {
        ll invm = inv(M);
        for (int i = 0; i < M; ++i)
            ans[i] = ans[i]*invm%p;
    }

    return ans;
}

vector<ll> mult(vector<ll> &a, vector<ll> &b) {
    vector<ll> c = pmult(fft(a, 0), fft(b, 0));
    return fft(c, 1);
}

