void Dfs(int Now, int Pa) {
    Coe[N] += 1; Size[Now] = 1;
    for(int i = Last[Now]; i; i = Road[i].Next) {
        int To = Road[i].To;
        if(To ^ Pa) {
            Dfs(To, Now); 
            Coe[Size[To]] -= 1;
            if(Coe[Size[To]] < 0) Coe[Size[To]] = (Coe[Size[To]] + Mod) % Mod;
            Size[Now] += Size[To]; 
        }
    }
    Coe[N - Size[Now]] -= 1;
    if(Coe[N - Size[Now]] < 0) Coe[N - Size[Now]] = (Coe[N - Size[Now]] + Mod) % Mod;
}

int Kasumi(int A, int B) {
    int Ans = 1, Base = A;
    B = (B + (Mod - 1)) % (Mod - 1);
    while(B) {
        if(B & 1) Ans = Base * Ans % Mod;
        Base = Base * Base % Mod;
        B >>= 1;
    }
    return Ans;
} 

int Fac[MaxN], Inv[MaxN];

void Init() {
    Fac[0] = 1; Inv[0] = 1;
    for(int i = 1; i <= N << 1; i++) Fac[i] = Fac[i - 1] * i % Mod;
    for(int i = 1; i <= N << 1; i++) Inv[i] = Kasumi(Fac[i], Mod - 2);
}

int C(int A, int B) {
    return Fac[A] % Mod * Inv[B] % Mod * Inv[A - B] % Mod;
} 

int Rev[MaxN];

#define Swap(A, B) A ^= B ^= A ^= B

void Ntt(int *A, int N, int Flag) {
    for(int i = 0; i < N; i++) 
        if(i < Rev[i]) Swap(A[i], A[Rev[i]]);
    for(int i = 1; i < N; i <<= 1) {
        int W = Kasumi(G, Flag * (Mod - 1) / (i << 1));
        for(int j = 0; j < N; j += (i << 1)) {
            int Wn = 1;
            for(int k = 0; k < i; k++, Wn = Wn * W % Mod) {
                int x = A[j + k], y = A[i + j + k] * Wn % Mod;
                A[j + k] = (x + y) % Mod;
                A[i + j + k] = (x - y + Mod) % Mod;
            }
        }
    }
    if(!~Flag) {
        int T = Kasumi(N, Mod - 2);
        for(int i = 0; i < N; i++) A[i] = A[i] * T % Mod;
    }
}

