const int mxn=524288,md=924844033;
int power(int x,int p){
	int ret=1;
	for (;p;p>>=1,x=1ll*x*x%md)
		if (p&1) ret=1ll*ret*x%md;
	return ret;
}
bool check(int x){
	int num=md-1;
	for (int i=2;i*i<=num;++i)
		if (num%i==0){
			if (power(x,(md-1)/i)==1) return 0;
			for (;num%i==0;num/=i);
		}
	if (num>1&&power(x,(md-1)/num)==1) return 0;
	return 1;
}
int len,ln,invn,rev[mxn],w[21][mxn];
void NTT(int *a,int flg){
	for (int i=0;i<len;++i)
		if (i<rev[i]) swap(a[i],a[rev[i]]);
	for (int i=1,p=0;i<=len>>1;i<<=1,++p)
		for (int j=0,k,t,x,y;j<len;j+=i<<1)
			for (k=j,t=i;k<j+i;++k,t+=flg){
				x=a[k],y=1ll*w[p][t]*a[k+i]%md;
				a[k]=(x+y)%md,a[k+i]=(x-y)%md;
			}
	if (flg==-1)
		for (int i=0;i<len;++i)
			a[i]=1ll*a[i]*invn%md;
}
void NTT_init(int n){
	for (len=1,ln=0;len<n;len<<=1,++ln);
	for (int i=0;i<len;rev[i]=rev[i>>1]>>1|((i&1)<<(ln-1)),++i);
	invn=power(len,md-2);
}
void W_init(int n){
	NTT_init(n);
	for (int i=1,p=0;i<=len>>1;i<<=1,++p){
		w[p][i]=1;
		int x=power(5,(md-1)/(i<<1));
		for (int j=1;j<i;++j) w[p][i+j]=1ll*x*w[p][i+j-1]%md;
		x=power(x,md-2);
		for (int j=1;j<i;++j) w[p][i-j]=1ll*x*w[p][i-j+1]%md;
	}
}
int fct[mxn],ifc[mxn];
void init(int n){
	fct[0]=ifc[0]=1;
	for (int i=1;i<=n;++i) fct[i]=1ll*fct[i-1]*i%md;
	ifc[n]=power(fct[n],md-2);
	for (int i=n-1;i;--i) ifc[i]=ifc[i+1]*(i+1ll)%md;
}
int n,m,head[mxn],cnt[mxn],a[mxn],b[mxn];
struct ed{int to,nxt;}edge[mxn<<1];
void addedge(int u,int v){
	edge[++m]=(ed){v,head[u]},head[u]=m;
	edge[++m]=(ed){u,head[v]},head[v]=m;
}
int dfs(int u,int fa){
	int siz=1;
	for (int i=head[u],v;i;i=edge[i].nxt)
		if ((v=edge[i].to)!=fa) siz+=dfs(v,u);
	if (u>1) ++cnt[siz];
	++cnt[n-siz];
	return siz;
}
