dfs (1, -1), fac[0] = 1;
for (int i=1; i<=N; i++)
    fac[i] = (1LL * fac[i - 1] * i) % mod;
inv[N] = pow (fac[N], mod - 2, mod);
for (int i=N - 1; i>=0; i--)
    inv[i] = (1LL * inv[i + 1] * (i + 1)) % mod;
///ans[k] = suma de ap[i] * comb (i, k)
///ans[k] = suma de ap[i] * fac[i] * inv[k] * inv[i - k]
///ans[k] = inv[k] * suma de (ap[i] * fac[i]) * inv[i - k] pentru i de la k la N, i de la 1 la N
///fie sirul inv2[j] = inv2[N - j] -> inv[i - k] = inv2[N - i + k]
///ans[k] = inv[k] * suma de (ap[i] * fac[i]) * inv2[N - i + k]
///ans[k] = inv[k] * pol_result[N + k], definite pana la 2N
ap[0] = 0;
for (int i=0; i<=N; i++)
{
    first_term[i] = (1LL * ap[i] * fac[i]) % mod;
    second_term[i] = inv[N - i];
}
GetProd (first_term, second_term, pol_result, N);
for (int i=1; i<=N; i++)
    ans[i] = (1LL * inv[i] * pol_result[N + i]) % mod;
