ll pwr(int ll x,ll y){
	if(!y)return 1;
	if(y&1)return pwr(x,y-1)*x%P;
	ll z=pwr(x,y/2);
	return z*z%P;
}
inline void ntt(ll *a,int t){
	for(int i=0;i<lim;i++)
		if(i<rev[i])
			swap(a[i],a[rev[i]]);
	for(int mid=1;mid<lim;mid<<=1){
		int rgt=mid<<1;
		ll wn=pwr(5,(P-1)/rgt);
		if(t==-1)wn=pwr(wn,P-2);
		for(int loc=0;loc<lim;loc+=rgt){
			ll w=1;
			for(int k=0;k<mid;k++){
				ll x=a[loc+k],y=w*a[loc+mid+k]%P;
				a[loc+k]=(x+y)%P;
				a[loc+mid+k]=(x-y+P)%P;
				w=w*wn%P;
			}
		}
	}
	if(t==-1){
		ll invlim=pwr(lim,P-2);
		for(int i=0;i<lim;i++)
			a[i]=a[i]*invlim%P;
	}
