	for(int nxt : to[u]){
		if(nxt == v) continue;
		dfs(nxt, u);
		cnt[sz[nxt]]++;
		sz[u] += sz[nxt];
	}
	if(v != -1){
		cnt[n - sz[u]]++;
	}
}
int main(){
