        k>>=1;
        x=x*x%MOD;
    }
    return res;
}
ll modInv(ll x){
    return powm(x,MOD-2);
}
inline ll comb(int x,int k){
    return fact[x]*factInv[k]%MOD*factInv[x-k]%MOD;
}
