    fact[0]=1;
    for(int i=0;i<n;i++){
        fact[i+1]=fact[i]*(i+1);
    }
    factInv[n]=modInv(fact[n]);
    for(int i=n-1;i>=0;i--){
        factInv[i]=factInv[i+1]*(i+1);
    }
}
