inline int C(int n, int m){return (ll)jc[n]*inv[m]%mod*inv[n-m]%mod;}

inline void NTT(int *a, int f){
	for(int i=0; i<n1; i++)if(i<R[i])swap(a[i], a[R[i]]);
	for(int i=1; i<n1; i<<=1){
		int wn=pow(g, (mod-1)/(i*2)); if(f==-1)wn=pow(wn, mod-2);
		for(int j=0; j<n1; j+=i*2){
			int w=1;
			for(int k=0; k<i; k++){
				int x=a[j+k], y=(ll)w*a[j+k+i]%mod;
				a[j+k]=x+y; a[j+k+i]=x-y;
				if(a[j+k]>=mod)a[j+k]-=mod; if(a[j+k+i]<0)a[j+k+i]+=mod;
				w=(ll)w*wn%mod;
			}
		}
	}
	if(f==-1)for(int i=0; i<n1; i++)a[i]=(ll)a[i]*INV%mod;
}
inline void solve(){
	memset(a, 0, sizeof(a)); memset(b, 0, sizeof(b));
	for(int i=1; i<=n; i++)a[size[i]]++;
	for(int i=0; i<=n; i++)a[i]=(ll)a[i]*jc[i]%mod;
	for(int i=0; i<=n; i++)b[i]=inv[n-i];
	n1=n+1;
	L=1; while((1<<L)<n1*2)L++; n1=1<<L;
	for(int i=0; i<n1; i++)R[i]=(R[i/2]/2)|((i&1)<<(L-1));

	INV=pow(n1, mod-2);
	NTT(a, 1); NTT(b, 1);
	for(int i=0; i<n1; i++)a[i]=(ll)a[i]*b[i]%mod;
	NTT(a, -1);

	for(int i=1; i<=n; i++)ans[i]=(ans[i]-(ll)a[n+i]*inv[i]%mod+mod)%mod;
}

