int lim;
int bit;

int rev(int x) {
  int ret = 0;
  for (int i = 0; i < bit; ++i) {
    ret <<= 1;
    ret |= x & 1;
    x >>= 1;
  }
  return ret;
}

int revbit[MAX];
int g[MAX];

void fft(int *f, int bit, int o) {
  for (int i = 0; i < lim; ++i) {
    if (revbit[i] > i) {
      swap(f[revbit[i]], f[i]);
    }
  }
  for (int i = 0; i < bit; ++i) {
    int len = 1 << i;
    for (int j = 0; j < lim; j += 1 << i + 1) {
      int wn = 0;
      for (int k = j; k < j + len; ++k) {
        int t = (long long) f[k + len] * g[wn] % P;
        f[k + len] = (f[k] - t) % P;
        if (f[k + len] < 0) {
          f[k + len] += P;
        }
        f[k] = (f[k] + t) % P;
        wn += o * (1 << bit - i - 1);                        
        if (wn < 0) {
          wn += lim;
        }
      }
    }
  }
}

int modexp(int a, int x, int P) {
  int ret = 1;
  while (x) {
    if (x & 1) {
      ret = (long long) ret * a % P;
    }
    a = (long long) a * a % P;
    x >>= 1;
  }
  return ret;
}

void calc() {
  while ((1 << bit) < n + n) {
    ++bit;   
  }
  lim = 1 << bit;
  for (int i = 0; i < lim; ++i) {
    revbit[i] = rev(i);
  }
  g[0] = 1;
  g[1] = modexp(5, (P - 1) / lim, P);
  for (int i = 2; i < lim; ++i) {
    g[i] = (long long) g[i - 1] * g[1] % P;
  }
  fft(f1, bit, 1);
  fft(f2, bit, 1);
  for (int i = 0; i < lim; ++i) {
    f1[i] = (long long) f1[i] * f2[i] % P;
  }
  fft(f1, bit, -1);
  int invlim = modexp(lim, P - 2, P);
  for (int i = 0; i < lim; ++i) {
    f1[i] = (long long) f1[i] * invlim % P;
  }    
}

