	for(int i=n-1;i>=0;i--)
		inv[i]=inv[i+1]*(i+1)%MO;
}
int Adj[MAXN],V[MAXN*2],nxt[MAXN*2],c,siz[MAXN];
void AddEdge(int u,int v)
{
	c++;V[c]=v,nxt[c]=Adj[u];Adj[u]=c;
}
void dfs(int u,int p)
{
