			siz[u]+=siz[V[i]];
		}
	f[siz[u]]--;
	f[n-siz[u]]--;
}
void NTT(LL A[],int N,int typ)
{
	for(int i=1,j=0;i<N-1;i++)
	{
		for(int s=N;j^=s>>=1,~j&s;);
		if(i<j) swap(A[i],A[j]);
	}
	for(int i=1;i<N;i<<=1)
	{
		LL w1=PowMod(G,(MO-1)/(i<<1)),w=1;
		if(typ==-1)
			w1=PowMod(w1,MO-2);
		for(int j=0;j<i;j++,w=w*w1%MO)
			for(int l=j,r=l+i;l<N;l+=(i<<1),r=l+i)
			{
				int tmp=A[r]*w%MO;
				A[r]=(A[l]-tmp+MO)%MO;
				A[l]=(A[l]+tmp)%MO;
			}
	}
	if(typ==-1)
	{
		int Inv=PowMod(N,MO-2);
		for(int i=0;i<N;i++)
			A[i]=A[i]*Inv%MO;
	}
}
