inline int Pow( int A , int B ) {
	B = ( B + Mod - 1 ) % ( Mod - 1 ) ;
	register int Ans = 1 ;
	while( B ) {
		if( B & 1 ) Ans = 1ll * Ans * A % Mod ;
		A = 1ll * A * A % Mod ;
		B >>= 1 ;
	}
	return Ans ;
}
inline void GetC() {
	Jc[0] = Inv[0] = 1 ;
	for(register long long i = 1 ; i <= N ; ++i )
		Jc[i] = Jc[i-1] * i % Mod ;
	Inv[N] = Pow( Jc[N] , Mod - 2 ) ; 
	for(register long long i = N ; --i ; )
		Inv[i] = Inv[i+1] * (i+1) % Mod ;
}
int Cnt , Head[MaxN] , To[MaxM] , Next[MaxM] , Size[MaxN] , Fa[MaxN] ;
inline void Add( int U , int V ) {
	To[++Cnt] = V ;
	Next[Cnt] = Head[U] ;
	Head[U] = Cnt ;
	To[++Cnt] = U ;
	Next[Cnt] = Head[V] ;
	Head[V] = Cnt ;
}
void Dfs( int Nod ) {
	Size[Nod] = 1 ;
	for(register int i = Head[Nod] ; i ; i = Next[i] )
		if( Fa[Nod] ^ To[i] ) {
			Fa[To[i]] = Nod ;
			Dfs( To[i] ) ;
			Size[Nod] += Size[To[i]] ;
		}
}
int A[MaxN] , B[MaxN] , Rev[MaxN] ;
void Getans( int Nod ) {
	for(register int i = Head[Nod] ; i ; i = Next[i] ) {
		if( To[i] != Fa[Nod] ) Getans( To[i] ) ;
		--A[ To[i] == Fa[Nod] ? N - Size[Nod] : Size[To[i]] ] ;
	}
}
int Log , Len ;
inline void Ntt( int *A , int Flag ) {
	for(register int i = 0 ; i < Len ; ++i )
		if( Rev[i] < i ) swap( A[i] , A[Rev[i]] ) ;
	for(register int l = 2 , Mid = 1 ; l <= Len ; l <<= 1 , Mid <<= 1 ) {
		register int Wn = Pow( G , Flag * ( Mod - 1 ) / l ) ;
		for(register int j = 0 ; j < Len ; j += l )
			for(register int W = 1 , k = 0 ; k < Mid ; ++k , W = 1ll * W * Wn % Mod ) {
				register int X = A[j+k] , Y = 1ll * W * A[j+k+Mid] % Mod ;
				A[j+k] = ( X + Y ) % Mod ;
				A[j+k+Mid] = ( X - Y + Mod ) % Mod ;
			}
	}
}
