int quick_pow(int x, int y){
	int sum = 1;
	for(; y; y >>= 1, x = 1ll * x * x % mod)
		if(y & 1) sum = 1ll * sum * x % mod;
	return sum;
}

void init(){
	fac[0] = 1;
	for(int i = 1; i <= n; ++i)
		fac[i] = 1ll * fac[i - 1] * i % mod;
	ifac[n] = quick_pow(fac[n], mod - 2);
	for(int i = n; i; --i)
		ifac[i - 1] = 1ll * ifac[i] * i % mod;
	return ;
}

void add(int u, int v){
	e[++cnt] = (edge){v, fir[u]}; fir[u] = cnt;
	return ;
}

void dfs(int u, int fa){
	sz[u] = 1;
	for(int i = fir[u]; i; i = e[i].nxt){
		int v = e[i].to;
		if(v == fa) continue;
		dfs(v, u); sz[u] += sz[v];
	}
	if(fa) ++a[sz[u]], ++a[n - sz[u]];
	return ;
}

void NTT(int *x, int len, int flag){
	for(int i = 0; i < len; ++i)
		if(i < R[i]) swap(x[i], x[R[i]]);
	for(int i = 1; i < len; i <<= 1){
		int wn = quick_pow(G, (mod - 1) / (i << 1));
		if(flag == -1) wn = quick_pow(wn, mod - 2);
		for(int j = 0; j < len; j += i << 1){
			int w = 1;
			for(int k = j; k < i + j; ++k, w = 1ll * w * wn % mod){
				int p = x[k], q = 1ll * w * x[i + k] % mod;
				x[k] = (p + q) % mod; x[i + k] = (p + mod - q) % mod;
			}
		}
	}
	if(flag == 1) return ;
	int inv = quick_pow(len, mod - 2);
	for(int i = 0; i < len; ++i) x[i] = 1ll * x[i] * inv % mod;
	return ;
}

int C(int x, int y){
	return 1ll * fac[x] * ifac[y] % mod * ifac[x - y] % mod;
}

