		}
}

void init(){
	fac[0]=1;
	for(int i=1;i<MAXN;i++) fac[i]=fac[i-1]*i%P;
	invfac[MAXN-1]=getPow(fac[MAXN-1],P-2);
	for(int i=MAXN-2;i>=0;i--) invfac[i]=invfac[i+1]*(i+1)%P;
}

LL getC(int x,int y){
	if(x<y) return 0;
	return fac[x]*invfac[y]%P*invfac[x-y]%P;
}

void FFT(LL *a,int len,int flag){
	static int rev[MAXN];
	rev[0]=0;
	for(int i=1;i<len;i++) rev[i]=rev[i>>1]>>1|((i&1)?(len>>1):0);
	for(int i=0;i<len;i++)
		if(i<rev[i]) 
			swap(a[i],a[rev[i]]);
	for(int l=2;l<=len;l<<=1){
		LL w=getPow(3,(P-1)/l);
		int l2=l/2;
		for(int i=0;i<len;i+=l){
			LL temp=1;
			for(int j=0;j<l2;j++){
				LL t1=a[i+j],t2=a[i+j+l2]*temp%P;
				a[i+j]=(t1+t2)%P;
				a[i+j+l2]=(t1-t2)%P;
				temp=temp*w%P;
			}
		}
	}
	if(flag==-1){
		LL invn=getPow(len,P-2);
		for(int i=0;i<len;i++)
			a[i]=a[i]*invn%P;
		for(int i=1;i<len;i++)
			if(i<len-i)
				swap(a[i],a[len-i]);
	}
}

