    for (int i = 1; i <= n; ++i)
        fac[i] = fac[i - 1] * i % mod;
    inf[n] = power(fac[n], mod - 2);
    for (int i = n - 1; i >= 1; --i)
        inf[i] = inf[i + 1] * (i + 1) % mod;
}

