		}
		return 1;
	}
	int calg(int p) {
		vp.clear();
		int t = p-1;
		for (int i = 2; i * i <= t; i++) {
			if (t % i == 0) {
				while (t % i == 0) t /= i;
				vp.push_back(i);
			}
		}
		for (int i = 2; i <= p; i++) {
			if (checkg(p, i)) {
				return i;
			}
		}
		return -1;
	}
	int wa[maxn*4], wb[maxn*4], wc[maxn*4], rev[maxn*4];
	void ntt(int *a, int _l, int ty) {
		int len = (1 << _l);
		for (int i = 1; i < len; i++) rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (_l - 1));
		for (int i = 0; i < len; i++) if (i < rev[i]) swap(a[i], a[rev[i]]);
		for (int l = 2; l <= len; l <<= 1) {
			int wl = qpow(g, (mod - 1) / l, mod);
			for (int s = 0; s < len; s += l) {
				int w = 1;
				for (int i = 0; i < (l >> 1); i++) {
					int v1 = a[s + i], v2 = 1LL * a[s + i + (l >> 1)] * w % mod;
					a[s + i] = (v1 + v2) % mod;
					a[s + i + (l >> 1)] = (v1 - v2 + mod) % mod;
					w = 1LL * w * wl % mod;
				}
			}
		}
		if (ty == -1) {
			int inv = qpow(len, mod-2, mod);
			for (int i = 0; i < len; i++) a[i] = 1LL * a[i] * inv % mod;
			for (int i = 1; i < len / 2; i++) swap(a[i], a[len-i]);
		}
	}
	int fac[maxn], ifac[maxn];
	void calans() {
		fac[0] = ifac[0] = 1;
		for (int i = 1; i <= n; i++) fac[i] = 1LL * fac[i-1] * i % mod;
		for (int i = 1; i <= n; i++) ifac[i] = qpow(fac[i], mod-2, mod);
		for (int i = 0; i <= n; i++) wa[i] = 1LL * a[i] * fac[i] % mod;
		for (int i = 0; i <= n; i++) wb[i] = ifac[n - i];
		int t = 0; while ((1<<t) <= 2 * n) ++ t;
		ntt(wa, t, 1); ntt(wb, t, 1);
		for (int i = 0; i < (1<<t); i++) wc[i] = 1LL * wa[i] * wb[i] % mod;
		ntt(wc, t, -1);
		for (int i = 1; i <= n; i++) ans[i] = (1LL * ifac[i] * wc[n+i] % mod + 1LL * fac[n] * ifac[i] % mod * ifac[n-i] % mod) % mod;
	}
}

