int rec(int idx, int par) {
  sub[idx] = 1;
  for(auto &to : g[idx]) {
    if(to == par) continue;
    sub[idx] += rec(to, idx);
  }
  return sub[idx];
}

void rec2(int idx, int par) {
  for(auto &to : g[idx]) {
    if(to == par) continue;
    v.emplace_back(N - sub[to]);
    v.emplace_back(sub[to]);
    rec2(to, idx);
  }
}


int64_t mod_pow(int64_t x, int64_t n) {
  int64_t ret = 1;
  while(n > 0) {
    if(n & 1) (ret *= x) %= mod;
    (x *= x) %= mod;
    n >>= 1;
  }
  return (ret);
}

int main() {

  fact[0] = 1;
  for(int i = 1; i < 200001; i++) {
    (fact[i] = fact[i - 1] * i) %= mod;
  }
  ifact[200000] = mod_pow(fact[200000], mod - 2);
  for(int i = 199999; i >= 0; i--) {
    ifact[i] = ifact[i + 1] * (i + 1) % mod;
  }

  scanf("%d", &N);
  for(int i = 1; i < N; i++) {
    int x, y;
