  }

  NumberTheoreticTransform ntt(mod, 5);
  auto ret = ntt.Multiply(P, Q);
  for(int i = 1; i <= N; i++) {
    int64 ans = N * fact[N] % mod * ifact[i] % mod * ifact[N - i] % mod;
    (ans += mod - (ret[N + i] * ifact[i] % mod)) %= mod;
    printf("%lld\n", ans);
  }
}

