inline void addedge(ll u,ll v)
{
	G[u].push_back(v);
	G[v].push_back(u);
}

inline ll qpow(ll x,ll k)
{
	ll res=1;
	for(ll i=k; i; i>>=1,x=1ll*x*x%mod)
		if(i&1) res=1ll*res*x%mod;
	return res;
}

inline void init(ll n)
{
	for(ll i=fac[0]=1; i<=n; ++i)
		fac[i]=1ll*fac[i-1]*i%mod;
	ifac[n]=qpow(fac[n],mod-2);
	for(ll i=n; i; --i)
		ifac[i-1]=1ll*ifac[i]*i%mod;
}

inline ll cat(ll n,ll k)
{return 1ll*fac[n]*ifac[k]%mod*ifac[n-k]%mod;}

inline void dfs(ll x,ll fa)
{
	sz[x]=1;
	for(auto y : G[x])
		if(y^fa) dfs(y,x),sz[x]+=sz[y],++cnt[sz[y]];
	++cnt[n-sz[x]];
}

inline void ntt(ll *a,ll n,ll type)
{
	for(ll i=0; i<n; ++i) if(i<rev[i]) swap(a[i],a[rev[i]]);
	for(ll i=1; i<n; i<<=1)
	{
		ll rt=qpow(5,(mod-1)/(i<<1));
		if(type==-1) rt=qpow(rt,mod-2);
		for(ll j=0; j<n; j+=(i<<1))
			for(ll k=0,w=1; k<i; ++k,w=1ll*w*rt%mod)
			{
				ll x=a[j+k],y=1ll*w*a[j+k+i]%mod;
				a[j+k]=(x+y)%mod,a[j+k+i]=(x-y+mod)%mod;
			}
	}
	if(type!=-1) return;
	ll inv=qpow(n,mod-2);
	for(ll i=0; i<n; ++i)
		a[i]=1ll*a[i]*inv%mod;
}

int main(int argc, char const *argv[])
{
	n=read();
	for(ll i=1; i<n; ++i) addedge(read(),read());
	dfs(1,0); init(n);
	for(ll i=1; i<=n; ++i)
		f[i]=1ll*cnt[i]*fac[i]%mod;
	reverse(f,f+n+1);
	for(ll i=0; i<=n; ++i) g[i]=ifac[i];
	ll lim=1,l=0;
	while(lim<=n+n) lim<<=1,++l;
	for(ll i=0; i<lim; ++i)
		rev[i]=(rev[i>>1]>>1)|((i&1)<<(l-1));
	ntt(f,lim,1),ntt(g,lim,1);
	for(ll i=0; i<lim; ++i) f[i]=1ll*f[i]*g[i]%mod;
	ntt(f,lim,-1); reverse(f,f+n+1);
	for(ll i=1; i<=n; ++i)
		printf("%lld\n",(1ll*n*cat(n,i)%mod
		                 -1ll*ifac[i]*f[i]%mod+mod)%mod);
	return 0;
}

