inline long long power(long long x,long long y){
	long long Ans=1;
	while(y){
		if(y&1) Ans=Ans*x%Mod;
		x=x*x%Mod;
		y>>=1;
	}
	return Ans;
}

void NTT(long long *A,int n,int type){
	register int i,j,k,mid,R;
	register long long Wn,W,x,y;
	for(i=0;i<n;i++) if(i<r[i]) swap(A[i],A[r[i]]);
	for(mid=1;mid<n;mid<<=1){
		Wn=power(G,(Mod-1)/(mid<<1));
		if(type==-1) Wn=power(Wn,Mod-2);
		for(R=mid<<1,j=0;j<n;j+=R){
			W=1;
			for(k=0;k<mid;k++,W=W*Wn%Mod){
				x=A[j+k],y=W*A[j+mid+k]%Mod;
				A[j+k]=(x+y)%Mod;
				A[j+k+mid]=(x-y+Mod)%Mod;
			}
		}
	}
	if(type==-1){
		int Inv=power(n,Mod-2);
		for(i=0;i<=n;i++) A[i]=A[i]*Inv%Mod;
	}
	return;
}

inline void Mul(long long *A,long long *B,int N){
	NTT(A,N,1);NTT(B,N,1);
	for(register int i=0;i<=N;i++) A[i]=A[i]*B[i]%Mod;
	NTT(A,N,-1);
	return;
}

