  }
  inv[n] = modexp(fac[n], P - 2, P);
  for (int i = n - 1; i >= 0; --i) {
    inv[i] = (long long) inv[i + 1] * (i + 1) % P;
  }
  for (int i = 1; i <= n; ++i) {
