void dfs(int a, int b) {
	sz[a] = 1;
	trav(t,adj[a]) if (t != b) {
		dfs(t,a);
		cnt[sz[t]] ++, cnt[N-sz[t]] ++;
		sz[a] += sz[t];
	}
}

