inline int inc(int a, int b) { return (a + b >= MOD) ? (a + b - MOD) : (a + b); }
inline int dec(int a, int b) { return (a >= b) ? (a - b) : (a + MOD - b); }
inline int mul(int a, int b) { return 1LL * a * b % MOD; }

inline int power(int x, int k) {
	int tmp = 1;
	while(k) {
		if(k & 1) tmp = mul(tmp,x);
		x = mul(x,x);
		k >>= 1;
	}
	return tmp;
}

inline void rader(int *a, int len) {
	for(int i = 0, j = 0;i < len - 1;i ++) {
		if(i < j) swap(a[i],a[j]);
		int k = (len >> 1);
		while(j >= k) {
			j -= k;
			k >>= 1;
		}
		if(j < k) j += k;
	}
}

inline void ntt(int *a, int len, int kd) {
	rader(a,len);
	for(int i = 2;i <= len;i <<= 1) {
		int pn = power(G,(MOD - 1) / i);
		for(int j = 0;j < len;j += i) {
			int p = 1;
			for(int k = 0;k < (i >> 1);k ++) {
				int x = a[k + j], y = mul(a[k + j + (i >> 1)],p);
				a[k + j] = inc(x,y);
				a[k + j + (i >> 1)] = dec(x,y);
				p = mul(p,pn);
			}
		}
	}
	if(kd == -1) {
		for(int i = 1;i < (len >> 1);i ++) swap(a[i],a[len - i]);
		int invn = power(len,MOD - 2);
		for(int i = 0;i < len;i ++) a[i] = mul(a[i],invn);
	}
}

