int ksm(int a,int b,int mod)
{
	int s=1;
	while (b>0)
	{
		if (b&1) s=(long long)s*a%mod;
		a=(long long)a*a%mod,b>>=1;
	}
	return s;
}
void Pre(int N)
{
	fac[0]=1;
	for (int i=1;i<=N;i++) fac[i]=(long long)fac[i-1]*i%mod;
	inv[N]=ksm(fac[N],mod-2,mod);
	for (int i=N-1;i>=0;i--) inv[i]=(long long)inv[i+1]*(i+1)%mod;
}
int C(int a,int b)
{
	return (long long)fac[a]*fac[b]%mod*fac[a-b]%mod;
}
void addedge(int u,int v)
{
	edgenum++,vet[edgenum]=v,nex[edgenum]=head[u],head[u]=edgenum;
}

void dfs(int u,int pre)
{
	siz[u]=1;
	for (int i=head[u];i!=0;i=nex[i])
		if (vet[i]!=pre) dfs(vet[i],u),siz[u]+=siz[vet[i]];
	num[siz[u]]=(num[siz[u]]+mod-1)%mod;
	if (pre!=0) num[n-siz[u]]=(num[n-siz[u]]+mod-1)%mod;
}

int calcg(int p)
{
	int m=p-1,tot=0;
	for (int i=2;i<=sqrt(p);i++)
		if (m%i==0)
		{
			pr[++tot]=i;
			while (m%i==0) m/=i;
		}
	if (m>1) pr[++tot]=m;
	for (int i=2;;i++)
	{
		int flag=0;
		for (int j=1;j<=tot;j++)
			if (ksm(i,(p-1)/pr[j],p)==1) {flag=1;break;}
		if (flag==0) return i;
	}
	return 0;

}

void NTT(int *num,int len,int flag)
{
	for (int i=0;i<len;i++)
		re[i]=(re[i>>1]>>1)+(i&1)*(len>>1);
	for (int i=0;i<len;i++)
		if (i<re[i]) swap(num[i],num[re[i]]);

	for (int i=1;i<len;i<<=1)
	{
		int w0=ksm(G[flag],(mod-1)/i/2,mod);
		for (int j=0;j<len;j+=i+i)
			for (int r=0,k=1;r<i;r++,k=(long long)k*w0%mod)
			{
				int x=num[j+r],y=(long long)num[i+j+r]*k%mod;
				num[j+r]=(x+y)%mod,num[i+j+r]=(x-y+mod)%mod;
			}
	}
	int invn=ksm(len,mod-2,mod);
	if (flag==1)
		for (int i=0;i<len;i++) num[i]=(long long)num[i]*invn%mod;
}

