void dfs(int x){
  used[x]=1;
  ct[x]=1;
  for(auto y:g[x]){
    if(!used[y]){
      dfs(y);
      ct[x]+=ct[y];
      c[ct[y]]++;
    }
  }
  c[n-ct[x]]++;
}
vector<ll> add(vector<ll> a, vector<ll> b){
  int m=max(a.size(), b.size());
  vector<ll> ret(m, 0);
  for(int i=0; i<a.size(); i++){
    ret[i]=a[i];
  }
  for(int i=0; i<b.size(); i++){
    ret[i]+=b[i];
    if(ret[i]>=MOD) ret[i]-=MOD;
  }
  return ret;
}
vector<ll> solve(int l, int r){
  if(l==r){
    vector<ll> ret(1, c[l]);
    return ret;
  }
  int m=(l+r)/2;
  vector<ll> p=solve(l, m);
  vector<ll> q0(m+2-l);
  for(int i=0; i<=m+1-l; i++){
    q0[i]=comb(m+1-l, i);
  }
  vector<ll> q1=solve(m+1, r);
