void FFT_init(int n){
    lgn_=32-clz(n-1);n_=1<<lgn_;
    rev_[0]=0;omg_[0]=1;
    ll d=ksm(w_,441<<(21-lgn_));
    for(int i=1;i<n_;i++){
        omg_[i]=omg_[i-1]*d%mod;
        rev_[i]=rev_[i/2]>>1|(i&1)<<(lgn_-1);
    }
}

ll ww[N];
void FFT(int*a,int fg=0){
    for(int i=0;i<n_;i++)if(rev_[i]<i)swap(a[i],a[rev_[i]]);
    int s,t;
    for(int i=0;i<lgn_;i++){
        t=1<<i;
        for(int j=0;j<1<<i;++j)ww[j]=omg_[j<<(lgn_-i-1)];
        for(int j=0;j<n_;j+=t<<1){
            int*at=a+j,*bt=a+j+t;
            for(int k=0;k<t;++k){
                s=ww[k]*bt[k]%mod;
                bt[k]=at[k]-s;bt[k]+=bt[k]>>31&mod;
				at[k]+=s-mod;at[k]+=at[k]>>31&mod;
            }
        }
    }
    if(fg){
        reverse(a+1,a+n_);
        ll iv=ksm(n_,mod-2);
        for(int i=0;i<n_;++i)a[i]=a[i]*iv%mod;
    }
}

int C(int n,int k){
	if(k<0)return 0;
	if(n<0){
		int res=C(k-n-1,k);
		if(k&1)return (mod-res)%mod;
		else return res;
	}
	if(n<k)return 0;
	return (ll)jc[n]*jc2[k]%mod*jc2[n-k]%mod;
}
