        vector<vector<sum_t>>& g_dp,
        vector<vector<sum_t>>& g_ndp,
        vector<vector<sum_t>>& memo,
        vector<vector<bool>>& seen) {
        for (int i = 0; i < (int)((*this)[idx].size()); i++) {
            auto& e = (*this)[idx][i];
            if (e.to == par)
                continue;
            ReRooting_dfs_sub<sum_t>(e.to, idx, f, gg, ident, subdp, dp, g_dp, g_ndp, memo, seen);
            if (!seen[idx][i]) {
                memo[idx][i] = gg(subdp[e.to], e);
                seen[idx][i] = true;
            }
            subdp[idx] = f(subdp[idx], memo[idx][i]);
        }
    }
    template <typename sum_t>
    void ReRooting_dfs_all(int idx, int par, const sum_t& top,
        const function<sum_t(sum_t, sum_t)>& f,
        const function<sum_t(sum_t, Edge)>& gg,
        const sum_t& ident,
        vector<sum_t>& subdp,
        vector<sum_t>& dp,
        vector<vector<sum_t>>& g_dp,
        vector<vector<sum_t>>& g_ndp,
        vector<vector<sum_t>>& memo,
        vector<vector<bool>>& seen) {
        sum_t buff{ident};
        for (int i = 0; i < (int)((*this)[idx].size()); i++) {
            auto& e = (*this)[idx][i];
            g_ndp[idx][i] = buff;
            if (!seen[idx][i]) {
                memo[idx][i] = gg(par == e.to ? top : subdp[e.to], e);
                seen[idx][i] = true;
            }
            g_dp[idx][i] = memo[idx][i];
            buff = f(buff, g_dp[idx][i]);
        }
        dp[idx] = buff;
        buff = ident;
        for (int i = (*this)[idx].size() - 1; i >= 0; i--) {
            auto& e = (*this)[idx][i];
            if (e.to != par)
                ReRooting_dfs_all<sum_t>(e.to, idx, f(g_ndp[idx][i], buff), f, gg, ident, subdp, dp, g_dp, g_ndp, memo, seen);
            g_ndp[idx][i] = f(g_ndp[idx][i], buff);
            buff = f(buff, g_dp[idx][i]);
        }
    }
