	fac[0]=1;
	for(int i=1;i<=n;i++) fac[i]=1ll*i*fac[i-1]%D;
	inv[n]=qpow(fac[n],D-2);
	for(int i=n-1;~i;i--) inv[i]=1ll*inv[i+1]*(i+1)%D;
}
int C(int x,int y) {
	return 1ll*fac[x]*inv[y]%D*inv[x-y]%D;
}

int main() {
	scanf("%d",&n);
	first();
	for(int i=1;i<n;i++) {
		int x,y; scanf("%d%d",&x,&y);
