	for(int i=2;i<=n;i++)
		++A[siz[i]],++A[n-siz[i]];
	for(int i=0;i<=n;i++)
		A[i]=1ll*A[i]*fac[i]%D;
	for(int i=0;i<=n;i++)
		B[i]=inv[i];
	reverse(B,B+n+1);

	int lim; for(lim=1;lim<=(n<<1);lim<<=1);
	for(int i=1;i<lim;i++)
		rev[i]=(rev[i>>1]>>1)|(i&1?lim>>1:0);
	NTT(A,1,lim),NTT(B,1,lim);
	for(int i=0;i<lim;i++)
		A[i]=1ll*A[i]*B[i]%D;
	NTT(A,-1,lim);

	for(int i=1;i<=n;i++)
		ans[i]=((1ll*C(n,i)*n-1ll*inv[i]*A[n+i])%D+D)%D;

	for(int i=1;i<=n;i++)
