namespace Poly {
    int n;

    void init(int _n) {
        n = _n;
        while(n > (n & -n)) n += (n & -n);
    }

    void dft(int *x, int ty) {
        for(int i = 0, j = 0; i < n; ++i) {
            if(i < j) std::swap(x[i], x[j]);
            for(int l = n >> 1; (j ^= l) < l; l >>= 1);
        }

        for(int l = 1; l < n; l <<= 1) {
            int wn = fpm(g, (mo - 1) / l / 2);
            if(ty == -1) wn = fpm(wn, mo - 2);

            for(int i = 0; i < n; i += l << 1) {
                int w = 1;
                for(int j = 0; j < l; ++j) {
                    int u = x[i + j];
                    int v = (ll) x[i + j + l] * w % mo;

                    x[i + j] = (u + v) % mo;
                    x[i + j + l] = (u - v + mo) % mo;
                    w = (ll) w * wn % mo;
                }
            }
        }

        if(ty == -1) {
            int inv = fpm(n, mo - 2);
            for(int i = 0; i < n; ++i) {
                x[i] = (ll) x[i] * inv % mo;
            }
        }
    }
}

