const int SN = 524288;

const int MOD = 924844033;

const int phi = MOD - 1;

const int g = 5;

LL A[SN], B[SN], jie[SN], inv_jie[SN], Ans[SN];

int size[SN], head[SN], rev[SN], LG, m, num, n;

