    }	

}

LL ksm(LL a, LL b) {
    LL ans = 1, B = a;
    while(b) {
	if(b & 1) ans = (ans * B) % MOD;
	B = (B * B) % MOD;
	b >>= 1;
    }
    return ans;
}

void NTT(LL *f, int n, int d) {

    for(int i = 1; i < n; i++)
	if(rev[i] > i) std :: swap(f[rev[i]], f[i]);

    for(int i = 1; i < n; i <<= 1) {
	LL w = ksm(g, phi / (i << 1));
	if(d == -1) w = ksm(w, MOD - 2);
	for(int j = 0; j < n; j += (i << 1)) {
	    LL wn = 1;
	    for(int k = 0; k < i; k++, wn = (wn * w) % MOD) {
		LL u = f[j + k], v = (f[j + k + i] * wn) % MOD;
		f[j + k] = (u + v) % MOD, f[j + k + i] = (u - v + MOD) % MOD;
	    }
	}
    }

    if(d == -1) {
	LL inv = ksm(n, MOD - 2);
	for(int i = 0; i < n; i++)
	    f[i] = (f[i] * inv) % MOD;
    }
}

LL C(LL n, LL m) {
    if(n < m) return 0;
    return jie[n] * inv_jie[m] % MOD * inv_jie[n - m] % MOD;
}

int main() {

    int x, y;

    Read(n);

    for(int i = 1; i < n; i++) Read(x), Read(y), Add_E(x, y);

    Dfs(1, 0);

    for(int i = 1; i <= n; i++) B[size[i]]++, B[n - size[i]]++;

    B[0] = 0, jie[0] = 1;

    for(int i = 1; i <= n; i++) jie[i] = (jie[i - 1] * i) % MOD;

    inv_jie[n] = ksm(jie[n], MOD - 2);

    for(int i = n - 1; i >= 0; i--)
	inv_jie[i] = (inv_jie[i + 1] * (i + 1)) % MOD;

    for(int i = 0; i <= n; i++)
	A[i] = inv_jie[n - i], B[i] = B[i] * jie[i] % MOD;

    for(m = 1; m <= (n + n); m <<= 1) LG++;

    for(int i = 1; i < m; i++) rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (LG - 1));

    NTT(A, m, 1), NTT(B, m, 1);

    for(int i = 0; i < m; i++) A[i] = (A[i] * B[i]) % MOD;

    NTT(A, m, -1);

    for(int i = 1; i <= n; i++) Ans[i] = A[i + n];

    for(int i = 1; i <= n; i++) Ans[i] = (Ans[i] * inv_jie[i]) % MOD;

    for(int i = 1; i <= n; i++) Ans[i] = (n * C(n, i) % MOD - Ans[i] + MOD) % MOD;

    for(int i = 1; i <= n; i++) printf("%lld\n", (Ans[i] + C(n, i)) % MOD); 

    return 0;
}

