inline int ksm(int x, int y, int z)
{
	int b = 1;
	while (y)
	{
		if (y & 1) b = 1ll * b * x % z;
		x = 1ll * x * x % z;
		y >>= 1;
	}
	return b;
}
inline int ntt_init(int m)
{
	int n = 1, nn = 0;
	while (n <= m) n <<= 1, nn ++;
	int g = ksm(5, (MOD - 1) / n, MOD);
	f[0] = 1;
	for(int i = 1; i < n; i ++)
		f[i] = 1ll * f[i - 1] * g % MOD, bit[i] = (bit[i >> 1] >> 1) | ((i & 1) << nn - 1);
	return nn;
}
inline void ntt(int *a, int nn, int ty)
