int fpow(int x, int p)
{
	int ret = 1;
	for(; p; p >>= 1, x = (long long)x * x % MOD)
		if(p & 1)
			ret = (long long)ret * x % MOD;
	return ret;
}

bool check_primitive(int x, int p)
{
	int tmp = p - 1;
	for(int i = 1; i * i <= tmp; i++)
		if(tmp % i == 0)
		{
			if(i != tmp && fpow(x, i) == 1) return false;
			if(tmp / i != tmp && fpow(x, tmp / i) == 1) return false;
		}
	return true;
}

namespace myNTT
{
	int rev[4 * MAXN], w1[4 * MAXN], w2[4 * MAXN];

	void NTT_core(int n, int *a, int *w)
	{
		for(int i = 0; i < n; i++)
			if(i < rev[i])
				swap(a[i], a[rev[i]]);
		for(int i = 1; i < n; i <<= 1)
			for(int j = 0; j < n; j += 2 * i)
				for(int k = 0; k < i; k++)
				{
					int x = a[j + k], y = (long long)a[j + k + i] * w[i + k] % MOD;
					a[j + k] = (x + y) % MOD;
					a[j + k + i] = (x - y + MOD) % MOD;
				}
	}

	void NTT(int n, int *a)
	{
		NTT_core(n, a, w1);
	}

	void INTT(int n, int *a)
	{
		NTT_core(n, a, w2);
		int inv = fpow(n, MOD - 2);
		for(int i = 0; i < n; i++)
			a[i] = (long long)a[i] * inv % MOD;
	}

	void init(int n)
	{
		int l = log2(n) + 0.5;
		rev[0] = 0;
		for(int i = 1; i < n; i++)
			rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (l - 1));
		int wn = fpow(PRIMITIVE_ROOT, (MOD - 1) / n), half = n / 2;
		w1[half] = 1;
		for(int i = 1; i < half; i++)
			w1[half + i] = (long long)w1[half + i - 1] * wn % MOD;
		for(int i = half - 1; i >= 0; i--)
			w1[i] = w1[i << 1];
		wn = fpow(wn, MOD - 2);
		w2[half] = 1;
		for(int i = 1; i < half; i++)
			w2[half + i] = (long long)w2[half + i - 1] * wn % MOD;
		for(int i = half - 1; i >= 0; i--)
			w2[i] = w2[i << 1];
	}

	void conv_ntt(int n, int *a, int m, int *b, int *c)
	{
		static int A[4 * MAXN], B[4 * MAXN], C[4 * MAXN];
		int N = 1;
		while(N < n + m - 1) N <<= 1;
		init(N);
		for(int i = 0; i < N; i++) A[i] = B[i] = C[i] = 0;
		for(int i = 0; i < n; i++) A[i] = a[i];
		for(int i = 0; i < m; i++) B[i] = b[i];
		NTT(N, A), NTT(N, B);
		for(int i = 0; i < N; i++)
			C[i] = (long long)A[i] * B[i] % MOD;
		INTT(N, C);
		for(int i = 0; i < n + m - 1; i++)
			c[i] = C[i];
	}

	void conv_force(int n, int *a, int m, int *b, int *c)
	{
		static int C[4 * MAXN];
		for(int i = 0; i < n + m - 1; i++)
			C[i] = 0;
		for(int i = 0; i < n; i++)
			for(int j = 0; j < m; j++)
				C[i + j] = (C[i + j] + (long long)a[i] * b[j]) % MOD;
		for(int i = 0; i < n + m - 1; i++)
			c[i] = C[i];
	}

	void conv(int n, int *a, int m, int *b, int *c)
	{
		if(n <= 2333)
			conv_force(n, a, m, b, c);
		else
			conv_ntt(n, a, m, b, c);
	}
}

