ll modpow(ll x, ll n){
    if (n == 0) return 1LL;
    ll tmp = modpow(x, n / 2);
    if (n % 2 == 0) return tmp * tmp % mod;
    return tmp * tmp % mod * x % mod;
}

ll inverse(ll x){
    return modpow(x, mod - 2);
}

void ntt(vector<ll>& a, bool rev = false){
    const int size = a.size();
    if(size == 1) return;
    vector<ll> b(size);
    ll r = rev ? (mod - 1 - (mod - 1) / size) : (mod - 1) / size;
    ll s = modpow(root, r);
    vector<ll> kp(size / 2 + 1, 1);
    for(int i = 0; i < size / 2; ++i) kp[i + 1] = kp[i] * s % mod;
    for(int i = 1, l = size / 2; i < size; i <<= 1, l >>= 1){
        for(int j = 0, r = 0; j < l; ++j, r += i){
            for(int k = 0, s = kp[i * j]; k < i; ++k){
                ll p = a[k + r], q = a[k + r + size / 2];
                b[k + 2 * r] = (p + q) % mod;
                b[k + 2 * r + i] = ((p - q) % mod + mod) % mod * s % mod;
            }
        }
        swap(a, b);
    }
    if(rev){
        s = inverse(size);
        for(int i = 0; i < size; i++){ a[i] = a[i] * s % mod; }
    }
}

vector<ll> convolute(vector<ll>& a, vector<ll>& b){
    const int size = (int)a.size() + (int)b.size() - 1;
    int t = 1;
    while(t < size){ t <<= 1; }
    vector<ll> A(t, 0), B(t, 0);
    for(int i = 0; i < (int)a.size(); i++){ A[i] = a[i]; }
    for(int i = 0; i < (int)b.size(); i++){ B[i] = b[i]; }
    ntt(A), ntt(B);
    for (int i = 0; i < t; i++){ A[i] = A[i] * B[i] % mod; }
    ntt(A, true);
    A.resize(size);
    return A;
}

ll fact(ll k, int sgn = 0) {
	static vector<ll> fac(2, 1LL);
	static vector<ll> inv(2, 1LL);
	static vector<ll> finv(2, 1LL);
	static ll nx = 2LL;
	while (nx <= k) {
		fac.push_back(fac[nx - 1] * nx % mod);
		inv.push_back(mod - inv[mod % nx] * (mod / nx) % mod);
		finv.push_back(finv[nx - 1] * inv[nx] % mod);
		++nx;
	}
	if (sgn == 0)
		return fac[k];
	return finv[k];
}

ll comb(ll a, ll b) {
	if (b < 0 || b > a) return 0;
	return fact(a) * fact(b, 1) % mod * fact(a - b, 1) % mod;
}

