int n, a[N], tn = 0, tl = 0;
int w[2][600005], rev[600005];
void pret(int n){
	for(tn = 1, tl = -1; tn <= n; tn <<= 1, tl ++);
	int W = Pow(G, (P - 1) / tn, P), IW = Pow(W, P - 2, P);
	w[0][0] = w[1][0] = 1;
	FOR(i, 1, tn){
		w[0][i] = (LL)w[0][i - 1] * W % P;
		w[1][i] = (LL)w[1][i - 1] * IW % P;
	}
	FOR(i, 0, tn){
		rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << tl); 
	}
}

void fft(int *a, int f){
	FOR(i, 0, tn) if(i < rev[i]) swap(a[i], a[rev[i]]);
	for(int i = 1; i < tn; i <<= 1)
	for(int j = 0, t = tn / (i << 1); j < tn; j += i << 1)
	for(int k = 0, l = 0; k < i; k ++, l += t){
		int x = (LL)w[f][l] * a[j + k + i] % P;
		int y = a[j + k];
		a[j + k] = (y + x) % P;
		a[j + k + i] = (y + P - x) % P;
	}
	if(f){
		int invn = Pow(tn, P - 2, P);
		FOR(i, 0, tn) a[i] = (LL)a[i] * invn % P;
	}
}

