    {
        if(y&1)ret=1LL*ret*x%mod;
        x=1LL*x*x%mod;
        y>>=1;
    }
    return ret;
}
void init()
{
    fac[0]=1;
    for(int i=1;i<maxn;i++)fac[i]=1LL*i*fac[i-1]%mod;
    inv[maxn-1]=qpow(fac[maxn-1],mod-2);
    for(int i=maxn-2;i>=0;i--)inv[i]=1LL*inv[i+1]*(i+1)%mod;
}
void getwn(int len)
{
    wn[0]=1;
    wn[1]=qpow(G,(mod-1)/len);
    int i;
    for(i=2;i<=len;i++) wn[i]=wn[i-1]*wn[1]%mod;
}
void NTT(long long *a,int len,int on){
    int i;
    long long ni=qpow(len,mod-2);
    for(i=0;i<len;i++){
        int p=0;
        double ce=log(len)/log(2);
        for(int j=0,tp=i;j<ce;j++,tp/=2) p=(p<<1)+(tp%2);
        tmp[p]=a[i];
    }
    for (int m=2;m<=len;m*=2){
        int half=m/2,bei=len/m;
        for(i=0;i<half;i++){
            long long wi=on>0?wn[i*bei]:wn[len-i*bei];
            for(int j=i;j<len;j+=m){
                long long u=tmp[j],v=tmp[j+half]*wi%mod;
                tmp[j]=(u+v)%mod;
                tmp[j+half]=(u-v+mod)%mod;
            }
        }
    }
    if (on==-1)
        for(i=0;i<len;i++) tmp[i]=tmp[i]*ni%mod;
    for(i=0;i<len;i++) a[i]=tmp[i];
}
