int power(int a, int b) {
    int t = 1;
    for (; b; b >>= 1, a = (ll)a * a % P)
        if (b & 1) t = (ll)t * a % P;
    return t;
}
void NTT(int* a, int n, int t) {
    for (int i = 1, j = 0; i < n - 1; i++) {
        for (int s = n; j ^= s >>= 1, ~j & s;)
            ;
        if (i < j) {
            int k = a[i];
            a[i] = a[j];
            a[j] = k;
        }
    }
    for (int d = 0; (1 << d) < n; d++) {
        int m = 1 << d, m2 = m << 1, _w = t == 1 ? g[d] : ng[d];
        for (int i = 0; i < n; i += m2)
            for (int w = 1, j = 0; j < m; j++) {
                int &A = a[i + j + m], &B = a[i + j], t = (ll)w * A % P;
                A = B - t;
                if (A < 0) A += P;
                B = B + t;
                if (B >= P) B -= P;
                w = (ll)w * _w % P;
            }
    }
    if (t == -1)
        for (int i = 0, j = inv[n]; i < n; i++) a[i] = (ll)a[i] * j % P;
}
int f[N + 10], rf[N + 10];
void init() {
    g[K] = power(G, (P - 1) / N), ng[K] = power(g[K], P - 2);
    for (i = K - 1; ~i; i--)
        g[i] = (ll)g[i + 1] * g[i + 1] % P,
        ng[i] = (ll)ng[i + 1] * ng[i + 1] % P;
    for (inv[1] = 1, i = 2; i <= N; i++)
        inv[i] = (ll)(P - inv[P % i]) * (P / i) % P;
    inv2 = inv[2];
    f[0] = 1;
    for (int i = 1; i <= N; i++) f[i] = (ll)f[i - 1] * i % P;
    rf[N] = power(f[N], P - 2);
    for (int i = N; i; i--) rf[i - 1] = (ll)rf[i] * i % P;
}
int C(int n, int m) {
    if (n < m || m < 0) return 0;
    return (ll)f[n] * rf[m] % P * rf[n - m] % P;
}
int ans[N + 10], sz[N + 10], cnt[N + 10];
void dfs(int x, int fx) {
    sz[x] = 1;
    for (auto y : v[x]) {
        if (y == fx) continue;
        dfs(y, x);
        sz[x] += sz[y];
    }
    if (fx) ++cnt[n - sz[x]], ++cnt[sz[x]];
}
