void dfs(int f,int x){
	ref(i,0,SZ(e[x])-1){int y=e[x][i];if(y!=f)dfs(x,y),s[x]+=s[y];}
	if(x>1)A[s[x]]++,A[n-s[x]]++;
}
int mi(int a,int b,int s=1){
	for(;b;b>>=1,a=(LL)a*a%M)if(b&1)s=(LL)s*a%M;
	return s;
}
void esbs(int L){
	ref(i,1,L-1)r[i]=r[i>>1]>>1|((i&1)?(L>>1):0);
	for(int i=1;i<L;i<<=1)
		for(int j=0,W=1,w=mi(G,(M-1)/(i<<1));j<i;++j,W=(LL)W*w%M)t[i+j]=W;
}
void dft(vec&a){
	int L=SZ(a);
	for(int i=1;i<L;++i)if(r[i]<i)swap(a[r[i]],a[i]);
	for(int i=1;i<L;i<<=1)
		for(int j=0;j<L;j+=(i<<1))
			for(int k=0;k<i;++k){
				int w=(LL)a[i+j+k]*t[i+k]%M;
				a[i+j+k]=a[j+k]-w;if(a[i+j+k]<0)a[i+j+k]+=M;
				a[j+k]+=w;if(a[j+k]>=M)a[j+k]-=M;
			}
}
void idft(vec&a){
	dft(a);int L=SZ(a),w=mi(L,M-2);
	ref(i,1,(L>>1)-1)swap(a[i],a[L-i]);
	ref(i,0,L-1)a[i]=(LL)a[i]*w%M;
}
