	for (int i = 2; i <= n ; i <<= 1) {
		if (fl) wn = mul(invG, (mo - 1) / i) ; else wn = mul(G, (mo - 1) / i) ;
		for (int j = 0; j < n; j += i) 
		  for (int w = 1, q = j; q < j + i / 2; q ++, w = (ll) w * wn % mo) {
			  u = a[x][q], v = (ll) a[x][q + i / 2] * w % mo ;
			  a[x][q] = (u + v) % mo, a[x][q + i / 2] = (u - v) % mo ;
		  }
