  a.resize(t); ntt(a);
  b.resize(t); ntt(b);
  rep(i, t) a[i] = mul(a[i], b[i]);
  ntt(a, true);
  a.resize(size);
}

V shift(V poly, int c) {
  int n = poly.size();
  V inv(n + 1), fact(n + 1), invfact(n + 1);
  inv[1] = invfact[1] = invfact[0] = fact[0] = fact[1] = 1;
  for (int i = 2; i <= n; i++) {
    fact[i] = mul(fact[i - 1], i);
    inv[i] = mul(inv[MOD % i], MOD - MOD / i);
    invfact[i] = mul(invfact[i - 1], inv[i]);
  }
  for (int i = 0; i < poly.size(); i++) {
    poly[i] = mul(poly[i], fact[i]);
  }
  int val = 1;
  V shifting(n);
  for (int i = 0; i < n; i++) {
    shifting[n - i - 1] = mul(val, invfact[i]);
    val = mul(val, c);
  }
  conv(poly, shifting);
  V ans(n);
  for (int i = 0; i < n; i++) {
    ans[i] = mul(poly[n - 1 + i], invfact[i]);
  }
  return ans;
}


struct mint {
  ll x;
  mint(ll x=0) : x((x%MOD+MOD)%MOD) {}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) { if ((x += a.x) >= MOD) x -= MOD; return *this; }
  mint& operator-=(const mint a) { if ((x -= a.x) < 0) x += MOD; return *this; }
  mint& operator*=(const mint a) { (x *= a.x) %= MOD; return *this; }
  mint operator+(const mint a) const { return mint(*this) += a; }
  mint operator-(const mint a) const { return mint(*this) -= a; }
  mint operator*(const mint a) const { return mint(*this) *= a; }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }
  mint& operator/=(const mint r) {
    ll a = r.x, b = MOD, u = 1, v = 0;
    while (b) {
      ll t = a / b;
      a -= t * b; swap(a, b);
      u -= t * v; swap(u, v);
    }
    x = x * u % MOD;
    if (x < 0) x += MOD;
    return *this;
  }
  mint operator/(const mint a) const { return mint(*this) /= a; }
};
