inline void NTT(ll *A,int lim,int opt){
	for(register int i=0;i<lim;i++)if(i<r[i])swap(A[i],A[r[i]]);
	for(register int mid=1;mid<lim;mid<<=1){
		ll W=ksm(5,(mod-1)/(mid<<1));if(opt==-1)W=ksm(W,mod-2);
		for(register int step=mid<<1,j=0;j<lim;j+=step){
			ll w=1;
			for(register int k=0;k<mid;k++,w=w*W%mod){
				ll x=A[j+k],y=w*A[j+mid+k]%mod;
				A[j+k]=(x+y)%mod;
				A[j+mid+k]=(x-y+mod)%mod;
			}
		}
	}
	if(opt==-1){
		ll inv=ksm(lim,mod-2);
		for(register int i=0;i<lim;i++)A[i]=A[i]*inv%mod;
	}
}
