inline int fpow(int x, int y) {
  int ret = 1;
  for ( ; y; y >>= 1, x = 1ll * x * x % P)
    if (y & 1) ret = 1ll * ret * x % P;
  return ret;
}
int fac[N], inv[N], ifac[N];

int rev[N], lim, L, inv_lim, w[N];
inline void init(int n) {
  for (lim = 1, L = 0; lim < n; lim <<= 1, ++L);
  for (int i = 0; i < lim; ++i)
    rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (L - 1));
  inv_lim = fpow(lim, P - 2);
  int qwq = lim >> 1, omega = fpow(Gp, (P - 1) / lim);
  w[qwq] = 1;
  for (int i = qwq + 1; i < lim; ++i)
    w[i] = 1ll * w[i - 1] * omega % P;
  for (int i = qwq - 1; i; --i)
    w[i] = w[i << 1];
}

inline void DFT(int f[], int o) {
  unsigned long long tmp[N];
  for (int i = 0; i < lim; ++i)
    tmp[rev[i]] = f[i];
  for (int i = 0; i < lim; i += 2) {
    int nx = tmp[i], ny = tmp[i + 1];
    tmp[i] = nx + ny, tmp[i + 1] = nx + P - ny;
  }
  for (int i = 2; i < lim; i <<= 1) {
    for (int j = 0; j < lim; j += i << 1) {
      auto *a = tmp + j, *b = tmp + i + j;
      auto *p = w + i;
      for (int k = 0; k < i; ++k) {
        int ny = b[k] * p[k] % P;
        b[k] = a[k] + P - ny;
        a[k] += ny;
      }
    }
  }
  for (int i = 0; i < lim; ++i)
    f[i] = tmp[i] % P;
  if (o == -1) {
    std::reverse(f + 1, f + lim);
    for (int i = 0; i < lim; ++i)
      f[i] = 1ll * f[i] * inv_lim % P;
  }
}

