int W[maxn];

void ntt(int *a, int n, int w, bool rev = 0){    
    int N = 1<<n;
    for(int i = 0; i < N; i++){
	int x = 0;
	for(int j = 0; j < n; j++)
	    x+= bit(i, j) << (n-1-j);
	if(x < i)
	    swap(a[x], a[i]);
    }
    w = Pow(w, (mod-1) >> n);
    if(rev)
	w = Pow(w, mod-2);
    W[0] = 1;
    for(int i = 1; i < N; i++)
	W[i] = 1ll * W[i-1] * w % mod;
    for(int stp = 0; stp < n; stp++){
	int ln = 1<<stp;
	for(int l = 0; l < N; l+= ln+ln){
	    for(int i = 0; i < ln; i++){
		int A = a[l + i], B = 1ll * a[l + ln + i] * W[i<<(n-1-stp)] %mod;
		a[l+i] = (A+B) % mod;
		a[l+ln+i] = (A-B) % mod;
	    }
	}
    }
    if(rev){
	int rv = Pow(1<<n, mod-2);
	for(int i = 0; i < N; i++)
	    a[i] = 1ll * a[i] * rv % mod;	
    }
}

