inline int qp(int x, ll n) {
	int ans = 1;
	for (; n; n >>= 1, x = 1LL * x * x % mod)
		if (n & 1) ans = 1LL * ans * x % mod;
	return ans;
}

inline int inv(int n) {
	return qp(n, mod - 2);
}

inline void FFT(int *a, int n, bool f = 0) {
	static int r[1 << 19];
	int k = __builtin_ctz(n) - 1;
	for (int i = 1; i < n - 1; ++ i) {
		r[i] = r[i >> 1] >> 1 | (i & 1) << k;
		if (i < r[i]) swap(a[i], a[r[i]]);
	}
	for (int h = 2; h <= n; h <<= 1) {
		int w = qp(g, (mod - 1) / h);
		for (int i = 0; i < n; i += h) {
			int wn = 1;
			rep(j, h / 2) {
				int u = a[i + j], v = 1LL * a[i + j + h / 2] * wn % mod;
				a[i + j] = (u + v) % mod; a[i + j + h / 2] = (u + mod - v) % mod;
				wn = 1LL * w * wn % mod;
			}
		}
	}
	if (f) {
		reverse(a + 1, a + n);
		int r = inv(n);
		rep(i, n) a[i] = 1LL * a[i] * r % mod;
	}
}

struct poly : vector <int> {
	poly(int len = 0) { resize(len, 0); }
	poly(const initializer_list <int> &v) {
		resize(v.size());
		rep(i, v.size()) at(i) = *(v.begin() + i);
	}
	friend poly operator * (const poly &a, const poly &b) {
		static int A[1 << 19], B[1 << 19], C[1 << 19];
		int sz = 1;
		while (sz < (a.size() + b.size() - 1)) sz <<= 1;
		rep(i, sz) A[i] = i < (int)(a.size()) ? a[i] : 0;
		rep(i, sz) B[i] = i < (int)(b.size()) ? b[i] : 0;
		FFT(A, sz); FFT(B, sz);
		rep(i, sz) C[i] = 1LL * A[i] * B[i] % mod;
		FFT(C, sz, 1);
		poly c(a.size() + b.size() - 1);
		rep(i, c.size()) c[i] = C[i];
		return c;
	}
	friend ostream& operator << (ostream &out, const poly &a) {
		out << "{";
		rep(i, a.size()) out << a[i] << ",}"[i + 1 == (int)(a.size())];
		return out;
	}
};

