int ksm(int x,int y){
    int res=1;
    while(y){
        if(y&1) res=1ll*res*x%mod;
        x=1ll*x*x%mod,y/=2;
    }
    return res;
}

int C(int x,int y){
    int res=1ll*fac[x]*ifac[y]%mod*ifac[x-y]%mod;
