void NTT(int *x,int on){
    for(int i=0;i<lim;i++) if(i<R[i]) swap(x[i],x[R[i]]);
    for(int i=2;i<=lim;i*=2){
        int wn=ksm(5,(mod-1)/i);
        if(on==-1) wn=ksm(wn,mod-2);
        for(int j=0;j<lim;j+=i){
            int w=1;
            for(int k=0;k<i/2;k++){
                int u=x[j+k],v=1ll*w*x[j+k+i/2]%mod;
                x[j+k]=(u+v)%mod;
                x[j+k+i/2]=(u+mod-v)%mod;
                w=1ll*w*wn%mod;
            }
        }
    }
}

