void ntt(ll *tmp,int tp){
	inc(i,0,lim-1) if(i<r[i]) swap(tmp[i],tmp[r[i]]);
	for(re int mid=1;mid<lim;mid<<=1){
		ll gn=qp(5,(mod-1)/(mid<<1));
		if(tp==-1) gn=qp(gn,mod-2);
		for(re int i=0;i<lim;i+=(mid<<1)){
			ll g=1;
