const int maxn=600007,mo=924844033,G=5;

int n,fi[maxn],ne[maxn],la[maxn],tot;
void add(int a,int b){
	tot++;
	ne[tot]=fi[a];
	la[tot]=b;
	fi[a]=tot;
}

