void bfs(){
	b[b[0]=1]=1;
	fo(i,1,b[0]){
		int v=b[i];
		for(int k=fi[v];k;k=ne[k])
			if (la[k]!=fa[v]){
				b[++b[0]]=la[k];
				fa[la[k]]=v;
			}
		si[v]=1;
	}
	fd(i,b[0],2){
		int v=b[i];
		for(int k=fi[v];k;k=ne[k])
			if (la[k]!=fa[v])
				si[v]+=si[la[k]];
		f[si[v]]++;
		f[n-si[v]]++;
	}
}
int qp(int a,int b){
	int c=1;
	while (b){
		if (b&1) c=1ll*a*c%mo;
		a=1ll*a*a%mo;
		b>>=1;
	}
	return c;
}
int N=1,w[maxn],_w[maxn],Fact[maxn],invFact[maxn];
void pre(){
	while (N<n*2) N<<=1;
	int t=qp(G,(mo-1)/N);
	w[0]=1;
	fo(i,1,N) w[i]=1ll*w[i-1]*t%mo;
	fo(i,0,N) _w[i]=w[N-i];
	Fact[0]=1;
	fo(i,1,N) Fact[i]=Fact[i-1]*1ll*i%mo;
	invFact[N-1]=qp(Fact[N-1],mo-2);
	fd(i,N-2,0) invFact[i]=invFact[i+1]*(i+1ll)%mo;
}
void Init(){
	scanf("%d",&n);
	fo(i,1,n-1){
		int x,y;
		scanf("%d%d",&x,&y);
		add(x,y);
		add(y,x);
	}
	bfs();
	pre();
}

int g[maxn];
void DFT(int *x,int *w){
	for(int i=0,j=0;i<N;i++){
		if (i<j) swap(x[i],x[j]);
		for(int l=N>>1;(j^=l)<l;l>>=1);
	}
	for(int i=2,m=1;i<=N;i<<=1,m<<=1)
		for(int j=0;j<N;j+=i)
			fo(k,0,m-1){
				int tmp=1ll*x[j+k+m]*w[N/i*k]%mo;
				x[j+k+m]=(x[j+k]-tmp+mo)%mo;
				x[j+k]=(x[j+k]+tmp)%mo;
			}
}
void NTT(int *a,int *b){
	DFT(a,w);
	DFT(b,w);
	fo(i,0,N-1) a[i]=1ll*a[i]*b[i]%mo;
	DFT(a,_w);
	int inv=qp(N,mo-2);
	fo(i,0,N-1) a[i]=1ll*a[i]*inv%mo;
}
void Solve(){
	fo(i,0,N-1) f[i]=1ll*f[i]*Fact[i]%mo;
	reverse(f,f+n+1);
	fo(i,0,n) g[i]=invFact[i];
	NTT(f,g);
}

int C(int x,int y){
	return 1ll*Fact[x]*invFact[y]%mo*invFact[x-y]%mo;
}
void Print(){
	fo(i,1,n) printf("%d\n",((1ll*n*C(n,i)-f[n-i]*1ll*invFact[i])%mo+mo)%mo);
}

int main(){
	Init();
	Solve();
	Print();
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int kN = 2e6 + 10;
const int kM = 2e5 + 10;
const int kMod = 998244353;

int fpow(int a, int n) {
	int res = 1;
	while(n) {
		if(n & 1) res = 1LL * res * a % kMod;
		n >>= 1, a = 1LL * a * a % kMod;
	}
	return res;
}
int Inv(int x) {return fpow(x, kMod - 2);}
struct NTT {
  int n, invn, rev[kN];
  int g;
  int omega[kN], iomega[kN];
  void init(int n, int g) {
    this->n = n, this->g = g;
    invn = Inv(n);
    int k = log2(n);
    int x = fpow(g, (kMod - 1) / n);
    omega[0] = 1;
    for (int i = 1; i < n; i++)
      omega[i] = 1LL * omega[i - 1] * x % kMod;
    iomega[n - 1] = Inv(omega[n - 1]);
    for (int i = n - 2; i >= 0; i--)
      iomega[i] = 1LL * iomega[i + 1] * x % kMod;

    for (int i = 0; i < n; i++) {
      int t = 0;
      for (int j = 0; j < k; j++)
        if (i & (1 << j)) t |= (1 << (k - j - 1));
      rev[i] = t;
    }
  }
  void transform(vector<int> &a, int *omega) {
    for (int i = 0; i < n; i++)
      if (i < rev[i]) swap(a[i], a[rev[i]]);

    for (int len = 2; len <= n; len <<= 1) {
      int mid = len >> 1;
      int r = n / len;
      for (int j = 0; j < n; j += len) {
        for (int i = 0; i < mid; i++) {
          int t = 1LL * omega[r * i] *
            a[j + mid + i] % kMod;
          a[j + mid + i] = a[j + i] - t;
          if (a[j + mid + i] < 0)
            a[j + mid + i] += kMod;
          a[j + i] += t;
          if (a[j + i] >= kMod) a[j + i] -= kMod;
        }
      }
    }
  }
  void dft(vector<int> &a) { transform(a, omega); }
  void idft(vector<int> &a) {
    transform(a, iomega);
    for (int i = 0; i < n; i++)
      a[i] = 1LL * a[i] * invn % kMod;
  }
} solver;
vector<int> mul(vector<int> a, vector<int> b) {
  int n = 1;
  int n1 = int(a.size()), n2 = int(b.size());
  while (n < n1 + n2 - 1) n <<= 1;
  a.resize(n), b.resize(n);
  solver.init(
    n, 3);  // 3 is primitive root for 998244353
  solver.dft(a), solver.dft(b);
  for (int i = 0; i < n; i++)
    a[i] = 1LL * a[i] * b[i] % kMod;
  solver.idft(a);
  while (!a.empty() && a.back() == 0) a.pop_back();
  return a;
}

int n;
vector<int> g[kN];
int sz[kN], cnt[kN];
void dfs(int u, int fa = 0) {
	sz[u] = 1;
	for(int v : g[u])
		if(v != fa) dfs(v, u), sz[u] += sz[v];
}
int fac[kN], invf[kN];
void pre() {
	fac[0] = 1;
	for(int i = 1; i <= kM + 10; i++) fac[i] = 1LL * fac[i - 1] * i % kMod;
	invf[kM + 10] = Inv(fac[kM + 10]);
	for(int i = kM + 10 - 1; i >= 0; i--) invf[i] = 1LL * invf[i + 1] * (i + 1) % kMod;
}
int C(int n, int m) {
	if(n < m) return 0;
	return 1LL * fac[n] * invf[n - m] % kMod * invf[m] % kMod;
}

int ans[kN];
int main() {
	scanf("%d", &n);
	pre(); 
	for(int i = 1, x, y; i < n; i++) {
		scanf("%d%d", &x, &y);
		g[x].push_back(y), g[y].push_back(x);
	}
	dfs(1);
	for(int i = 2; i <= n; i++) cnt[sz[i]]++, cnt[n - sz[i]]++;

	vector<int> a(n + 1), b(kM + 1);
	for(int i = 0; i <= n; i++) a[i] = 1LL * cnt[i] * fac[i] % kMod;
	for(int i = 0; i <= kM; i++) b[i] = invf[kM - i];
	vector<int> res = mul(a, b); // ans_k = [x^{k + kM}]
	while(res.size() <= n + kM + 1) res.push_back(0);

	for(int i = 0; i <= n; i++) ans[i] = 1LL * res[i + kM] * invf[i] % kMod;
	for(int i = 1; i <= n; i++) {
		ans[i] = 1LL * n * C(n, i) % kMod - ans[i];
		if(ans[i] < 0) ans[i] += kMod;
		printf("%d\n", ans[i]);
	}
	return 0;
}

