inline int mls(int x) {return x < 0 ? x + Mod : x;}
inline int pls(int x) {return x >= Mod ? x - Mod : x;}
inline void add(int u, int v) {
	e[++tot] = (E){v, h[u]}, h[u] = tot;
	e[++tot] = (E){u, h[v]}, h[v] = tot;
}
template <class T> inline void swap(T &a, T &b) {T t = a; a = b, b = t;}
template <class T> inline void in(T &x) {
	x = 0; int f = 1; char ch = getchar();
	for (; ch<'0' || ch>'9';) {if (ch=='-') f=-1; ch = getchar();}
	for (; ch>='0' && ch<='9';) x = x*10 + ch-'0', ch = getchar();
	x *= f;
}

inline int qpow(int A, int B) {
	int S = 1;
	for (; B; B >>= 1, A = 1LL * A * A % Mod)
		if (B & 1) S = 1LL * S * A % Mod;
	return S;
}

inline void dfs(int x, int f) {
	int v; sz[x] = 1;
	for (int i = h[x]; i; i = e[i].nt)
		if ((v = e[i].v) != f) dfs(v, x), sz[x] += sz[v];
	if (x != 1) ++a[sz[x]], ++a[n - sz[x]];
}

inline void FFT(int *a, int n) {
	for (int i = 0; i < n; ++i) if (i < rev[i]) swap(a[i], a[rev[i]]);
	for (int i = 1, l = L-1; i < n; i <<= 1, --l)
		for (int j = 0; j < n; j += i << 1)
			for (int u, v, k = 0, w = 1; k < i; ++k, w = 1LL * w * wn[l] % Mod)
				u = a[j + k], v = 1LL * w * a[i + j + k] % Mod,
				a[j + k] = pls(u + v), a[i + j + k] = mls(u - v);
}

inline void Mul(int m) {
	int invn, n = 1;
	for (L = 0; n <= m; n <<= 1, ++L);
	invn = qpow(n, Mod - 2);
	for (int i = 1; i < n; ++i)
		rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << L-1);

	wn[0] = qpow(5, Mod-1 >> L);
	for (int i = 1; i < L; ++i) wn[i] = 1LL * wn[i-1] * wn[i-1] % Mod;
	FFT(a, n), FFT(b, n);
	for (int i = 0; i < n; ++i) a[i] = 1LL * a[i] * b[i] % Mod;

	wn[0] = qpow(wn[0], Mod - 2);
	for (int i = 1; i < L; ++i) wn[i] = 1LL * wn[i-1] * wn[i-1] % Mod;
	FFT(a, n);
	for (int i = 0; i < n; ++i) a[i] = 1LL * a[i] * invn % Mod;
}

int main() {
	int u, v, ret; in(n);
	for (int i = 1; i < n; ++i) in(u), in(v), add(u, v);
	dfs(1, 0), fac[0] = fac[1] = inv[0] = inv[1] = 1;

	for (int i = 2; i <= n; ++i) inv[i] = 1LL * (Mod - Mod / i) * inv[Mod % i] % Mod;
	for (int i = 1; i <= n; ++i) inv[i] = 1LL * inv[i - 1] * inv[i] % Mod;
	for (int i = 1; i <= n; ++i) fac[i] = 1LL * fac[i - 1] * i % Mod;

	for (int i = 0; i <= n; ++i)
		a[i] = 1LL * a[i] * fac[n - i] % Mod, b[i] = inv[i];
	Mul(n << 1);

	for (int i = 1; i <= n; ++i) {
		ret = mls(1LL*n*fac[n]%Mod*inv[n-i]%Mod*inv[i]%Mod - 1LL*a[n-i]*inv[i]%Mod);
		printf("%d\n", ret);
	}
	return 0;
}

