        for(int j = 0; j < lim; j += i)
        {
            int tmp = 1;
            for(int k = j; k < j + len; k++)
            {
                int t = 1ll * tmp * f[k + len] % MOD;
                f[k + len] = f[k] - t;
                f[k] = f[k] + t;
                if(f[k] >= MOD) f[k] -= MOD;
                if(f[k + len] < 0) f[k + len] += MOD;
                tmp = 1ll * tmp * ur % MOD;
            }
        }
    }
    if(p)
    {
        int tmp = inv(lim);
        for(int i = 0; i < lim; i++)
            f[i] = 1ll * f[i] * tmp % MOD;
