inline void conv(int *x, int *y, int *z,int K) {
	N = (K + 1) << 1;
	L = 0;
	while ((1 << L) < N) ++L;
	N = 1 << L;
	fft_prepare();
	rep(i, 0, K + 1) a[i] = comp(x[i] & 32767, x[i] >> 15);
