		static comp da, db, dc, dd;
		da = (a[i] + conj(a[j])) * comp(0.5, 0);
		db = (a[i] - conj(a[j])) * comp(0, -0.5);
		dc = (b[i] + conj(b[j])) * comp(0.5, 0);
		dd = (b[i] - conj(b[j])) * comp(0, -0.5);
		ad[j] = da*dc+da*dd*comp(0,1);
		bd[j] = db*dc+db*dd*comp(0,1);
	}
	rep(i, 0, N) {
		a[i] = ad[i];
	}
	rep(i, 0, N) b[i] = bd[i];
	fft(a, N), fft(b, N);
