int powi(int a, int b, int c)
{
    int d = 1;
    for (; b; b /= 2, a = 1ll * a * a % c)
        if (b & 1) d = 1ll * d * a % c;
    return d;
}
void NTT(int A[], int n, int M, int G, int fl)
{
    for (int i = 1; i < n; ++ i)
    {
        int d = 0;
        for (int j = 1, k = n >> 1; j < n; j <<= 1, k >>= 1) if (i & j) d |= k;
        if (i < d) swap(A[i], A[d]);
    }
    for (int i = 2; i <= n; i <<= 1)
    {
        int w0 = powi(G, (M - 1) / i, M);
        if (fl < 0) w0 = powi(w0, M - 2, M);
        for (int j = 0; j < n; j += i)
        {
            int w = 1;
            for (int k = j; k < j + (i >> 1); ++ k)
            {
                int u = A[k], v = 1ll * A[k + (i >> 1)] * w % M;
                A[k] = (u + v) % M, A[k + (i >> 1)] = (u - v + M) % M;
                w = 1ll * w * w0 % M;
            }
        }
    }
    if (fl < 0) for (int i = 0; i < n; ++ i) A[i] = (1ll * A[i] * powi(n, M - 2, M)) % M;
}

__int128 CRT(int a[], int m[], int n)
{
    __int128 M = 1;
    __int128 ans = 0;
    for (int i = 0; i < n; ++ i) M *= m[i];
    for (int i = 0; i < n; ++ i)
    {
        __int128 Mi = M / m[i];
        ans = (ans + Mi * powi(Mi % m[i], m[i] - 2, m[i]) * a[i]) % M;
    }
    if (ans < 0) ans += M;
    return ans;
}


void solve(int M, int G)
{
    int nn = 1; while (nn <= n) nn *= 2; nn *= 2;
    for (int i = 0; i < nn; ++ i) A[i] = B[i] = 0;
    for (int i = 0; i <= n; ++ i) A[n - i] = 1ll * fac[i] * cnt[i] % M;
    for (int i = 0; i <= n; ++ i) B[i] = inv[i];
    NTT(A, nn, M, G, 1);
    NTT(B, nn, M, G, 1);
    for (int i = 0; i < nn; ++ i) A[i] = 1ll * A[i] * B[i] % M;
    NTT(A, nn, M, G, -1);
}
