void get_ready()
{
	int W=fpm(5,(mod-1)/N),IW=fpm(W,mod-2),i;
	eps[0]=inv_eps[0]=1;
	for(i=1;i<N;i++)
		eps[i]=1LL*eps[i-1]*W%mod,
		inv_eps[i]=1LL*inv_eps[i-1]*IW%mod;
}
void dft(int *x,int n,int *Eps)
{
	int i,j,k,u,t,wn,w;
	for(i=j=0;i<n;i++)
	{
		if(i<j) swap(x[i],x[j]);
		for(k=n>>1;(j^=k)<k;k>>=1);
	}
	for(i=1;i<n;i<<=1)
	{
		wn=(N/i)>>1;
		for(j=0;j<n;j+=i<<1)
			for(k=w=0;k<i;k++,w+=wn)
			{
				u=x[j+k]; t=1LL*Eps[w]*x[j+k+i]%mod;
				x[j+k]=pul(u,t);
				x[j+k+i]=dec(u,t);
			}
	}
}
void idft(int *x,int n,int *Eps)
{
	dft(x,n,Eps);
	int Inv=fpm(n,mod-2),i;
	for(i=0;i<n;i++)
		x[i]=1LL*x[i]*Inv%mod;
}
