namespace FFT {
  const int maxk = 20, maxn = (1 << maxk) + 5;
  int brev[maxn];
  int ws[maxn];
  int n, k;
  int lastk = -1;

  void fft(int *f) {
    if (k != lastk) {
      lastk = k;
      {
        brev[0] = 0;
        for (int i = 1, bit = -1; i < n; i++) {
          if (!(i & (i - 1))) {
            bit++;
          }
          brev[i] = (brev[i ^ (1 << bit)] ^ (1 << (k - 1 - bit)));
        }
      }
      {
        ws[1] = 1;
        for (int l = 0; l < k - 1; l++) {
          int w = powMod(w1, (1 << (20 - l - 2)));
          for (int i = (1 << l); i < (1 << (l + 1)); i++) {
            ws[2 * i] = ws[i];
            ws[2 * i + 1] = mul(ws[i], w);
          }
        }
      }
    }
    for (int i = 0; i < n; i++) {
      if (i < brev[i]) {
        swap(f[i], f[brev[i]]);
      }
    }
    for (int len = 1; len < n; len <<= 1) {
      for (int i = 0; i < n; i += len) {
        int j = i + len;
        for (int it = 0; it < len; it++, i++, j++) {
          int tmp = mul(f[j], ws[len + it]);
          f[j] = f[i];
          add(f[i], tmp);
          add(f[j], mod - tmp);
        }
      }
    }
  }

  int a[maxn], b[maxn];

  void mulPol(int na, int *_a, int nb, int *_b, int *res) {
    for (int i = 0; i < na; i++) {
      a[i] = _a[i];
    }
    for (int i = 0; i < nb; i++) {
      b[i] = _b[i];
    }
    int nres = na + nb - 1;
    n = 1;
    k = 0;
    while (n < nres) {
      n <<= 1;
      k++;
    }
    assert(n < maxn);
    for (int i = na; i < n; i++) {
      a[i] = 0;
    }
    for (int i = nb; i < n; i++) {
      b[i] = 0;
    }
    fft(a);
    fft(b);
    for (int i = 0; i < n; i++) {
      a[i] = mul(a[i], b[i]);
    }
    reverse(a + 1, a + n);
    fft(a);
    for (int i = 0; i < nres; i++) {
      res[i] = mul(a[i], inv[n]);
    }
  }
}

