}edg[maxn];
void add(int u,int v) {
	edg[++ecnt]=(edge){u,v,ehead[u]};
	ehead[u]=ecnt;
	edg[++ecnt]=(edge){v,u,ehead[v]};
	ehead[v]=ecnt;
}
int fac[maxn],inc[maxn];
int n,L,cnt[maxn],g[maxn],h[maxn],sz[maxn];
namespace FFT {
	int o[maxn],w[maxn],rv[maxn];
	LL fpm(LL p,LL k) {
		LL res=1ll;
		while (k) {
			if (k&1) (res*=p)%=mod;
			(p*=p)%=mod;k>>=1;
		}
		return res;
	}
	void prepare(int L) {
		o[0]=1;LL w0=fpm(5,(mod-1)/L);
		for (int i=1;i<L;i++) o[i]=o[i-1]*w0%mod;
		for (int i=1;i<L;i++) rv[i]=rv[i>>1]>>1|(i&1?L>>1:0);
	}
	int plu(int u,int v) {
		return u>=mod-v?v-mod+u:u+v;
	}
	int dec(int u,int v) {
		u-=v;return u<0?u+=mod:u;
	}
	void ntt(int *f,int idft=0)
	{
		for (int i=0;i<L;i++)
			if (i<rv[i]) swap(f[i],f[rv[i]]);
		for (int p=2;p<=L;p<<=1)
		{
			int s=L/p;w[0]=o[0];
			if (idft) for (int i=1,t=L-s;i<p>>1;i++,t-=s) w[i]=o[t];
			else for (int i=1,t=s;i<p>>1;i++,t+=s) w[i]=o[t];
			for (int i=0;i<L;i+=p) {
				int *c=w;
				for (int j=i;j<i+(p>>1);j++)
				{
					int u=f[j],v=(LL)f[j+(p>>1)]*(*c++)%mod;
					f[j]=plu(u,v);f[j+(p>>1)]=dec(u,v);
				}
			}
		}
		if (idft) {
			int inc=fpm(L,mod-2);
			for (int i=0;i<L;i++)
				f[i]=(LL)f[i]*inc%mod;
		}
	}
}
