namespace poly{
	using namespace math_template;

	using poly_t=int[mxdg];
	using poly=int*const;

	inline int calcpw2(const int&n){
		int t=1;
		for(;t<n;t<<=1);
		return t;
	}

	int wn[mxdg],
		iwn[mxdg];

	inline void polyinit(){
		const int wnv=fpow(proot,(p-1)/mxdg);
		const int iwnv=fpow(wnv,p-2);
		wn[0]=iwn[0]=1;
		for(int i=1,v=1,iv=1;i!=mxdg;++i){
			v=(int64)v*wnv%p;wn[i]=v;
			iv=(int64)iv*iwnv%p;iwn[i]=iv;
		}
	}

	void DFT(poly&A,const int&deg){
		for(int i=0,j=0;i!=deg;++i){
			if(i<j)swap(A[i],A[j]);
			for(int k=deg>>1;(j^=k)<k;k>>=1);
		}
		int*const td=A+deg;
		for(int l=1,tp=mxdg>>1;l!=deg;l+=l,tp>>=1)
			for(int*i=A,z;i<td;i+=l+l)
				for(int j=0,*w=wn;j!=l;++j,w+=tp)
					z=(int64)i[j+l]**w%p,
					i[j+l]=sub(i[j],z),
					inc(i[j],z);
	}
	void IDFT(poly&A,const int&deg){
		for(int i=0,j=0;i!=deg;++i){
			if(i<j)swap(A[i],A[j]);
			for(int k=deg>>1;(j^=k)<k;k>>=1);
		}
		int*const td=A+deg;
		for(int l=1,tp=mxdg>>1;l!=deg;l+=l,tp>>=1)
			for(int*i=A,z;i<td;i+=l+l)
				for(int j=0,*w=iwn;j!=l;++j,w+=tp)
					z=(int64)i[j+l]**w%p,
					i[j+l]=sub(i[j],z),
					inc(i[j],z);

		const int invdeg=fpow(deg,p-2);
		for(int i=0;i!=deg;++i)
			A[i]=(int64)A[i]*invdeg%p;
	}
}

struct Edge{
	int v;Edge*las;
	inline Edge* init(const int&to,Edge*const&ls)
		{return v=to,las=ls,this;}
}*las[maxn+1];

inline void AddEdge(){
	static Edge pool[maxn<<1],*alc=pool-1;
	const int u=io,v=io;
	las[u]=(++alc)->init(v,las[u]);
	las[v]=(++alc)->init(u,las[v]);
}

int sz[maxn+1],
	cnt[maxn+1];

void precalc(const int&u,const int&fa){
	sz[u]=1;
	for(Edge*o=las[u];o;o=o->las)
		if(o->v!=fa)
			precalc(o->v,u),
			sz[u]+=sz[o->v];
}

int Fac[maxn+1],
	invFac[maxn+1];

inline int C(const int&n,const int&k)
	{return(int64)Fac[n]*invFac[k]%p*invFac[n-k]%p;}

using namespace poly;

poly_t f,g;

int main(){
	polyinit();

	const int n=io;
	for(int i=n-1;i!=0;--i)
		AddEdge();

	precalc(1,0);
	for(int i=2;i<=n;++i)
		++cnt[sz[i]],
		++cnt[n-sz[i]];

	int v=1;
	Fac[0]=Fac[1]=invFac[0]=invFac[1]=1;
	for(int i=2;i<=n;++i)
		v=(int64)v*i%p,
		Fac[i]=v;
	v=fpow(v,p-2);
	for(int i=n;i!=1;--i)
		invFac[i]=v,
		v=(int64)v*i%p;

	for(int i=1;i<=n;++i)
		f[i]=(int64)cnt[i]*Fac[i]%p;
	std::reverse_copy(invFac,invFac+n+1,g);

	const int deg(calcpw2(n+n));

	DFT(f,deg);DFT(g,deg);
	for(int i=0;i!=deg;++i)
		f[i]=(int64)f[i]*g[i]%p;
	IDFT(f,deg);

	for(int i=1;i<=n;++i)
		printf("%d\n",sub((int64)n*C(n,i)%p,(int64)f[n+i]*invFac[i]%p));

	return 0;
}

