typedef long long LL;

const int N=800400;
const LL mo=924844033;

void read(int &hy)
{
	hy=0;
	char cc=getchar();
	while(cc<'0'||cc>'9')
	cc=getchar();
	while(cc>='0'&&cc<='9')
	{
