void adde(int x,int y){
	des[++tot]=y;nxt[tot]=head[x];head[x]=tot;
}
void init(int n,int m){
	n++;m++;l=n+m-1;
	for(N=1,bitl=0;N<l;N<<=1,bitl++);
	rep2(i,0,N)bitrev[i]=(bitrev[i>>1]>>1)|((i&1)<<(bitl-1));
}
void ntt(int *a,int n,int flag){
	rep2(i,0,n)if(i<bitrev[i])swap(a[i],a[bitrev[i]]);
	for(int i=1;i<n;i<<=1){
		int wn=power(G,(mod-1)/(i<<1),mod);
		if(flag==-1)wn=power(wn,mod-2,mod);
		for(int j=0;j<n;j+=i<<1){
			int w=1;
			rep2(k,0,i){
				int x=a[j+k],y=1ll*w*a[j+k+i]%mod;
				a[j+k]=add(x,y);
				a[j+k+i]=sub(x,y);
				w=1ll*w*wn%mod;
			}
		}
	}
	if(flag==-1){
		int inv=power(n,mod-2,mod);
		rep2(i,0,n)a[i]=1ll*a[i]*inv%mod;
	}
}
void dfs(int x,int fa){
	sz[x]=1;
	cnt[n]=add(cnt[n],1);
	Rep(p,x)if(des[p]!=fa){
		dfs(des[p],x);
		sz[x]+=sz[des[p]];
		cnt[sz[des[p]]]=sub(cnt[sz[des[p]]],1);
	}
	cnt[n-sz[x]]=sub(cnt[n-sz[x]],1);
}
int main(){
	read(n);
	fac[0]=1;rep(i,1,n)fac[i]=1ll*fac[i-1]*i%mod;
	rep(i,0,n)ifac[i]=power(fac[i],mod-2,mod);
