void solve()
{
	read(n);
	for (int i = 1; i < n; ++i)
	{
		int x, y;
		read(x, y);
		v[x].push_back(y);
		v[y].push_back(x);
	}
	dfs(1, 0);
	for (int i = 2; i <= n; ++i)
	{
		c[sz[i]]++;
	}
	prepare_factorials(n);

	poly res(n + 1);
	for (int k = 1; k <= n; ++k)
		res[k] = choose(n, k) * n;

	poly x(n + 1);
	for (int i = 1; i <= n; ++i) x[i] = (c[i] + c[n - i]) * factorial[i];
	poly y(n + 1);
	for (int i = 0; i <= n; ++i) y[n - i] = inv_factorial[i];
	auto z = NTT::mod_multiply(x, y);
	for (int k = 1; k <= n; ++k)
		res[k] -= inv_factorial[k] * z[n + k];

	for (int k = 1; k <= n; ++k)
		writeln(int(res[k]));
}

