	a[n-sz[u]]++;
}
void ntt(int *a,int op){
	for (int i=0;i<lim;i++)
		if (i<r[i]) swap(a[i],a[r[i]]);
	for (int mid=1,pp=M-1>>1;mid<lim;mid<<=1,pp>>=1)
		for (int R=mid<<1,j=0,wn=pw(op==1?g:gi,pp);j<lim;j+=R)
			for (int k=0,w=1;k<mid;k++,w=mul(w,wn)){
				int x=a[j|k],y=mul(w,a[j|k|mid]);
				a[j|k]=inc(x,y);
				a[j|k|mid]=dec(x,y);
			}
	if (op==-1){
		int inv=Inv(lim);
		for (int i=0;i<lim;i++) a[i]=mul(a[i],inv);
	}
}
