LL getmi(LL a,int x)
{
    LL rt=1;
    while(x)
    {
        if(x&1) rt=rt*a%mod;
        a=a*a%mod,x>>=1;
    }
    return rt;
}

LL C(int n,int m)
{
    return flv[n]*inv[m]%mod*inv[n-m]%mod;
}

void addedge(int u,int v)
{
    e[cnt]=(edge){v,h[u]},h[u]=cnt++;
    e[cnt]=(edge){u,h[v]},h[v]=cnt++;
}

void dfs(int x,int fa)
{
    f[x]=fa,siz[x]=1;
    for(int i=h[x]; i!=-1; i=e[i].n)
        if(e[i].v!=fa)
            dfs(e[i].v,x),siz[x]+=siz[e[i].v];
}

void FFT(LL a[],int tp)
{
    rep(i,0,len-1) if(i<bin[i]) swap(a[i],a[bin[i]]);
    for(int i=1; i<len; i<<=1)
    {
        LL wn=getmi(5,(mod-1)/(i<<1));
        if(tp==-1) wn=getmi(wn,mod-2);
        w[0]=1;
        rep(j,1,i-1) w[j]=w[j-1]*wn%mod;
        for(int j=0; j<len; j+=(i<<1))
            rep(k,0,i-1)
            {
                LL x=a[j+k],y=w[k]*a[i+j+k]%mod;
                a[j+k]=(x+y)%mod;
                a[j+k+i]=(x-y+mod)%mod;
            }
    }
    if(tp==-1)
    {
        LL x=getmi(len,mod-2);
        rep(i,0,len-1) a[i]=a[i]*x%mod;
    }
}

int main()
{
    n=getint(),memset(h,-1,sizeof(h));
    rep(i,1,n-1) addedge(getint(),getint());
    dfs(1,0);
    flv[0]=1;
    rep(i,1,n) flv[i]=flv[i-1]*i%mod;
    inv[n]=getmi(flv[n],mod-2);
    repd(i,n,1) inv[i-1]=inv[i]*i%mod;
    rep(i,1,n)
    {
        for(int sz=0,j=h[i]; j!=-1; j=e[j].n)
        {
            if(e[j].v==f[i]) sz=n-siz[i];
            else sz=siz[e[j].v];
            ++c[sz];
        }
    }
    rep(i,1,n) c[i]=c[i]*flv[i]%mod;
    rep(i,0,n) F[i]=getmi(flv[n-i],mod-2);
    for(len=1; len<n+n; len<<=1);
    rep(i,1,len) bin[i]=(bin[i>>1]>>1)|((i&1)*(len>>1));
    FFT(c,1),FFT(F,1);
    rep(i,0,len) G[i]=c[i]*F[i]%mod;
    FFT(G,-1);
    rep(i,1,n)
    {
        ans[i]=(n*C(n,i)%mod-G[i+n]*getmi(flv[i],mod-2)%mod)%mod;
        printf("%lld\n",(ans[i]+mod)%mod);
    }
    return 0;
}

