inline void NTT(int *A,int limit,int flg){
	for(int i = 0 ; i < limit ; i++)
	    if(i > rev[i])
		   swap(A[i],A[rev[i]]) ;
	for(int mid = 1 ; mid < limit ; mid <<= 1){
		int Wn = power(flg == 1 ? GG : IG,(mod-1)/(mid<<1)) ; 
		for(int j = 0 ; j < limit ; j += (mid<<1)){
			int w = 1 ;
			for(int k = 0 ; k < mid ; k++,w = mul(w,Wn)){
				int x = A[j+k],y = mul(w,A[j+mid+k]) ;
				A[j+k] = add(x,y) ;
				A[j+mid+k] = sub(x,y) ; 
			}
		}
	}
	if(flg == -1){
		int Inv = power(limit,mod-2) ;
		for(int i = 0 ; i < limit ; i++)
		    A[i] = mul(A[i],Inv) ;
	}
}
