ll fac[N],ans[N],_fac[N],g[N*5],_g[N*5],A[N*5],B[N*5];
struct ed{ int v,nxt; }e[N<<1];
void add(int u,int v){
	e[++cnt]=(ed){v,head[u]},head[u]=cnt;
	e[++cnt]=(ed){u,head[v]},head[v]=cnt;
}
ll qpow(ll x,int y){
	ll tmp=1;
	for(;y;y>>=1,(x*=x)%=mod) if(y&1) tmp=1ll*tmp*x%mod;
	return tmp;
}
ll C(int x,int y){
	if(x<y) return 0;
	return fac[x]*_fac[y]%mod*_fac[x-y]%mod;
}
ll mnS(ll x,ll y){ return x-y<0?x-y+mod:x-y; } 
void init(){
	fac[0]=_fac[0]=fac[1]=_fac[1]=1;
	For(i,2,n){
		fac[i]=1ll*fac[i-1]*i%mod;
		_fac[i]=(1ll*mod-mod/i)*_fac[mod%i]%mod;
	}
	For(i,2,n) (_fac[i]*=_fac[i-1])%=mod;
	for(bit=0,len=1;len<=2*n+1;len<<=1,bit++);
	For(i,0,len-1) rev[i]=(rev[i>>1]>>1)|((i&1)<<bit-1);
	g[len]=qpow(1ll*G,(mod-1)/len),_g[len]=qpow(g[len],mod-2);
	for(int i=(len>>1);i>=2;i>>=1){
		g[i]=g[i<<1]*g[i<<1]%mod;
		_g[i]=_g[i<<1]*_g[i<<1]%mod;
	}
	_len=(int)qpow(len,mod-2);
}
void dfs(int x,int f){
	sz[x]=1;
	Edge(x){
		int to=e[i].v;
		if(to!=f){
			dfs(to,x);
			sz[x]+=sz[to];
		}
	}
	if(x!=1){
		num[sz[x]]++;
		num[n-sz[x]]++;		
	}
}
void NTT(ll *a,int f){
	For(i,0,len-1) if(rev[i]>i) swap(a[rev[i]],a[i]);
	for(int i=2;i<=len;i<<=1){
		ll omega;f==1?omega=g[i]:omega=_g[i];
		int mid=i>>1;
		for(int j=0;j<len;j+=i){
			ll w=1;
			for(int k=j;k<j+mid;++k,(w*=omega)%=mod){
				ll u=a[k],v=a[k+mid]*w%mod;
				a[k]=(u+v)%mod;
				a[k+mid]=(u-v+mod)%mod;
			}
		}
	}
	if(f==-1) For(i,0,len-1) (a[i]*=1ll*_len)%=mod; 
}
int main(){
	int u,v;
	scanf("%d",&n);
	init();
	For(i,1,n-1) scanf("%d%d",&u,&v),add(u,v);
	dfs(1,0);
	For(i,0,n) A[i]=fac[i]*num[i]%mod;
	For(i,0,n) B[n-i]=_fac[i];
	NTT(A,1),NTT(B,1);
	For(i,0,len-1) A[i]=A[i]*B[i]%mod;
	NTT(A,-1);
	For(i,1,n)
		ans[i]=mnS(1ll*n*C(n,i),_fac[i]*A[n+i]%mod);
	For(i,1,n) printf("%lld\n",ans[i]);
}

