using ll = long long;
using namespace std;

const int mod = 998244353;
const int gen = 3;

int pt(int a, int b)
{
	int res = 1;
	while(b)
	{
		if(b & 1)
			res = (ll) res * a % mod;
		a = (ll) a * a % mod;
		b /= 2;
	}
	return res;
}

void nnt(vector <int> &a, bool inv)
{
	int n = (int)a.size();
	for(int i = 1, j = 0; n > i; ++i)
	{
		int bit = n / 2;
		while(bit & j)
		{
			j ^= bit;
			bit /= 2;
		}
		j ^= bit;
		if(j > i)
			swap(a[i], a[j]);
	}

	for(int len = 2; n >= len; len *= 2)
	{
		int root = pt(gen, (mod - 1) / len);
		if(inv)
			root = pt(root, mod - 2);
		for(int pocz = 0; n > pocz; pocz += len)
		{
			int W = 1;
			for(int j = 0; len  / 2 > j; ++j)
			{
				int u = a[pocz + j];
				int w = 1ll * W * a[pocz + j + len / 2] % mod;
				a[pocz + j] = (u + w < mod ? u + w : u + w - mod);
				a[pocz + j + len / 2] = (u - w >= 0 ? u - w : u - w + mod);
				W = 1ll * W * root % mod;
			}
		}
	}
	int odw = pt(n, mod - 2);
	if(inv)
	{
		for(auto &it: a)
			it = (ll) it * odw % mod;
	}	
}

vector <int> mul(vector <int> a, vector <int> b) {
	int p = 0;
	while(ss(a) + ss(b) >= (1 << p))
		p++;
	a.resize((1 << p));
	b.resize((1 << p));
	nnt(a, 0);
	nnt(b, 0);
	for(int i = 0; i < (1 << p); ++i)
		a[i] = 1ll * a[i] * b[i] % mod;
	nnt(a, 1);
	return a;
}

