namespace ntt 
{
	int eps[NX];
	void preprocess()
	{
		int g = exp(G, (mod - 1) / N);
		eps[0] = 1; 
		for (int i = 1; i < N; i++)
			eps[i] = (LL) eps[i - 1] * g % mod;
	}

	void dft(int n, int x[])
	{
		for (int i = 0, j = 0; i < n; i++)
		{
			if(i > j) swap(x[i], x[j]);
			for (int l = n >> 1; (j ^= l) < l; l >>= 1);
		}

		for (int i = 2; i <= n; i <<= 1)
		{
			int l = i >> 1, d = N / i;
			for (int j = 0; j < n; j += i) 
				for (int k = 0; k < l; k++)
				{
					int t = (LL) eps[d * k] * x[j + k + l] % mod;
					x[j + k + l] = (x[j + k] + mod - t) % mod;
					x[j + k] = (x[j + k] + t) % mod;
				}
		}
	}

	void idft(int n, int x[]) 
	{
		dft(n, x);
		reverse(x + 1, x + n);
		int inv = exp(n, mod - 2);
		for (int i = 0; i < n; i++)
			x[i] = (LL) x[i] * inv % mod;
	}
}
