namespace FFT {
  struct comp {
    ld x, y;

    comp(ld x = 0, ld y = 0) : x(x), y(y) {}

    comp operator+(const comp & b) const {
      return comp(x + b.x, y + b.y);
    }

    comp operator-(const comp & b) const {
      return comp(x - b.x, y - b.y);
    }

    comp operator*(const comp & b) const {
      return comp(x * b.x - y * b.y, x * b.y + y * b.x);
    }
  };

  const int maxn = 1 << 20;
  int n, logn, rev[maxn];
  comp a[maxn], b[maxn];

  void init() {
    rev[0] = 0;
    for (int i = 1, j = -1; i < n; i++) {
      if (!(i & (i - 1))) {
        j++;
      }
      rev[i] = rev[i ^ (1 << j)] ^ (1 << (logn - 1 - j));
    }
  }

  void fft(comp * a, bool back = false) {
    for (int i = 0; i < n; i++) {
      if (rev[i] < i) {
        swap(a[rev[i]], a[i]);
      }
    }
    for (int j0 = 1; j0 < n; j0 <<= 1) {
      comp mult = comp(cos(PI / j0), sin(PI / j0));
      if (back) {
        mult.y = -mult.y;
      }
      for (int i = 0; i < n; i += j0) {
        comp cur = comp(1);
        for (int it = 0, j = i + j0; it < j0; i++, j++, it++) {
          comp add = a[j] * cur;
          a[j] = a[i] - add;
          a[i] = a[i] + add;

          cur = cur * mult;
        }
      }
    }
  }

  int mult(int n1, int * a1, int n2, int * a2, ll * ans) {
    for (n = 1, logn = 0; n < n1 + n2 - 1; n <<= 1, logn++) ;
    init();

    for (int i = 0; i < n; i++) {
      a[i] = (i < n1) ? a1[i] : 0;
      b[i] = (i < n2) ? a2[i] : 0;
    }
    fft(a);
    fft(b);
    for (int i = 0; i < n; i++) {
      a[i] = a[i] * b[i];
    }
    fft(a, true);

    int anslen = 0;
    for (int i = 0; i < n; i++) {
      ll cur = (ll) floor(a[i].x / n + 0.5);
      if (cur) {
        while (anslen < i) {
          ans[anslen++] = 0;
        }
        ans[anslen++] = cur;
      }
    }
    return anslen;
  }
}

