void NTT(ll a[],ll n,ll mode){
	for(ll i=0,j=0;i<n;i++)
	{
		if(i<j) swap(a[i],a[j]);
		ll k=(n>>1);
		while(k&&(k&j)){ j^=k; k>>=1; }
		j^=k;
	}
	for(ll i=1;i<n;i<<=1)
	{
		ll w1=ksm(g,(mod-1)/(i<<1)),w=1;
		if(mode==-1) w1=ksm(w1,mod-2);
		for(ll j=0;j<i;j++,w=1ll*w*w1%mod)
			for(ll l=j,r=l+i;l<n;l+=(i<<1),r=l+i)
			{
