const int maxn = 131072<<2;
const int P =  924844033;
const int G = 5;

struct MOD{
	int x;
	MOD (int x_=0):x(x_){
		if(x<0)	x+=P;if(x>=P)	x-=P;
	}
	MOD operator+(const MOD& rhs)const{
		return MOD(x+rhs.x);
	}
	MOD operator-(const MOD& rhs)const{
		return MOD(x-rhs.x);
	}
	MOD operator-()const{
		return MOD(-x);
	}
	MOD operator*(const MOD& rhs)const{
		return MOD(int(1LL*x*rhs.x%P));
	}
}w[maxn+1];

MOD mypow(MOD x,int b){
	MOD res=1;
	while(b){
		if(b&1)	res=res*x;
		x=x*x;
		b>>=1;
	}
	return res;
}

void pre_ntt(){
	MOD dw = mypow(G,(P-1)/maxn);
	w[0]=1;
	for(int i=1;i<=maxn;i++)
		w[i]=w[i-1]*dw;
}
void ntt(vector<MOD>& v,int n,bool inv){
	for(int i=0,j=0;i<n;i++){
		if(i>j)	swap(v[i],v[j]);
		for(int s=n>>1;(j^=s)<s;s>>=1);
	}
	for(int s=2;s<=n;s<<=1){
		int z=s>>1;
		for(int i=0;i<n;i+=s)
			for(int j=0;j<z;j++){
				MOD x=v[i+z+j]*w[maxn/s*j];
				v[i+z+j]=v[i+j]-x;
				v[i+j]=v[i+j]+x;
			}
	}
	if(inv){
		reverse(v.begin()+1,v.end());
		MOD invn = mypow(n,P-2);
		for(int i=0;i<n;i++)	v[i]=v[i]*invn;
	}
}
vector<int> conv(const vector<int>& a,const vector<int>& b){
	int sz=1;
	while(sz<a.size()+b.size()-1)	sz<<=1;
	vector<MOD> fa(sz),fb(sz);
	for(int i=0;i<a.size();i++)
		fa[i]=a[i];
	for(int i=0;i<b.size();i++)
		fb[i]=b[i];
	ntt(fa,sz,0);ntt(fb,sz,0);
	for(int i=0;i<sz;i++)
		fa[i]=fa[i]*fb[i];
	ntt(fa,sz,1);
	vector<int> res(sz);
	for(int i=0;i<sz;i++)
		res[i]=fa[i].x;
	return res;
}

