const int Max_N(200050);
const int MOD(924844033);
typedef long long int LL;

inline int Mult(const int &a, const int &b)
{
	return static_cast<int>(static_cast<LL>(a) * static_cast<LL>(b) % static_cast<LL>(MOD));
}

void exgcd(const int &a, const int &b, int &x, int &y)
{
	if (b == 0)
		x = 1, y = 0;
	else
		exgcd(b, a % b, y, x), y -= x * (a / b);
}

inline int inverse(const int &a)
{
	int invx, invy;
	exgcd(a, MOD, invx, invy);
	return (invx % MOD + MOD) % MOD;
}

int power(int a, int n)
{
	int Ret(1);
	while (n)
	{
		if (n & 1)
			Ret = Mult(Ret, a);
		a = Mult(a, a), n >>= 1;
	}
	return Ret;
}

namespace NTT
{
	const int Max_L(524288 + 5);
	int L, A[Max_L], B[Max_L], W[Max_L], C[Max_L];
	void DFT(int *P)
	{
		for (int i = 0, j = 0;i <= L - 1;++i)
		{
			if (j > i)
				swap(P[i], P[j]);
			for (int l = (L >> 1);(j ^= l) < l;l >>= 1)
				;
		}
		int z;
		for (int l = 2, m = 1;l <= L;l <<= 1, m <<= 1)
			for (int i = 0;i <= L - 1;i += l)
				for (int k = 0;k <= m - 1;++k)
				{
					z = Mult(P[i + m + k], W[L / l * k]);
					P[i + m + k] = ((P[i + k] - z) % MOD + MOD) % MOD;
					(P[i + k] += z) %= MOD;
				}
	}
	void NTT()
	{
		W[0] = 1, W[1] = power(5, (MOD - 1) / L);
		for (int i = 2;i <= L - 1;++i)
			W[i] = Mult(W[i - 1], W[1]);
		DFT(A), DFT(B);
		for (int i = 0;i <= L - 1;++i)
			C[i] = Mult(A[i], B[i]);
		W[0] = 1, W[1] = inverse(W[1]);
		for (int i = 2;i <= L - 1;++i)
			W[i] = Mult(W[i - 1], W[1]);
		DFT(C);
		int invL = inverse(L);
		for (int i = 0;i <= L - 1;++i)
			C[i] = Mult(C[i], invL);
	}
}

int N, F[Max_N], Size[Max_N], Fac[Max_N], Inv[Max_N];
int Head[Max_N], Total, To[Max_N << 1], Next[Max_N << 1];

inline void Add_Edge(const int &s, const int &t)
{
	++Total, To[Total] = t, Next[Total] = Head[s], Head[s] = Total;
}

void dfs(const int &u, const int &fa)
{
	Size[u] = 1;
	for (int i = Head[u], v;i;i = Next[i])
		if ((v = To[i]) != fa)
			dfs(v, u), Size[u] += Size[v], --F[Size[v]];
	++F[N], --F[N - Size[u]];
}

void init()
{
	Get_Val(N);
	for (int i = 1, u, v;i != N;++i)
		Get_Val(u), Get_Val(v), Add_Edge(u, v), Add_Edge(v, u);
	dfs(1, -1);
	for (int i = 0;i <= N;++i)
		F[i] = (F[i] % MOD + MOD) % MOD;
	Fac[0] = 1;
	for (int i = 1;i <= N;++i)
		Fac[i] = Mult(Fac[i - 1], i);
	Inv[N] = inverse(Fac[N]);
	for (int i = N - 1;i >= 0;--i)
		Inv[i] = Mult(Inv[i + 1], i + 1);
}

//计算任选K个点形成虚树大小的和Ans[K]，考虑计算一个点u对答案的贡献：
//C(N, K) - Sum{C(Size[v], K) | v是u的儿子} - C(N - Size[u], K)
//设F[i]表示Ans[K] = Sum{F[i] * C(i, K)}，对于每个K的F[i]均是相等的。我们可以O(N)计算出F[i]
//Ans[K] = Sum{F[i] * C(i, K)} = Sum{F[i] * i! / K! / (i - K)!} = Sum{F[i] * i! / (i - K)!} / K!，NTT优化即可
void work()
{
	for (int i = 1;i <= N;++i)
		NTT::A[N - i] = Mult(F[i], Fac[i]);
	for (int i = 0;i <= N;++i)
		NTT::B[i] = Inv[i];
	NTT::L = 1;
	while (NTT::L <= N * 2)
		NTT::L <<= 1;
	NTT::NTT();
	for (int k = 1;k <= N;++k)
		printf("%d\n", Mult(Inv[k], NTT::C[N - k]));
}

int main()
{
	init();
	work();
	return 0;
}

