LL cheng(LL a,LL b)
{
	LL res=1ll;
	for(;b;b>>=1,a=a*a%p)
	if(b&1)
	res=res*a%p;
	return res;
}

int n,rev[N];

void init(int lim)
{
	int k=-1;
	n=1;
	while(n<lim)
	n<<=1,k++;
	for(int i=0;i<n;i++)
	rev[i]=(rev[i>>1]>>1) | ((i&1)<<k);
}

void ntt(LL *a,int ops)
{
	for(int i=0;i<n;i++)
	if(i<rev[i])
	swap(a[i],a[rev[i]]);
	for(int l=2;l<=n;l<<=1)
	{
		int m=l>>1;
		LL wn;
		if(ops)
		wn=cheng(g,(p-1)/l);
		else
		wn=cheng(g,p-1-(p-1)/l);
		for(int i=0;i<n;i+=l)
		{
			LL w=1;
			for(int k=0;k<m;k++)
			{
				LL t=a[i+k+m]*w%p;
				a[i+k+m]=(a[i+k]-t+p)%p;
				a[i+k]=(a[i+k]+t)%p;
				w=w*wn%p;
			}
		}
	}
	if(!ops)
	{
		LL Inv=cheng(n,p-2);
		for(int i=0;i<n;i++)
		a[i]=a[i]*Inv%p;
	}
}

