    b >>= 1;
  }
  return ret;
}
void prework(int n) {
  rev[0] = 0;
  for (int i = 1 ; i < n ; ++ i)
    if (i&1) rev[i] = rev[i-1] | (n >> 1);
    else rev[i] = rev[i>>1] >> 1;
}
void dft(int* a,int n,int sgn) {
  for (int i = 0 ; i < n ; ++ i)
    if (i < rev[i]) swap(a[i],a[rev[i]]);
  int w,wp,u,v;
  for (int s = 2 ; s <= n ; s <<= 1) {
    wp = power(G,(MOD-1) / s);
    if (sgn) wp = power(wp,MOD-2);
    for (int k = 0 ; k < n ; k += s) {
      w = 1;
      for (int j = k ; j < k + (s >> 1) ; ++ j) {
	u = a[j];
	v = 1ll * w * a[j + (s >> 1)] % MOD;
	a[j] = u + v;
	if (a[j] >= MOD) a[j] -= MOD;
	a[j + (s >> 1)] = u - v + MOD;
	if (a[j + (s >> 1)] >= MOD) a[j + (s >> 1)] -= MOD;
	w = 1ll * w * wp % MOD;
      }
    }
  }
  if (sgn) {
    wp = power(n,MOD-2);
    for (int i = 0 ; i < n ; ++ i)
      a[i] = 1ll * a[i] * wp % MOD;
  }
}
