inline void ntt(int *a,int n,int tag){
	static int r[N],cnt;cnt=-2;
	for(int i=n;i;i>>=1,++cnt);
	for(int i=0;i<n;++i){
		r[i]=(r[i>>1]>>1)|((i&1)<<cnt);
		if(r[i]>i)swap(a[i],a[r[i]]);
	}
	for(int i=1;i<n;i<<=1){
		int u=qpow(tag==1?G1:G2,mod/i/2),w=1;
