template<int X>
struct NTT{
  static constexpr int md = bmds(X);
  static constexpr int rt = brts(X);

  inline int add(int a,int b){
    a+=b;
    if(a>=md) a-=md;
    return a;
  }

  inline int mul(int a,int b){
    return 1LL*a*b%md;
  }

  inline int pow(int a,int b){
    int res=1;
    while(b){
      if(b&1) res=mul(res,a);
      a=mul(a,a);
      b>>=1;
    }
    return res;
  }

  inline int inv(int x){
    return pow(x,md-2);
  }

  vector<vector<int> > rts,rrts;

  void ensure_base(int n){
    if((int)rts.size()>=n) return;
    rts.resize(n);rrts.resize(n);
    for(int i=1;i<n;i<<=1){
      if(!rts[i].empty()) continue;
      int w=pow(rt,(md-1)/(i<<1));
      int rw=inv(w);
      rts[i].resize(i);rrts[i].resize(i);
      rts[i][0]=1;rrts[i][0]=1;
      for(int k=1;k<i;k++){
	rts[i][k]=mul(rts[i][k-1],w);
	rrts[i][k]=mul(rrts[i][k-1],rw);
      }
    }
  }

  void ntt(vector<int> &a,bool f,int n=-1){
    if(n==-1) n=a.size();
    assert((n&(n-1))==0);

    for(int i=0,j=1;j+1<n;j++){
      for(int k=n>>1;k>(i^=k);k>>=1);
      if(i>j) swap(a[i],a[j]);
    }

    for(int i=1;i<n;i<<=1){
      for(int j=0;j<n;j+=i*2){
	for(int k=0;k<i;k++){
	  int z=mul(a[i+j+k],f?rrts[i][k]:rts[i][k]);
	  a[i+j+k]=add(a[j+k],md-z);
	  a[j+k]=add(a[j+k],z);
	}
      }
    }

    if(f){
      int tmp=inv(n);
      for(int i=0;i<n;i++) a[i]=mul(a[i],tmp);
    }
  }

  vector<int> multiply(vector<int> &a,vector<int> &b){
    int need=a.size()+b.size()-1;
    int sz=1;
    while(sz<need) sz<<=1;
    ensure_base(sz);

    vector<int> f(sz),g(sz);
    for(int i=0;i<(int)a.size();i++) f[i]=a[i];
    for(int i=0;i<(int)b.size();i++) g[i]=b[i];
    ntt(f,0);ntt(g,0);
    for(int i=0;i<sz;i++) f[i]=mul(f[i],g[i]);
    ntt(f,1);

    f.resize(need);
    return f;
  }

};

int N;
vector<int> edge[202020], dp(202020,1);
vec ans(202020,0);
vector<int> a, b;

void dfs(int no, int par){
  for(int to:edge[no]){
    if(to==par) continue;
    dfs(to,no);
    dp[no] += dp[to];
  }
}

void dfs2(int no, int par){
  for(int to:edge[no]) a[dp[to]] += 1; 
  for(int to:edge[no]){
    if(to==par) continue;
    int x = dp[to];
    dp[to] = N;
    dp[no] -= x;
    dfs2(to,no);
    dp[to] = x;
    dp[no] = N;
  }
}

void solve(){
  cin >> N;
  init(N+10);
  a.assign(N+1,0), b.assign(N+1,0);
  REP(i,N-1){
    int x,y;
    cin >> x >> y; x--; y--;
    edge[x].push_back(y);
    edge[y].push_back(x);
  }

  dfs(0,-1);
  dfs2(0,-1);

  NTT<1> ntt;
  REP2(i,N) a[i] *= fact[i].val, a[i] %= MODS[2];
  REP2(i,N) b[i] = inv[N-i].val;

  auto c = ntt.multiply(a,b);

  FOR2(i,1,N) cout << cmb(N,i)*N - inv[i]*c[N+i] << endl; 
}

