    B = polyInv(A, (n+1)>>1), prepare(n<<1);
    NTT(A, 0), NTT(B, 0);
    for(int i = 0; i < lim; ++i) B[i] = (2ll-1ll*A[i]*B[i]%P+P)%P*B[i]%P;
    NTT(B, 1), B.set(n-1);
    return B;
}
Poly operator / (Poly A, Poly B)
{
    int n = A.ti(), m = B.ti(); A.rev(), B.rev();
    A = A*polyInv(B, n-m+1), A.set(n-m), A.rev();
    return A;
}
Poly operator % (Poly A, Poly B)
{
    if(A.ti() < B.ti()) return A;
    A = A-(A/B)*B; A.set(B.ti()-1);
    return A;
}
Poly polyDer(Poly A, int n = -1)
{
    if(n == -1) n = A.ti()+1;
    for(int i = 0; i < n-1; ++i) A[i] = 1ll*(i+1)*A[i+1]%P; A[n-1] = 0;
    return A;
}
Poly H[N<<2];
void build(int x, int l, int r, int *px)
{
    if(l == r) return (void)(H[x].set(1), H[x][0] = P-px[l], H[x][1] = 1);
    int mid = (l+r)>>1; build(x<<1, l, mid, px), build(x<<1|1, mid+1, r, px);
    H[x] = H[x<<1]*H[x<<1|1];
}
void solve(int x, int l, int r, int* px, int* py, Poly F)
{
    if(r-l+1 <= 512)
    {
        int n = F.ti(), *f = &F[0];
        for(int k = l; k <= r; ++k)
        {
            int64 x = px[k], y = 0;
            for(int i = n; ~i; --i) y = (y*x%P+f[i])%P;
            py[k] = y;
        }
        return;
    }
    int mid = (l+r)>>1;
    solve(x<<1, l, mid, px, py, F%H[x<<1]);
    solve(x<<1|1, mid+1, r, px, py, F%H[x<<1|1]);
}
Poly solve(int x, int l, int r, int *p)
{
    Poly F; if(l == r) return F.set(0), F[0] = p[l], F;
    int mid = (l+r)>>1;
    F = H[x<<1|1]*solve(x<<1, l, mid, p)+H[x<<1]*solve(x<<1|1, mid+1, r, p);
    return F;
}
void evaluate(Poly F, int n, int *px, int *py, int t = 1)
{
    if(t) build(1, 1, n, px);
    solve(1, 1, n, px, py, F%H[1]);
}
Poly interpolate(int n, int *px, int *py)
{
    static int pi[N]; build(1, 1, n, px);
    evaluate(polyDer(H[1]), n, px, pi, 0);
    for(int i = 1; i <= n; ++i) py[i] = py[i]*qpow(pi[i], P-2)%P;
    return solve(1, 1, n, py);
}
