double PI = acos (-1.0);
struct comp
{
    double a, b;///a + bi
    comp (): a (0.0), b (0.0) {}
    comp (double _a, double _b): a (_a), b (_b) {}
    comp (int val): a (val), b (0.0) {}
};
comp unit (int N) {comp x; x.a = (double) cos (2.0 * PI / N), x.b = sin (2.0 * PI / N); return x;}
comp operator / (comp x, double val) {return comp (x.a / val, x.b / val);}
comp operator - (comp a, comp b) {return comp (a.a - b.a, a.b - b.b);}
comp operator + (comp a, comp b) {return comp (a.a + b.a, a.b + b.b);}
comp operator * (comp a, comp b) {return comp (1.0 * a.a * b.a - 1.0 * a.b * b.b, 1.0 * a.b * b.a + 1.0 * a.a * b.b);}

void DFT (comp a[], int N, bool inv)
{
    for (int i=0; i<N; i++)
        if (i < rev[i]) swap (a[i], a[rev[i]]);
    for (int l=2; l<=N; l <<= 1)
    {
        comp omega = unit (l);
        if (inv) omega = unit (-l);
        for (int i=0; i<N; i+=l)
        {
            comp put = comp(1.0);
            for (int j=0; j<l / 2; j++)
            {
                comp u = a[i + j], v = a[i + j + l / 2] * put;
                a[i + j] = u + v;
                a[i + j + l / 2] = u - v;
                put = put * omega;
            }
        }
    }
    if (inv)
    {
        for (int i=0; i<N; i++)
            a[i] = a[i] / N;
    }
}

void GetProd (int a[], int b[], int c[], int n)
{
    int N = 1;
    while (N <= 2 * n) N <<= 1;
    for (int i=0; (1<<i) < N; i++)
        for (int j=0; j<N; j++)
            rev[j] = ((rev[j] << 1) | ((j >> i) & 1));
    comp dfa[N], dfb[3][N], aux[N];
    for (int i=0; i<N; i++)
        c[i] = 0;
    for (int i=0; i<3; i++)
    {
        for (int j=0; j<N; j++)
            dfb[i][j] = comp (b[j] % Konst), b[j] /= Konst;
        DFT (dfb[i], N, 0);
    }
    int put = 1;
    for (int i=0; i<3; i++)
    {
        for (int j=0; j<N; j++)
            dfa[j] = comp (a[j] % Konst), a[j] /= Konst;
        DFT (dfa, N, 0);
        int aux_put = put;
        for (int j=0; j<3; j++)
        {
            for (int k=0; k<N; k++)
                aux[k] = dfa[k] * dfb[j][k];
            DFT (aux, N, 1);
            for (int k=0; k<N; k++)
            {
                int curr = ((long long) (aux[k].a + 0.5)) % mod;
                c[k] = ((long long) c[k] + 1LL * aux_put * curr) % mod;
            }
            aux_put = (1LL * aux_put * Konst) % mod;
        }
        put = (1LL * put * Konst) % mod;
    }
}

