typedef long long ll;
cpnst ll mod=924844033,g=5;
ll qpow(ll x,ll k){ll r=1;for(;k;k>>=1,(x*=x)%=mod)if(k&1)(r*=x)%=mod;return r;}
int rev[1111111],V;
void resiz(int _v)
{
	V=_v;
	register int i;
	for(i=1;i<V;i++)rev[i]=(rev[i>>1]>>1)|((i&1)*(V>>1));
}
int wi[1111111];
void swap(register ll&x,register ll&y)
{x^=y^=x^=y;}
void NTT(ll*x,int op)
{
	register int i,ii,iii;
	for(i=1;i<V;i++)if(rev[i]>i)swap(x[i],x[rev[i]]);
	wi[0]=1;
	for(i=1;i<V;i<<=1)
	{
		register int w=qpow(g,(mod-1)/(i<<1));
		if(op<0)w=qpow(w,mod-2);
		for(register int*p=wi+1;p<wi+i;p++)*p=*(p-1)*1ll*w%mod;
		for(ii=0;ii<V;ii+=(i<<1))
			for(iii=0;iii<i;iii++)
			{
				int px=ii+iii,py=px+i;
				ll vx=x[px]+wi[iii]*x[py],vy=x[px]-wi[iii]*x[py];
				x[px]=vx%mod,x[py]=vy%mod; 
			}
	}ll t=op>0?1:qpow(V,mod-2);
	for(i=0;i<V;i++)x[i]=(x[i]+mod)*t%mod;
}
