struct NTT{
	int n,r[N<<2],a[N<<2],b[N<<2],W[N<<2];
	inline void Pre(){
		int to=n<<1,l=0;
		for(n=1;n<=to;n<<=1) ++l; --l;
		for(RG int i=0;i^n;++i) r[i]=(r[i>>1]>>1)|((i&1)<<l);
	}
	inline void Trans(int *P,int op){
		for(RG int i=0;i^n;++i) if(i<r[i]) swap(P[i],P[r[i]]);
		for(RG int i=1;i<n;i<<=1){
			int w=Pow(5,(MOD-1)/(i<<1));
			if(op==-1) w=Pow(w,MOD-2); W[0]=1;
			for(RG int k=1;k^i;++k) W[k]=1LL*W[k-1]*w%MOD;
			for(RG int p=i<<1,j=0;j<n;j+=p)
				for(RG int k=0;k^i;++k){
					int X=P[j+k],Y=1LL*P[i+j+k]*W[k]%MOD;
					P[j+k]=Plu(X,Y),P[i+j+k]=Plu(X,MOD-Y);
				}
		}
		if(op==-1)
			for(RG int i=0,Inv=Pow(n,MOD-2);i^n;++i)
				P[i]=1LL*P[i]*Inv%MOD;
	}
}   F;

