            ReRooting_dfs_sub<sum_t>(e.to, idx, f, gg, ident, subdp, dp, g_dp, g_ndp, memo, seen);
            if (!seen[idx][i]) {
                memo[idx][i] = gg(subdp[e.to], e);
                seen[idx][i] = true;
            }
            subdp[idx] = f(subdp[idx], memo[idx][i]);
