    template <typename sum_t>
    void ReRooting_dfs_all(int idx, int par, const sum_t& top,
        const function<sum_t(sum_t, sum_t)>& f,
        const function<sum_t(sum_t, Edge)>& gg,
        const sum_t& ident,
        vector<sum_t>& subdp,
        vector<sum_t>& dp,
