void NTT(long long *A,int n,int type){
	register int i,j,k,mid,R;
	register int Wn,W,x,y;
	for(i=0;i<n;i++) if(i<r[i]) swap(A[i],A[r[i]]);
	for(mid=1;mid<n;mid<<=1){
		Wn=power(G,(Mod-1)/(mid<<1));
