		for(R=mid<<1,j=0;j<n;j+=R){
			W=1;
			for(k=0;k<mid;k++,W=1ll*W*Wn%Mod){
				x=A[j+k],y=1ll*W*A[j+mid+k]%Mod;
				A[j+k]=(x+y)%Mod;
				A[j+k+mid]=(x-y+Mod)%Mod;
			}
		}
	}
	if(type==-1){
		int Inv=power(n,Mod-2);
		for(i=0;i<=n;i++)	A[i]=1ll*A[i]*Inv%Mod;
	}
	return;
}

