     fac[0] = 1; ifac[0] = 1; inv[0] = 1;
    for(int i = 1; i < maxn; i++){
        inv[i] = (i == 1) ? 1 : 1ll * inv[mod % i] * (mod - mod / i) % mod;
        fac[i] = 1ll *  fac[i - 1] * i % mod;
        ifac[i] = 1ll * ifac[i - 1] * inv[i] % mod;
    }
    int ans = 0;
    for(int i = 1; i <= n; i++)
        f[i] = 1ll * f[i] *fac[i] % mod; 
    for(int i = 0; i <= n; i++) g[i] = ifac[i];
    reverse(f, f + n + 1);
    int len = 0; 
    for(lim = 1; lim <= (n << 1); lim <<= 1, len++);
    for(int i = 1; i < lim; i++)
    rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (len  - 1));
    ntt(g, 1); ntt(f, 1);
    for(int i = 0; i < lim; i++) g[i] = 1ll * g[i] * f[i] % mod;
    ntt(g, -1); 
    for(int i = 0; i < lim; i++) g[i] = 1ll * g[i] * ksm(lim, mod - 2) % mod;
    reverse(g, g + n + 1);
    for(int i = 1; i <= n; i++){
        ans = 1ll * (n + 1) * C(n, i) % mod;
        ans = (ans - 1ll * g[i] * ifac[i] % mod + mod) % mod;
        printf("%d\n", ans);
    } 
