template <signed mod>
struct NumberTheoreticTransform {
private:
    vector<signed> rev, rts;  //swap計算用の配列, \omega^iに相当するもの
    signed base, max_base, root;
    inline signed mod_add(signed a, signed b) {
        a += b;
        if (a >= mod)
            a -= mod;
        return a;
    }
    inline signed mod_mul(signed a, signed b) {
        return (1ull * a * b) % (unsigned long long)mod;
    }
    inline signed mod_pow(signed a, signed n) {
        signed ret = 1;
        while (n) {
            if (n & 1)
                ret = mod_mul(ret, a);
            a = mod_mul(a, a);
            n >>= 1;
        }
        return ret;
    }
    inline signed mod_inv(signed a) {
        return mod_pow(a, mod - 2);
    }
    //
public:
    NumberTheoreticTransform() : base(1), rev{0, 1}, rts{0, 1} {
        assert(mod >= 3 && mod & 1 == 1);
        signed tmp = mod - 1;
        max_base = 0;
        while (tmp % 2 == 0) {
            tmp >>= 1;
            max_base++;
        }
        root = 2;
        while (mod_pow(root, (mod - 1) >> 1) == 1)
            root++;
        assert(mod_pow(root, mod - 1) == 1);
        root = mod_pow(root, (mod - 1) >> max_base);
    }
    //
private:
    void ensure_base(signed nbase) {
        if (nbase <= base)
            return;
        assert(nbase <= max_base);
        rev.resize(1 << nbase);
        rts.resize(1 << nbase);
        for (signed i = 0; i < (1 << nbase); i++) {
            rev[i] = (rev[i >> 1] >> 1) + ((i & 1) << (nbase - 1));
        }
        while (base < nbase) {
            signed z = mod_pow(root, 1 << (max_base - 1 - base));
            for (signed i = 1 << (base - 1); i < (1 << base); i++) {
                rts[i << 1] = rts[i];
                rts[(i << 1) + 1] = mod_mul(rts[i], z);
            }
            base++;
        }
    }
    void ntt(vector<signed>& a) {
        const signed n = (signed)a.size();
        assert((n & (n - 1)) == 0);
        signed zeros = __builtin_ctz(n);
        ensure_base(zeros);
        signed shift = base - zeros;
        for (signed i = 0; i < n; i++) {
            if (i < (rev[i] >> shift))
                swap(a[i], a[rev[i] >> shift]);
        }
        for (signed k = 1; k < n; k <<= 1) {
            for (signed i = 0; i < n; i += 2 * k) {
                for (signed j = 0; j < k; j++) {
                    signed z = mod_mul(a[i + j + k], rts[j + k]);
                    a[i + j + k] = mod_add(a[i + j], mod - z);
                    a[i + j] = mod_add(a[i + j], z);
                }
            }
        }
    }
    //
public:
    vector<signed> multiply(vector<signed> a, vector<signed> b) {
        if (a.empty() || b.empty())
            return {};
        bool eq = (a == b);
        signed need = a.size() + b.size() - 1;
        signed nbase = 1;
        while ((1 << nbase) < need)
            nbase++;
        ensure_base(nbase);
        signed sz = 1 << nbase;
        a.resize(sz, 0);
        b.resize(sz, 0);
        ntt(a);
        if (eq)
            b = a;
        else
            ntt(b);
        signed inv_sz = mod_inv(sz);
        for (signed i = 0; i < sz; i++) {
            a[i] = mod_mul(a[i], mod_mul(b[i], inv_sz));
        }
        reverse(a.begin() + 1, a.end());
        ntt(a);
        a.resize(need);
        return a;
    }
    vector<long long> multiply(vector<long long> a, vector<long long> b) {
        vector<signed> A(a.size()), B(b.size());
        for (signed i = 0; i < a.size(); i++) {
            A[i] = a[i];
        }
        for (signed i = 0; i < b.size(); i++) {
            B[i] = b[i];
        }
        A = multiply(A, B);
        a.resize(A.size());
        for (signed i = 0; i < A.size(); i++)
            a[i] = A[i];
        return a;
    }
};


template <uint MD>
struct ModInt {
    using M = ModInt;
    const static M G;
    uint v;
    ModInt(ll _v = 0) { set_v(_v % MD + MD); }
    M& set_v(uint _v) {
        v = (_v < MD) ? _v : _v - MD;
        return *this;
    }
    explicit operator bool() const { return v != 0; }
    M operator-() const { return M() - *this; }
    M operator+(const M& r) const { return M().set_v(v + r.v); }
    M operator-(const M& r) const { return M().set_v(v + MD - r.v); }
    M operator*(const M& r) const { return M().set_v(ull(v) * r.v % MD); }
    M operator/(const M& r) const { return *this * r.inv(); }
    M& operator+=(const M& r) { return *this = *this + r; }
    M& operator-=(const M& r) { return *this = *this - r; }
    M& operator*=(const M& r) { return *this = *this * r; }
    M& operator/=(const M& r) { return *this = *this / r; }
    bool operator==(const M& r) const { return v == r.v; }
    M pow(ll n) const {
        M x = *this, r = 1;
        while (n) {
            if (n & 1)
                r *= x;
            x *= x;
            n >>= 1;
        }
        return r;
    }
    M inv() const { return pow(MD - 2); }
    /*
    M inv() const {
        long long b = MD, u = 1, v = 0;
        long long a = (*this).v;
        while (b) {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        u %= MD;
        if (u < 0)
            u += MD;
        return M{u};
    }
    */
    friend ostream& operator<<(ostream& os, const M& r) { return os << r.v; }
    friend istream& operator>>(istream& is, M& r) { return is >> r.v; }
};

using Mint = ModInt<MOD>;
const int MN = 2000010;
Mint fact[MN], iFac[MN];

void first() {
    fact[0] = Mint(1);
    for (int i = 1; i < MN; i++)
        fact[i] = fact[i - 1] * Mint(i);
    iFac[MN - 1] = fact[MN - 1].inv();
    for (int i = MN - 1; i >= 1; i--) {
        iFac[i - 1] = iFac[i] * Mint(i);
    }
    assert(fact[2345] * iFac[2345] == Mint(1));
}
Mint C(int n, int k) {
    if (n < k || k < 0)
        return Mint(0);
    return fact[n] * iFac[k] * iFac[n - k];
}

