private:
    template <typename sum_t>
    void ReRooting_dfs_sub(int idx, int par,
        const function<sum_t(sum_t, sum_t)>& f,
        const function<sum_t(sum_t, Edge)>& gg,
        const sum_t& ident,
        vector<sum_t>& subdp,
        vector<sum_t>& dp,
        vector<vector<sum_t>>& g_dp,
        vector<vector<sum_t>>& g_ndp,
        vector<vector<sum_t>>& memo,
        vector<vector<bool>>& seen) {
        for (int i = 0; i < (int)((*this)[idx].size()); i++) {
            auto& e = (*this)[idx][i];
            if (e.to == par)
                continue;
            ReRooting_dfs_sub<sum_t>(e.to, idx, f, gg, ident, subdp, dp, g_dp, g_ndp, memo, seen);
            if (!seen[idx][i]) {
                memo[idx][i] = gg(subdp[e.to], e);
                seen[idx][i] = true;
            }
            subdp[idx] = f(subdp[idx], memo[idx][i]);
        }
    }
    template <typename sum_t>
    void ReRooting_dfs_all(int idx, int par, const sum_t& top,
        const function<sum_t(sum_t, sum_t)>& f,
        const function<sum_t(sum_t, Edge)>& gg,
        const sum_t& ident,
        vector<sum_t>& subdp,
        vector<sum_t>& dp,
        vector<vector<sum_t>>& g_dp,
        vector<vector<sum_t>>& g_ndp,
        vector<vector<sum_t>>& memo,
        vector<vector<bool>>& seen) {
        sum_t buff{ident};
        for (int i = 0; i < (int)((*this)[idx].size()); i++) {
            auto& e = (*this)[idx][i];
            g_ndp[idx][i] = buff;
            if (!seen[idx][i]) {
                memo[idx][i] = gg(par == e.to ? top : subdp[e.to], e);
                seen[idx][i] = true;
            }
            g_dp[idx][i] = memo[idx][i];
            buff = f(buff, g_dp[idx][i]);
        }
        dp[idx] = buff;
        buff = ident;
        for (int i = (*this)[idx].size() - 1; i >= 0; i--) {
            auto& e = (*this)[idx][i];
            if (e.to != par)
                ReRooting_dfs_all<sum_t>(e.to, idx, f(g_ndp[idx][i], buff), f, gg, ident, subdp, dp, g_dp, g_ndp, memo, seen);
            g_ndp[idx][i] = f(g_ndp[idx][i], buff);
            buff = f(buff, g_dp[idx][i]);
        }
    }
    //
public:
    template <typename sum_t>
    pair<vector<sum_t>, vector<vector<sum_t>>> Tbuild_ReRooting(
        const function<sum_t(sum_t, sum_t)> f,
        const function<sum_t(sum_t, Edge)> gg,
        sum_t ident) {
        assert(tree);
        int N = (*this).size();
        vector<sum_t> subdp(N, ident), dp(N, ident);
        vector<vector<sum_t>> g_dp(N), g_ndp(N), memo(N);
        vector<vector<bool>> seen(N);
        for (int i = 0; i < N; i++) {
            int S = (*this)[i].size();
            g_dp[i].resize(S, ident);
            g_ndp[i].resize(S, ident);
            memo[i].resize(S);
            seen[i].resize(S, false);
        }
        stack<int> stk;
        stk.push(0);
        vector<int> par(N), ord(N);
        int index = 0;
        par[0] = -1;
        while (!stk.empty()) {
            int node = stk.top();
            stk.pop();
            ord[index++] = node;
            for (auto& e : (*this)[node]) {
                if (e.to == par[node])
                    continue;
                stk.push(e.to);
                par[e.to] = node;
            }
        }
        for (int k = ord.size() - 1; k >= 0; k--) {
            int idx = ord[k];
            for (int i = 0; i < (int)((*this)[idx].size()); i++) {
                auto& e = (*this)[idx][i];
                if (e.to == par[idx])
                    continue;
                if (!seen[idx][i]) {
                    memo[idx][i] = gg(subdp[e.to], e);
                    seen[idx][i] = true;
                }
                subdp[idx] = f(subdp[idx], memo[idx][i]);
            }
        }
        vector<sum_t> top(N, ident);
        for (int k = 0; k < (int)(ord.size()); k++) {
            int idx = ord[k];
            sum_t buff{ident};
            for (int i = 0; i < (int)((*this)[idx].size()); i++) {
                auto& e = (*this)[idx][i];
                g_ndp[idx][i] = buff;
                if (!seen[idx][i]) {
                    memo[idx][i] = gg(par[idx] == e.to ? top[idx] : subdp[e.to], e);
                    seen[idx][i] = true;
                }
                g_dp[idx][i] = memo[idx][i];
                buff = f(buff, g_dp[idx][i]);
            }
            dp[idx] = buff;
            buff = ident;
            for (int i = (*this)[idx].size() - 1; i >= 0; i--) {
                auto& e = (*this)[idx][i];
                if (e.to != par[idx])
                    top[e.to] = f(g_ndp[idx][i], buff);
                g_ndp[idx][i] = f(g_ndp[idx][i], buff);
                buff = f(buff, g_dp[idx][i]);
            }
        }
        return make_pair(dp, memo);
    }
};
