void ins(int a,int b){
	Next[++o]=Last[a],Last[a]=o;
	End[o]=b;
}
void inss(int a,int b){
	ins(a,b),ins(b,a);
}
int ksm(int a,int b){
	int ret=1;
	while(b){
		if(b&1)ret=1ll*ret*a%P;
		b>>=1,a=1ll*a*a%P;
	}
	return ret;
}
void init(){
	fac[0]=1;
	for(int i=1;i<=N;++i)fac[i]=1ll*fac[i-1]*i%P;
	invfac[N]=ksm(fac[N],P-2);
	for(int i=N;i>=1;--i)invfac[i-1]=1ll*invfac[i]*i%P;
	while(len<2*N)len<<=1,tot++;
	for(int i=0;i<len;++i)rev[i]=(rev[i>>1]>>1)|((i&1)<<(tot-1));
}
void NTT(ll *T,int len,int ty){
	for(int i=0;i<len;++i)if(i<rev[i])swap(T[i],T[rev[i]]);
	for(int m=1;m<len;m<<=1){
		ll wn=ksm(G,(ty*(P-1)/(m<<1)+P-1)%(P-1));
		for(int i=0;i<len;i+=m<<1){
			ll mul=1;
			for(int j=0;j<m;++j){
				ll x=T[i+j],y=T[i+j+m]*mul%P;
				T[i+j]=(x+y)%P,T[i+j+m]=(x-y+P)%P;
				mul=mul*wn%P;
			}
		}
	}
	if(ty==1)return;
	int inv=ksm(len,P-2);
	for(int i=0;i<len;++i)T[i]=T[i]*inv%P;
}
