int ksm(int x,int y){
	int ans=1;
	for (;y;y>>=1,x=x*x%M)
		if (y&1)(ans*=x)%=M;
	return ans;	
}
int C(int x,int y){
	if (x<y)return 0;
	return fac[x]*inv[y]%M*inv[x-y]%M;
}
void init(int y[],int len){
	for (int i=1,j=len/2;i<len-1;i++){
		if (i<j)swap(y[i],y[j]);
		int k=len/2;
		while (j>=k){
			j-=k;
			k/=2;
		}
		j+=k;
	}
}
void ntt(int y[],int len,int opt){
	init(y,len);
	for (int h=2;h<=len;h<<=1){
		int wn=ksm(5,(M-1)/h);
		if (opt==-1)wn=ksm(wn,M-2);
		for (int j=0;j<len;j+=h){
			int w=1;
			for (int k=j;k<j+h/2;k++){
				int u=y[k],v=w*y[k+h/2]%M;
				y[k]=(u+v)%M;
				y[k+h/2]=(u-v+M)%M;
				w=w*wn%M;
			}
		}
	}
	if (opt==1)return;
	int temp=ksm(len,M-2);
	for (int i=0;i<len;i++)(y[i]*=temp)%=M;
}
