        REP(i, sz) f_tmp[l + sz + i] = f[l + i] + f[l + sz + i] * pow_inv_e[(sz + i) << t];
        FOR(i, l, r) f[i] = f_tmp[i];
    }

public:

    int N, n;
    ModInt<MOD> e, inv_N;
    vector<ModInt<MOD>> pow_e, pow_inv_e;

    NTT(int N, ModInt<MOD> e): N(N), e(e){

        n = 31 - __builtin_clz((signed)N);
        assert(N == (1 << n));

        assert((e.pow(N)).val == 1);
        pow_e.resize(N);
        pow_e[0] = 1;
        bool e_valid = true;
        FOR(i, 1, N){
            pow_e[i] = pow_e[i - 1] * e;
            if(pow_e[i].val == 1) e_valid = false;
        }
        assert(e_valid);

        pow_inv_e.resize(N);
        pow_inv_e[0] = 1;
        FOR(i, 1, N) pow_inv_e[i] = pow_e[N - i];
        inv_N = ((ModInt<MOD>)N).inv();

        f.resize(N);
        f_tmp.resize(N);
    }

    void exec(vector<ModInt<MOD>> &F, bool inverse = false){
        assert(F.size() == N);
        f.swap(F);
        if(!inverse) forward_exec(0, N, 0);
        else inverse_exec(0, N, 0);
        F.swap(f);
        if(inverse){
            REP(i, N) F[i] *= inv_N;
        }
    }

    vector<ModInt<MOD>> convolution(vector<ModInt<MOD>> A, vector<ModInt<MOD>> B){
        exec(A);
        exec(B);
        vector<ModInt<MOD>> C(N);
        REP(i, N) C[i] = A[i] * B[i];
        exec(C, true);
        return C;
    }
};

struct edge{int to, cost;};

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec dp;
    vec ls;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        dp.resize(N);
    }

    void add_Directed_edge(int from, int to, int cost = 1){
        G[from].push_back(edge({to, cost}));
    }

    void add_Undirected_edge(int v1, int v2, int cost = 1){
        add_Directed_edge(v1, v2, cost);
        add_Directed_edge(v2, v1, cost);
    }

    void dfs(int v, int p = -1){
        dp[v] = 1;
        int n = N - 1;
        for(auto e: G[v]) if(e.to != p){
            dfs(e.to, v);
            dp[v] += dp[e.to];
            ls.pb(dp[e.to]);
            n -= dp[e.to];
        }
        if(n) ls.pb(n);
    }

};

signed main(){

    int N; cin >> N;
    Graph G(N);
    int a, b;
    REP(i, N - 1){
        cin >> a >> b;
        G.add_Undirected_edge(a - 1, b - 1);
    }
    G.dfs(0);

    mvec ans(N + 1);
    Combination C(N);
    vec ls = G.ls;

    int n = bit(19);
    mint e = pow((mint)5, (mod - 1) / n);
    NTT<mod> ntt(n, e);
    mvec f(n, 0), g(n, 0);
    for(int s: ls) f[s] += C.fact[s];
    g[0] = 1;
    FOR(i, 1, N + 1) g[n - i] = C.invfact[i];
    mvec conv = ntt.convolution(f, g);

    FOR(K, 1, N + 1) ans[K] = C.nCr(N, K) * N - conv[K] * C.invfact[K];
    FOR(K, 1, N + 1) Out(ans[K]);

    return 0;
}

