	for(int i=beg[u];i;i=nxt[i])
		if(to[i]!=fa)
		{
			dfs(to[i],u);
			siz[u]+=siz[to[i]];
			chk(--a[siz[to[i]]]);
		}
	chk(--a[n-siz[u]]);
}

inline void NTT(ll *a,int n,bool f)
{
	for(int i=0;i<n;i++)
		if(i<rev[i])
			swap(a[i],a[rev[i]]);
	for(int h=2;h<=n;h<<=1)
	{
		ll w=qpow(5,(md-1)/h);
		if(f)w=qpow(w,md-2);
		for(int j=0;j<n;j+=h)
		{
			ll wn=1;
			for(int k=j;k<j+(h>>1);k++)
			{
				ll x=a[k],y=wn*a[k+(h>>1)]%md;
				a[k]=(x+y)%md;
				a[k+(h>>1)]=(x-y+md)%md;
				wn=wn*w%md;
			}
		}
	}

	if(f)
		for(ll i=0,invn=qpow(n,md-2);i<n;i++)
			a[i]=a[i]*invn%md;
}

inline void init()
{
	fac[0]=1;
	for(ll i=1;i<N;i++)
		fac[i]=fac[i-1]*i%md;
	inv[N-1]=qpow(fac[N-1],md-2);
	for(ll i=N-1;i>=1;i--)
		inv[i-1]=inv[i]*i%md;
}

