void dft(int *x,int n,int *Eps)
{
	int i,j,k,u,t,wn,w;
	for(i=j=0;i<n;i++)
	{
		if(i<j) swap(x[i],x[j]);
		for(k=n>>1;(j^=k)<k;k>>=1);
	}
	for(i=1;i<n;i<<=1)
	{
		wn=(N/i)>>1;
		for(j=0;j<n;j+=i<<1)
			for(k=w=0;k<i;k++,w+=wn)
