}

long long combi(int a, int b) {
  if (b < 0 || b > a) return 0;
  long long res = fac[a];
  res = (res * inv_fac[b]) % mmod;
  res = (res * inv_fac[a-b]) % mmod;
  return res;
}

long long partial_combi(int a, int b) {
  if (b < 0 || b > a) return 0;
  long long res = fac[a];
//  res = (res * inv_fac[b]) % mmod;
  res = (res * inv_fac[a-b]) % mmod;
  return res;
}

