	for (int i = 1; i < n; i <<= 1)
	{
		int m = i << 1;
		int w = fpow(g, (mod - 1) / m);
		if (sig == -1) w = fpow(w, mod - 2);
		for (int j = 0; j < n; j += m)
		{
			int v = 1;
			for (int k = j; k < j + i; ++k, v = 1LL * v * w % mod)
			{
				int x = a[k], y = 1LL * a[k + i] * v % mod;
				a[k] = (x + y) % mod;
				a[k + i] = (x - y + mod) % mod;
			}
		}
	}
	if (sig == -1)
	{
		int invn = fpow(n, mod - 2);
		for (int i = 0; i < n; ++i) a[i] = 1LL * a[i] * invn % mod;
	}
}

