const int MAXN=1000005,MOD=924844033,ROOT=5;

int PowMod(int a,int b)
{
	int res=1;
	while(b)
	{
		if(b&1)
			res=1LL*res*a%MOD;
		a=1LL*a*a%MOD;
		b>>=1;
	}
	return res;
}

int fac[MAXN],ifac[MAXN];
void InitFac()
{
	fac[0]=1;
	for(int i=1;i<MAXN;i++)
		fac[i]=1LL*fac[i-1]*i%MOD;
	ifac[MAXN-1]=PowMod(fac[MAXN-1],MOD-2);
	for(int i=MAXN-2;i>=0;i--)
		ifac[i]=1LL*ifac[i+1]*(i+1)%MOD;
}

void NTT(int A[],int n,int mode)
{
	for(int i=0,j=0;i<n;i++)
	{
		if(i<j)
			swap(A[i],A[j]);
		int k=n>>1;
		while(j&k)
		{
			j^=k;
			k>>=1;
		}
		j^=k;
	}
	for(int i=1;i<n;i<<=1)
	{
		int w1=PowMod(ROOT,(MOD-1)/(i<<1)),w=1;
		if(mode==-1)
			w1=PowMod(w1,MOD-2);
		for(int j=0;j<i;j++,w=(1LL*w*w1)%MOD)
            for(int l=j,r=l+i;l<n;l+=(i<<1),r=l+i)
            {
                int temp=(1LL*A[r]*w)%MOD;
                A[r]=(A[l]-temp+MOD)%MOD;
                A[l]=(A[l]+temp)%MOD;
            }
	}
	if(mode==-1)
	{
		int inv=PowMod(n,MOD-2);
		for(int i=0;i<n;i++)
			A[i]=1LL*A[i]*inv%MOD;
	}
}

