	for (int i = 0; i < to[x].size(); ++i){
		int y = to[x][i];
		if (y == f) continue;
		dfs(y, x);
		sz[x] += sz[y];
		--a[sz[y]];
		--a[n - sz[y]];
	}
}

LL pwr(LL a, LL b){
	LL res = 1;
	for (; b; b >>= 1, (a *= a) %= mo)
		if (b & 1) (res *= a) %= mo;
	return res; 
}

LL inv(LL x){
	return pwr(x, mo - 2);
}

void ntt(LL *a, int n, int d = 1){
	REP(i, 0, n - 1) if (i > rev[i]) swap(a[i], a[rev[i]]);
	for (int m = 2; m <= n; m <<= 1){
		LL wn = pwr(g, d * (mo - 1) / m + mo - 1);
		for (int i = 0; i < n; i += m){
			LL w = 1;
			for (int j = i; j < i + m / 2; ++j){
				LL u = a[j], v = w * a[j + m / 2] % mo;
				a[j] = (u + v) % mo;
				a[j + m / 2] = (u - v) % mo;
				(w *= wn) %= mo;
			}
		}
	}
	if (d == -1){
		LL t = inv(n);
		REP(i, 0, n - 1) (a[i] *= t) %= mo;
	}
}

