	REP(i, 0, n) b[i] = inv(f[i]);
	REP(i, 0, n / 2) swap(a[i], a[n - i]);
	int len;
	for (len = 1; len < 2 * (n + 1); len <<= 1);
	REP(i, 1, len - 1)
		if (i & 1) rev[i] = (rev[i >> 1] >> 1) ^ (len >> 1);
		else rev[i] = (rev[i >> 1] >> 1);
	ntt(a, len); ntt(b, len);
	REP(i, 0, len - 1) (a[i] *= b[i]) %= mo;
	ntt(a, len, -1);
	PER(i, n - 1, 0){
		LL ans = a[i] * inv(f[n - i]) % mo;
