		LL wn=(ops) ? cheng(5,(mo-1)/l) : cheng(5,mo-1-(mo-1)/l);
		for(int i=0;i<n;i+=l)
		{
			LL w=1;
			for(int k=0;k<m;k++)
			{
				LL t=a[i+k+m]*w%mo;
				a[i+k+m]=(a[i+k]-t+mo)%mo;
				a[i+k]=(a[i+k]+t)%mo;
