#define ll long long
#define pb push_back
#define bit(a , b) (((a)>>(b))&1)

const int maxb = 19;
const int N = (1 << maxb);
const int maxn = N + 20;
const int mod = 924844033;

int bpw(int a , int b)
{
	if(!b)
		return 1;
	int x = bpw(a , b / 2);

	x = 1LL * x * x % mod;
	if(b&1)
		x = 1LL * x * a % mod;

	return x;
}

void rev(int* a)
{
	for(int i = 0; i < N; i++)
	{
		int k = 0;
		for(int j = 0; j < maxb; j++)
			if(bit(i , j))
				k |= 1 << (maxb - 1 - j);

		if(i < k)
			swap(a[i] , a[k]);
	}
}

void mul(int* a , int val)
{
	rev(a);

	for(int len = 2; len <= N; len *= 2)
	{
		int wn = bpw(5 , (mod - 1) / len);
		if(val == -1)
			wn = bpw(wn , mod - 2);
		for(int i = 0; i < N; i += len)
		{
			int nxt = len / 2 , pw = 1;
			for(int j = 0; j < nxt; j++)
			{
				int x = a[i + j] , y = a[i + j + nxt];
				a[i + j] = (x + 1LL * pw * y) % mod;
				a[i + j + nxt] = (x - 1LL * pw * y % mod + mod) % mod;
				pw = 1LL * pw * wn % mod;
			}
		}
	}

	if(val == -1)
	{
		int inv = bpw(N , mod - 2);
		for(int i = 0; i < N; i++)
			a[i] = 1LL * a[i] * inv % mod;
	}
}

vector<int> adj[maxn];

int t[maxn] , sz[maxn] , n , fac[maxn] , caf[maxn] , a[maxn] , b[maxn] , c[maxn];

