inline void add_edge(int from, int to)
{
	e[++e_num] = (edge) {head[from], to};
	head[from] = e_num;
}

int fastpow(int x, int y)
{
	int ans = 1;
	for (; y; y >>= 1, x = 1ll * x * x % Mod)
		if (y & 1) ans = 1ll * ans * x % Mod;
	return ans;
}

void dfs(int x, int fa)
{
	size[x] = 1;
	for (int i = head[x]; i; i = e[i].next)
	{
		int to = e[i].to; if (to == fa) continue;
		dfs(to, x), size[x] += size[to], ++g[size[to]];
	}
	++g[n - size[x]];
}

void FFT(int *p, int N)
{
	for (int i = 0; i < N; i++) if (i < r[i]) std::swap(p[i], p[r[i]]);
	for (int i = 1, s = 2, t = N >> 1; i < N; s <<= 1, t >>= 1, i <<= 1)
		for (int j = 0; j < N; j += s) for (int k = 0, o = 0; k < i; ++k, o += t)
		{
			int x = p[j + k], y = 1ll * w[o] * p[i + j + k] % Mod;
			p[j + k] = (x + y) % Mod, p[i + j + k] = (x - y + Mod) % Mod;
		}
}

int main()
{
	n = read(), fac[0] = inv[0] = 1;
	for (int i = 1; i <= n; i++) fac[i] = 1ll * fac[i - 1] * i % Mod;
	inv[n] = fastpow(fac[n], Mod - 2);
	for (int i = n - 1; i; i--) inv[i] = 1ll * inv[i + 1] * (i + 1) % Mod;
	for (int i = 1, a, b; i < n; i++)
		a = read(), b = read(), add_edge(a, b), add_edge(b, a);
	dfs(1, 0), g[0] = 0;
	for (int i = 1; i <= n; i++) c[i] = 1ll * n * C(n, i) % Mod;
	for (int i = 1; i <= n; i++) g[i] = 1ll * g[i] * fac[i] % Mod;
	for (int i = 0; i <= n; i++) f[i] = inv[i];
	std::reverse(g, g + n + 1); int N = 1, P = -1;
	while (N <= ((n + 1) << 1)) N <<= 1, ++P;
	for (int i = 1; i < N; i++) r[i] = (r[i >> 1] >> 1) | ((i & 1) << P);
	w[0] = 1, w[1] = fastpow(5, (Mod - 1) / N);
	for (int i = 2; i < N; i++) w[i] = 1ll * w[i - 1] * w[1] % Mod;
	FFT(f, N), FFT(g, N), w[1] = fastpow(554906420, (Mod - 1) / N);
	for (int i = 2; i < N; i++) w[i] = 1ll * w[i - 1] * w[1] % Mod;
	for (int i = 0; i < N; i++) f[i] = 1ll * f[i] * g[i] % Mod;
	FFT(f, N); int invn = fastpow(N, Mod - 2);
	for (int i = 0; i < N; i++) f[i] = 1ll * f[i] * invn % Mod;
	for (int i = 1; i <= n; i++) f[i] = 1ll * f[i] * inv[n - i] % Mod;
	for (int i = 1; i <= n; i++) printf("%d\n", (c[i] - f[n - i] + Mod) % Mod);
	return 0;
}

