	int qmod(int a,int b)
	{
		int t=1;
		while(b)
		{
			if(b%2) t=1ll*t*a%mmod;
			b/=2;
			a=1ll*a*a%mmod;
		}
		return t;
	}
	void ntt_pre(int n)
	{
		int len=0;
		while((1<<len)<n) len++;
		len--;
		for(int i=0;i<n;i++)
		{
			int k=0;
			for(int j=0;j<=len;j++) if(i&(1<<j)) k|=1<<(len-j);
			bitrev[i]=k;
		}
	}
	void ntt(int *x,int n,int o)
	{
		for(int i=0;i<n;i++) if(i>bitrev[i]) swap(x[i],x[bitrev[i]]);
		for(int s=2;s<=n;s*=2)
		{
			if(o==1 && g[s]==0) g[s]=qmod(grt,(mmod-1)/s);
			if(o==-1 && ng[s]==0) ng[s]=qmod(grt,mmod-1-(mmod-1)/s);
			int wn;
			if(o==1) wn=g[s];
			else wn=ng[s];
			for(int i=0;i<n;i+=s)
