		while(n-1<m) n*=2;
		ntt_pre(n);
		ntt(a,n,1);ntt(b,n,1);
		for(int i=0;i<n;i++) c[i]=1ll*a[i]*b[i]%mmod;
		ntt(c,n,-1);
		int ny=qmod(n,mmod-2);
		for(int i=0;i<n;i++) c[i]=1ll*c[i]*ny%mmod;
