	return s;
}

void init(int n){
	fac[0]=1;
	rep (i,1,n) fac[i]=(ll)fac[i-1]*i%mod;
	inv[n]=ksm(fac[n],mod-2);
	for (int i=n-1;~i;i--) inv[i]=(ll)inv[i+1]*(i+1)%mod;
}

int C(int n,int m){return (ll)fac[n]*inv[m]%mod*inv[n-m]%mod;}

void fft_init(int &n){
	int len=0; while (1<<len<n) len++; n=1<<len;
	int G=ksm(5,(mod-1)>>len); invn=ksm(n,mod-2);
	w[0]=w[n]=1;
	rep (i,1,n-1) w[i]=(ll)w[i-1]*G%mod,r[i]=(r[i>>1]>>1)|((i&1)<<len-1);
}

void fft(int *a,int all,int fl){
	rep (i,0,all-1) if (i<r[i]) swap(a[i],a[r[i]]);
	int n=2,m=1,x=all>>1;
	for (;n<=all;m=n,n<<=1,x>>=1)
		for (int i=0;i<all;i+=n)
			for (int k=0;k<m;k++){
				int t=(ll)w[fl?all-x*k:x*k]*a[i+m+k]%mod;
				a[i+m+k]=(a[i+k]+mod-t)%mod;
				a[i+k]=(a[i+k]+t)%mod;
			}
	if (fl) rep (i,0,all-1) a[i]=(ll)a[i]*invn%mod;
}

void solve(){
	memset(a,0,sizeof(a)),memset(b,0,sizeof(b));
	rep (i,2,n) a[sz[i]]++;
	rep (i,0,n) a[i]=(ll)a[i]*fac[i]%mod,b[i]=inv[i];
	reverse(b,b+n+1);
	int _n=2*n+1; fft_init(_n);
	fft(a,_n,0); fft(b,_n,0);
	rep (i,0,_n-1) a[i]=(ll)a[i]*b[i]%mod;
	fft(a,_n,1);
	rep (i,1,n) ans[i]=(ans[i]+mod-(ll)a[n+i]*inv[i]%mod)%mod;
}

