	dfs(1,0); init(n);
	rep (i,1,n) ans[i]=(ll)n*C(n,i)%mod;
	solve();
	rep (i,1,n) sz[i]=n-sz[i];
	solve();
	rep (i,1,n) printf("%d\n",ans[i]);
	return 0;
}
