void DFT(LL a[],int n)
{
    int j=0;
    for(int i=0;i<n;i++)
    {
        if(i<j) swap(a[i],a[j]);
        int t=n>>1;
        while(j&t)
        {
            j^=t;
            t>>=1;
        }
        j^=t;
    }
    int i=1,m;
    while(i<n)
    {
        m=i;
        i<<=1;
        for(int j=0;j<n;j+=i)
        {
            for(int k=0;k<m;k++)
            {
                LL z=w[(n/i)*k]*a[j+m+k]%mod;
                a[j+m+k]=(a[j+k]-z)%mod;
                a[j+k]=(a[j+k]+z)%mod;
            }
        }
    }
}
LL qp(LL x,LL y)
{
    if(y==0) return 1;
    if(y==1) return x;
    LL t=qp(x,y>>1);
    t=t*t%mod;
    if(y&1) t=t*x%mod;
