	}
}

void NTT(LL a[], int n, int d = 1) {
	for (int i = (n >> 1), j = 1; j < n; ++j) {
		if (i < j) swap(a[i], a[j]);
		int k; for (k = (n >> 1); i & k; i ^= k, k >>= 1);
		i ^= k;
	}
	for (int m = 2; m <= n; m <<= 1) {
		LL w = pow_mod(gi, (d * ((mo - 1) / m) + mo - 1) % (mo - 1), mo);
		for (int i = 0; i < n; i += m) {
			LL s = 1;
			for (int j = i; j < i + (m >> 1); ++j) {
				LL u = a[j], v = a[j + (m >> 1)] * s % mo;
				a[j] = (u + v) % mo; a[j + (m >> 1)] = (u - v + mo) % mo;
				s = s * w % mo;
			}
		}
	} 
	if (d == -1) {
		LL xinv = pow_mod(n, mo - 2, mo);
		for (int i = 0; i < n; ++i) a[i] = a[i] * xinv % mo;
	}
}

