int pwr(int a,int b){
    int ans = 1;
    while(b){
        if(b & 1)
            ans = (ans * 1LL * a) % mod;
        a = (a * 1LL * a) % mod;
        b >>= 1;
    }
    return ans;
}

ll iv[(1 << MAX) + 1];
struct ntt {
    ll rt[1 << MAX];
    void pre(int n) {
        rt[n / 2] = 1;
        rt[n / 2 + 1] = pwr(root, (mod - 1) / n);
        for(int i = n / 2 + 2; i < n; ++i)
            rt[i] = rt[i - 1] * rt[n / 2 + 1] % mod;
        for(int i = n / 2; --i; )
            rt[i] = rt[i << 1];
        iv[1] = 1;
        for(int i = 2; i <= (1 << MAX); ++i)
            iv[i] = mod - ((mod / i) * iv[mod % i]) % mod;
    }
    void go(vi &a) {
        int n = a.size();
        for(int i = 0, j = 0; i < n; ++i) {
            if(i > j)
                swap(a[i], a[j]);
            for(int k = n / 2; (j ^= k) < k; k >>= 1);
        }
        for(int st = 1; (st << 1) <= n; st <<= 1) {
            for(int i = 0; i < n; i += (st << 1)) {
                for(int j = i; j < i + st; ++j) {
                    int z = (rt[j - i + st] * a[j + st]) % mod;
                    a[j + st] = a[j] - z;
                    if(a[j + st] < 0)
                        a[j + st] += mod;
                    a[j] += z;
                    if(a[j] >= mod)
                        a[j] -= mod;
                }
            }
        }
    }
} nt;

