    int s = sz(v) + sz(w) - 1, t = 1;
    while(t < s)
        t <<= 1;
    v.resize(t, 0), w.resize(t, 0);
    nt.go(v), nt.go(w);
    ll I = iv[t];
    for(int i = 0; i < t; ++i)
        v[i] = (((v[i] * 1LL * w[i]) % mod) * I) % mod;
    reverse(v.begin() + 1, v.end());
    nt.go(v);
    while(!v.empty() && !v.back())
        v.pop_back();
    return v;
}

