inline void FFT(int *p,int n,int op)
{
	int l=0;
	while((1<<l)<n)l++;
	REP(i,1,n-1)rev[i]=(rev[i>>1]>>1)|((i&1)<<l-1);
	REP(i,1,n-1)if(i<rev[i])swap(p[i],p[rev[i]]);
	for(int i=1;i<n;i<<=1)
	{
		int w=power(5,(mod-1)/(i<<1));
		st[0]=1; REP(j,1,i-1)st[j]=(ll)st[j-1]*w%mod;
		for(int j=0;j<n;j+=i<<1)
			for(int k=0;k<i;k++)
			{
				int x=p[j+k],y=(ll)st[k]*p[i+j+k]%mod;
				p[j+k]=x+y; if(p[j+k]>=mod)p[j+k]-=mod;
				p[i+j+k]=x-y; if(p[i+j+k]<0)p[i+j+k]+=mod;
			}
	}
	if(op==-1)
	{
		int inv=power(n,mod-2);
		REP(i,0,n-1)p[i]=(ll)inv*p[i]%mod;
		reverse(p+1,p+n);
	}
}

