				int t=(w*1LL*a[j+k+(i>>1)])%mod;
				a[j+k+(i>>1)]=(((a[j+k]-t)%mod)+mod)%mod;
				a[j+k]=(a[j+k]+t)%mod;
				w=(w*1LL*wn)%mod;
			}
		}
	}
	if(flag)
	rep(i,0,len-1) a[i]=(a[i]*1LL*invn)%mod;
}
LL C(int n,int m){
	return (((fac[n]*1LL*inv[n-m])%mod)*1LL*inv[m])%mod;
