  for (int i=1;i<=n;++i) b[i]=inv[i]=K(jc[i]=jc[i-1]*i%mod);
  for (int i=0;i<=n;++i) a[i]=a[i]*jc[i]%mod;
  reverse(a,a+n+1);
  FFT::realmain(a,b,19);
