	for(int i=0;i<=n;i++) a[i]=1ll*c[i]*fac[i]%mod;
	for(int i=0;i<=n;i++) b[i]=inv[i];
	reverse(a,a+n+1);
	Mul(a,b,c,n+1,n+1);
	reverse(c,c+n+1);
	for(int i=1;i<=n;i++) f[i]=(f[i]-1ll*c[i]*inv[i]%mod+mod)%mod;
	memset(c,0,sizeof(c));
	for(int i=1;i<=n;i++) c[n-siz[i]]++;
	for(int i=0;i<=n;i++) a[i]=1ll*c[i]*fac[i]%mod;
