ll quick_pow(ll a,ll b){
	ll ans=1;
	for(;b;b>>=1,a=a*a%mod)
		if(b&1) ans=ans*a%mod;
	return ans;
}
void add(int x,int y){
	cnt++;
	e[cnt].k=y;
	e[cnt].next=home[x];
	home[x]=cnt;
}
int siz[N],m;
void dft(ll *a,int sig){
	for(int i=0;i<m;i++){
		int p=0,g=m>>1,j=i;
		while(g) p=p<<1|(j&1),g>>=1,j>>=1;
		if(p<i) swap(a[p],a[i]);
	}
	ll w,wn;
	for(int b=2;b<=m;b<<=1){
		wn=quick_pow(5,sig==1?(mod-1)/b:mod-1-(mod-1)/b);
		int half=b>>1;
		for(int i=0;i<m;i+=b){
			w=1;
			for(int j=0;j<half;j++){
				ll u=a[i+j],v=a[i+j+half]*w%mod;
				a[i+j]=(u+v)%mod;
				a[i+j+half]=(u-v)%mod;
				w=w*wn%mod;
			}
		}
	}
	ll inv=quick_pow(m,mod-2);
	if(sig==-1) for(int i=0;i<m;i++) a[i]=a[i]*inv%mod;
}
void dfs(int k,int F){
	siz[k]=1;
	for(int i=home[k];~i;i=e[i].next){
		if(e[i].k!=F){
			dfs(e[i].k,k);
			siz[k]+=siz[e[i].k];
		}
	}
	num[siz[k]]--;
	num[n-siz[k]]--;
}
