const int mod=998244353;
int KSM(int x,int k)
{
	int tmp=1,y=x;
	for(int i=k;i;i>>=1,y=1ll*y*y%mod)if(i&1)tmp=1ll*tmp*y%mod;
	return tmp;
}
void Add(int &x,int y){x+=y-mod;x+=x>>31&mod;}
void dec(int &x,int y){x-=y;x+=x>>31&mod;}
