			{
//				cout<<i<<' '<<k<<'\n';
				int t0=a[k],t1=1ll*x*a[k+(1<<m)]%mod;
				Add(a[k],t1);fix(a[k+(1<<m)]=t0-t1);
			}
	}
	if(d==-1){int x=KSM(1<<n,mod-2);FOR(i,0,(1<<n)-1)a[i]=1ll*a[i]*x%mod;}
