const int L=1<<19|1,mod=924844033;
int a[L],b[L];
inline int mu(ri x,ri y){
	rll s=(ll)x*y;
	return s>=mod?s%mod:s;
}
inline int fpow(ri a,ri b){
	ri ans=1;
	for(;b;b>>=1,a=mu(a,a))
		if(b&1) ans=mu(ans,a);
	return ans;
}
namespace ntt{ // by NaCly_Fish	
	int rt[L],rev[L],lim,l;

	inline void init(ri n){
	    ri w,i;
		lim=1;l=0;
	    while(lim<=n) lim<<=1,++l;
	    w=fpow(5,mod-1>>l);
	    rt[lim>>1]=1;
	    for(i=(lim>>1)+1;i^lim;++i) rt[i]=mu(rt[i-1],w);
	    for(i=(lim>>1)-1;i>0;--i) rt[i]=rt[i<<1];
	    for(i=1;i^lim;++i) rev[i]=rev[i>>1]>>1|(i&1)<<l-1;
	}

	inline void transform(int *f,ri lim,ri type){
	    if(type==-1) reverse(f+1,f+lim);
	    static unsigned long long a[L];
	    ri x,shift=l-__builtin_ctz(lim),i,mid,j,k;
	    for(i=0;i^lim;++i) a[rev[i]>>shift]=f[i];
	    for(mid=1;mid^lim;mid<<=1)
	        for(j=0;j^lim;j+=mid<<1)
	            for(k=0;k^mid;++k)
	                x=a[j|k|mid]*rt[mid|k]%mod,
	                a[j|k|mid]=a[j|k]-x+mod,
	                a[j|k]+=x;
	    for(i=0;i^lim;++i) f[i]=a[i]>=mod?a[i]%mod:a[i];
	    if(type==1) return;
	    x=fpow(lim,mod-2);
	    for(i=0;i^lim;++i) f[i]=mu(f[i],x);
