void Add(int x,int y)
{
	cur++;
	e[cur].obj=y;
	e[cur].Next=head[x];
	head[x]=e+cur;
}

void Dfs(int node)
{
	Size[node]=1;
	for (edge *p=head[node]; p; p=p->Next)
	{
		int son=p->obj;
		if (son==fa[node]) continue;
		fa[son]=node;
		Dfs(son);
		Size[node]+=Size[son];
		num[ Size[son] ]++;
	}
	num[ n-Size[node] ]++;
}

LL Pow(LL x,LL y)
{
	if (!y) return 1;
	LL temp=Pow(x,y>>1);
	temp=temp*temp%M;
	if (y&1) temp=temp*x%M;
	return temp;
}

void DFT(LL *a,int f)
{
	for (int i=0; i<N; i++)
		if (i<Rev[i]) swap(a[i],a[ Rev[i] ]);

	for (int len=2; len<=N; len<<=1)
	{
		int mid=(len>>1);
		LL e=Pow(g,(M-1)/len);
		if (f==-1) e=Pow(e,M-2);

		for (LL *p=a; p!=a+N; p+=len)
		{
			LL wn=1;
			for (int i=0; i<mid; i++)
			{
				LL temp=wn*p[mid+i]%M;
				p[mid+i]=(p[i]-temp+M)%M;
				p[i]=(p[i]+temp)%M;
				wn=wn*e%M;
			}
		}
	}
}

void NTT()
{
	N=1,Lg=0;
	while (N<2*n+2) N<<=1,Lg++;
	for (int i=0; i<N; i++)
		for (int j=0; j<Lg; j++)
			if (i&(1<<j)) Rev[i]|=(1<<(Lg-j-1));

	DFT(A,1);
	DFT(B,1);
	for (int i=0; i<N; i++) A[i]=A[i]*B[i]%M;
	DFT(A,-1);

	LL inv=Pow(N,M-2);
	for (int i=0; i<N; i++) A[i]=A[i]*inv%M;
}

