    while(b) {
        if(b & 1) c = 1ll * c * a % mod;
        a = 1ll * a * a % mod;
        b >>= 1;
    } return c;
}
void NTT(int * a, int len, int op) {
    for(int i = 0; i < len; ++i)
        if(i < pos[i]) swap(a[i], a[pos[i]]);
    for(int i = 1; i < len; i <<= 1) {
        int s = i << 1;
        int wn = qpow(g, (mod - 1) / s);
        if(op == -1) wn = qpow(wn, mod - 2);
        for(int j = 0; j < len; j += s) {
            int w = 1;
            for(int k = 0; k < i; ++k, w = 1ll * w * wn % mod) {
                int x = a[k + j];
                int y = 1ll * w * a[i + j + k] % mod;
                a[k + j] = (x + y) % mod;
                a[i + k + j] = (x - y + mod) % mod;
            }
        }
    }
    if(op == -1) {
        int inv = qpow(len, mod - 2);
        for(int i = 0; i < len; ++i) 
