}

void DFT(poly &p, int n) {
	if (n == 1) return;
	int Hn = n>>1;
	poly p0(Hn), p1(Hn);
	for (int k = 0; k < Hn; k++) {
		p0[k] = p[k<<1];
		p1[k] = p[(k<<1)|1];
	}

	DFT(p0, Hn);
	DFT(p1, Hn);
	int dif = L/n;
	if( dir ){
		for (int i = 0, j = Hn, k = 0; k < HL; k += dif, i++, j++) {
			p[i] = (p0[i] + w[k] * p1[i]) % MM;
			p[j] = (p0[i] + MM - w[k] * p1[i]%MM) % MM;
		}
	}
	else{
		for (int i = 0, j = Hn, k = L; k > HL; k -= dif, i++, j++) {
			p[i] = (p0[i] + w[k] * p1[i]) % MM;
			p[j] = (p0[i] + MM - w[k] * p1[i]%MM) % MM;
		}
	}
}

void poly_multi(poly X, poly Y, poly &Z)
{
	dir = true; DFT(X, L); DFT(Y, L);
	for(int i = 0; i < L; i++)
		Z[i] = (ll)X[i] * Y[i] % MM;
	dir = false; DFT(Z, L);
	for(int i = 0; i < L; i++) Z[i] = Z[i] * 924842269ll % MM;
}

