const int N=4e5+5,mo=924844033,FFTN=1<<19;
int W[N],w[N],p[N];
poly R;
int ksm(int x,int p){
	int res=1;
	for(;p;p>>=1,x=(ll)x*x%mo){
		if(p&1) res=(ll)res*x%mo;
	}
	return res;
}
void FFTinit(){
	W[0]=1;W[1]=ksm(5,(mo-1)/FFTN);
	For(i,2,N-1) W[i]=(ll)W[i-1]*W[1]%mo;
}
int FFTinit(int n){
	int L=1;for(;L<=n;L<<=1);R.resize(L);
	For(i,0,L-1) R[i]=(R[i>>1]>>1)|((i&1)?(L>>1):0);
	return L;
}
void DFT(poly &a,int n){
	a.resize(n);For(i,0,n-1) p[R[i]]=a[i];
	for(int d=1;d<n;d<<=1){
		int len=FFTN/(d<<1);
		for(int i=0,j=0;i<d;i++,j+=len) w[i]=W[j];
		for(int i=0;i<n;i+=(d<<1)){
			For(j,0,d-1){
				int y=(ll)w[j]*p[i+j+d]%mo;
				p[i+j+d]=(p[i+j]-y+mo)%mo;
				p[i+j]=(p[i+j]+y)%mo;
			}
		}
	}
	For(i,0,n-1) a[i]=p[i];
}
void IDFT(poly &a,int n){
	DFT(a,n);reverse(a.begin()+1,a.end());
	int inv=ksm(n,mo-2);
	For(i,0,n-1) a[i]=(ll)a[i]*inv%mo;
}
