const ll p=924844033,r=5;

ll Pow(ll n,ll m){
	ll res=1;
	while(m>0){
		if(m&1) (res*=n)%=p;
		(n*=n)%=p;
		m>>=1;
	}
	return res;
}

ll Inv(ll x){return Pow(x,p-2);}

void ntt(vi& a,bool B){
	int n=a.size(),h=0;
	while(1<<h<n) h++;
	for(int i=0;i<n;i++){
		int j=0;
		for(int k=0;k<h;k++) if(i&1<<k) j+=1<<(h-k-1);
		if(i<j) swap(a[i],a[j]);
	}
	for(int i=1;i<n;i*=2){
		ll w=Pow(r,(p-1)/(i*2));
		if(B) w=Inv(w);
		for(int j=0;j<n;j+=i*2){
			ll wn=1;
			for(int k=0;k<i;k++){
				ll s=a[j+k],t=a[i+j+k]*wn%p;
				a[j+k]=(s+t)%p;
				a[i+j+k]=(s-t+p)%p;
				(wn*=w)%=p;
			}
		}
	}
	if(B){
		ll v=Inv(n);
		for(int i=0;i<n;i++) (a[i]*=v)%=p;
	}
}

vi Conv(vi a,vi b){
	int s=a.size()+b.size()-1,t=1;
	while(t<s) t*=2;
	a.resize(t);
	b.resize(t);
	ntt(a,0);ntt(b,0);
	for(int i=0;i<t;i++) (a[i]*=b[i])%=p;
	ntt(a,1);
	a.resize(s);
	return a;
}
