int rev[1<<20];
void NTT(int *p,int len,int type)
{
	For(i,0,len-1)if(i<rev[i])swap(p[i],p[rev[i]]);
	int tim,wn,X;
	for(int i=2;i<=len;i<<=1)
	{
		tim=i>>1;
		wn=power(5,(mo-1)/i);
		if(type==-1)wn=power(wn,mo-2);
		for(int j=0;j<len;j+=i)
		{
			X=1;
			for(int k=0;k<tim;k++,X=1ll*X*wn%mo)
			{
				int u=p[j+k],v=1ll*p[j+k+tim]*X%mo;
				p[j+k]=(u+v)%mo;
				p[j+k+tim]=(u-v+mo)%mo;
			}
		}
	}
	if(type==-1)
	{
		int inv=power(len,mo-2);
		For(i,0,len-1)p[i]=1ll*p[i]*inv%mo;
	}
}
