	For(i,0,n)g[i]=1ll*g[i]*mc[i]%mo;
	For(i,0,n)f[i]=inv[n-i];
	int len=1,cnt=0;
	for(;len<=n*2;len<<=1)cnt++;
	For(i,0,len)rev[i]=(rev[i>>1]>>1)|(i&1)<<(cnt-1);
	NTT(g,len,1),NTT(f,len,1);
	For(i,0,len)g[i]=1ll*g[i]*f[i]%mo;
	NTT(g,len,-1);
	//For(i,1,n)cout<<g[i+n]<<endl;
	For(i,1,n)ans[i]=1ll*g[n+i]*inv[i]%mo;
	For(i,1,n)write(ans[i],'\n');
}
