inline void GetC() {
	Jc[0] = Inv[0] = 1 ;
	for(register long long i = 1 ; i <= N ; ++i )
		Jc[i] = Jc[i-1] * i % Mod ;
	Inv[N] = Pow( Jc[N] , Mod - 2 ) ; 
	for(register long long i = N ; --i ; )
		Inv[i] = Inv[i+1] * (i+1) % Mod ;
}
