int rev[1<<19|1];

inline int power(int a, int n)
{
	int ans = 1;
	for (; n; n >>= 1) {
		if (n&1) ans = (long long)ans*a%mod;
		a = (long long)a*a%mod;
	}
	return ans;
}

inline int inv(int a)
{ return power(a, mod-2); }

void NTT(int a[], int n, int lgn, int flag)
{
	for (int i = 1; i < n; i++) rev[i] = ((rev[i>>1]>>1)|((i&1)<<(lgn-1)));
	for (int i = 1; i < n; i++)
		if (rev[i] < i)
			swap(a[i], a[rev[i]]);
	for (int k = 2; k <= n; k <<= 1) {
		int dw = power(g, (mod-1)/k);
		if (flag == -1) dw = inv(dw);
		for (int i = 0; i < n; i += k) {
			int w = 1, u, v;
			for (int j = 0; j < k>>1; j++) {
				u = a[i+j], v = (long long)w*a[i+j+(k>>1)]%mod;
				a[i+j] = (u+v)%mod, a[i+j+(k>>1)] = ((u-v)%mod+mod)%mod;
				w = (long long)w*dw%mod;
			}
		}
	}
	if (flag == -1) {
		int invn = inv(n);
		for (int i = 0; i < n; i++)
			a[i] = (long long)a[i]*invn%mod;
	}
}

