		int to = edge[i].to;
		if (to == f) continue;
		dfs(to, nd), siz[nd] += siz[to];
	}
	if (nd != 1) a[siz[nd]]++;
	b[n-siz[nd]]++;
}

int fac[MAXN], ifac[MAXN], inv_num[MAXN];

