}E[N << 1];

void add_edge(int u, int v)
{
	E[++e] = Edge(v, Begin[u]), Begin[u] = e;
	E[++e] = Edge(u, Begin[v]), Begin[v] = e;
}

//NTT
int rev[N << 2], Len, bit_cnt;

int fpm(int x, int e)
{
	int res = 1;
	for(; e; e >>= 1){
		if(e & 1) res = (LL)res * x % mod;
		x = (LL)x * x % mod;
	}
	return res;
}

void NTT(int *p, int n, int f)
{
	REP(i, n) if(i < rev[i]){
		std::swap(p[i], p[rev[i]]);
	}

	for(int step = 1; step < n; step <<= 1){
		int w = fpm(G0, (mod-1)/(step<<1));
		if(f) w = fpm(w, mod - 2);

		for(int i = 0; i < n; i += step << 1){
			int e = 1;

			for(int j = i; j < i + step; ++j){
				int u = (LL)p[j + step] * e % mod;
				p[j + step] = (p[j] - u + mod) % mod;
				p[j] = (p[j] + u) % mod;
				e = (LL)e * w % mod;
			}
		}
	}

	if(f){
		REP(i, n)
			p[i] = (LL)p[i] * fpm(n, mod - 2) % mod;
	}

	return ;
}

int size[N], A[N << 2], B[N << 2];

void Addcon(int o, int f)
{
	A[o] += f;
	if(A[o] < 0) A[o] += mod;
	if(A[o] >= mod) A[o] -= mod;
}

void dfs_Modulus(int u, int fa)
{
	Addcon(n, +1);
	size[u] = 1;

	for(int i = Begin[u]; i; i = E[i].next){
		int v = E[i].to;
		if(v == fa) continue;
		dfs_Modulus(v, u);
		size[u] += size[v];

		Addcon(size[v], -1);
	}

	Addcon(n-size[u], -1);
}

void Init()
{
	read(n);
	for(int i = 1; i < n; ++i){
		int u, v; 
		read(u), read(v);
		add_edge(u, v);
	}

	bit_cnt = 0;
	Len = 1; 
	for(; Len <= n + n; Len <<= 1, ++bit_cnt) {}

	REP(i, Len){
		rev[i] = (rev[i>>1] >> 1) | ((i&1) << (bit_cnt-1));
	}

	return ;
}

void Work()
{
	dfs_Modulus(1, 0);

	int fac = 1;
	for(int i = 1; i <= n; ++i){
		fac = (LL)fac * i % mod;
		A[i] = (LL)A[i] * fac % mod;
	}
	fac = 1;
	for(int i = 0; i < n; ++i){
		if(i) fac = (LL)fac * i % mod;
		B[n - i] = fpm(fac, mod - 2);
	}

	NTT(A, Len, 0), NTT(B, Len, 0);
	REP(i, Len) A[i] = (LL)A[i] * B[i] % mod;
	NTT(A, Len, 1);

	fac = 1;
	for(int i = 1; i <= n; ++i){
		fac = (LL)fac * i % mod;
		printf("%lld\n", (LL)A[n + i] * fpm(fac, mod-2) % mod);
	}

	return ;
}

