  fact[0] = 1;
  for(int i = 1; i <= n; i++){
    fact[i] = mul(fact[i-1], i);
  }
  ifact[n] = inv(fact[n]);
  for(int i = n-1; i >= 0; i--){
    ifact[i] = mul(ifact[i+1], i+1);
  }
}

