    for (int i = 2; i <= n; ++i)
        sub.app(cnt[i]);

    prec();

    for (int k = 1; k <= n; k++) {
        M ans = C(n, k) * n;
        for (int x : sub) {
            ans -= C(x, k);
            ans -= C(n - x, k);                                                    
        }
        cout << ans.x << endl;  
    }   
}

