const int SZ = (1 << LOG);
int rev[SZ];
int w[SZ];

void initRev()
{
    for (int i = 1; i < SZ; i++)
    {
        int j = 0;
        while ((i & (1 << j)) == 0)
            j++;
        rev[i] = rev[i ^ (1 << j)] ^ (1 << (LOG - 1 - j));
    }
}

void init()
{
    initRev();

    int alpha = 2;
    int r = MOD - 1;
    while (r % 2 == 0)
         r >>= 1;

    while (fpow(alpha, (MOD - 1) / r) == 1 || fpow(alpha, (MOD - 1) / 2) == 1)
        alpha++;
    alpha = fpow(alpha, (MOD - 1) / (1 << LOG));

    w[0] = 1;
    for (int i = 1; i < SZ; i++)
        w[i] = mul(w[i - 1], alpha);
}


int _a[2][SZ];
void fft(int a[SZ])
{
    int t = 0, nt = 1;
    for (int i = 0; i < SZ; i++)
        _a[t][i] = a[rev[i]];

    for (int hlog = 0; (2 << hlog) <= SZ; hlog++)
    {
        //eprintf("hlog = %d\n", hlog);
        int hlen = (1 << hlog);
        for (int i = 0; i < SZ; i += 2 * hlen)
            for (int j = 0; j < hlen; j++)
            {
                int x = _a[t][i + j];
                int y = _a[t][i + j + hlen];
                _a[nt][i + j] = add(x, mul(y, w[j << (LOG - hlog - 1)]));
                _a[nt][i + j + hlen] = add(x, mul(y, w[(hlen + j) << (LOG - hlog - 1)]));
            }
        swap(t, nt);
    }
    for (int i = 0; i < SZ; i++)
        a[i] = _a[t][i];
}

