constexpr ll mod = 924844033;
vector<ll> fac, inv, facinv;

void modcalc(int modsize) {
	fac.resize(modsize); inv.resize(modsize); facinv.resize(modsize);
	fac[0] = 1; fac[1] = 1; inv[1] = 1;
	facinv[0] = 1; facinv[1] = 1;
	for (ll i = 2; i < modsize; i++) {
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;
		facinv[i] = facinv[i - 1] * inv[i] % mod;
	}
}

ll modinv(ll a) {
	a %= mod;
	if (a == 0) abort();
	if (a < (ll)inv.size()) return inv[a];
	ll b = mod, u = 1, v = 0;
	while (b) {
		ll t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= mod;
	if (u < 0) u += mod;
	return u;
}

ll modpow(ll a, ll b, ll m = mod) {
	ll ans = 1;
	a %= m;
	while (b) {
		if (b & 1) ans = ans * a % m;
		a = a * a % m;
		b >>= 1;
	}
	return ans;
}

ll modcomb(ll n, ll k) {
	if (n < 0 || k < 0 || n < k) return 0;
	return fac[n] * facinv[k] % mod * facinv[n - k] % mod;
}

ll modperm(ll n, ll k) {
	if (n < 0 || k < 0 || n < k) return 0;
	return fac[n] * facinv[n - k] % mod;
}

ll modhom(ll n, ll k) {
	if (n < 0 || k < 0 || n == 0 && k > 0) return 0;
	if (n == 0 && k == 0) return 1;
	return fac[n + k - 1] * facinv[k] % mod * facinv[n - 1] % mod;
}

constexpr ll root = 5;

void ntt(vector<ll> &f, bool inv) {
	int n = f.size();
	if (n == 1) return;
	ll h = modpow(root, (mod - 1) / n);
	if (inv) h = modinv(h);
	vector<ll> a, b;
	for (int i = 0; i < n / 2; i++) {
		a.push_back(f[i << 1]); 
		b.push_back(f[i << 1 | 1]);
	}
	ntt(a, inv); ntt(b, inv);
	ll base = 1; ll t = (n >> 1) - 1;
	for (int i = 0; i < n; i++) {
		f[i] = a[i & t] + base * b[i & t];
		f[i] %= mod;
		base = base * h % mod;
	}
}

vector<ll> convolution(vector<ll> f, vector<ll> g) {
	int n = 1;
	while (n < f.size() + g.size() + 2) n <<= 1;
	f.resize(n); g.resize(n);
	ntt(f, false); ntt(g, false);
	vector<ll> res(n);
	for (int i = 0; i < n; i++) res[i] = f[i] * g[i] % mod;
	ntt(res, true);
	ll inv = modinv(n);
	for (int i = 0; i < n; i++) res[i] = res[i] * inv % mod;
	return res;
}

