/*
For NTT, let p be modulo prime
p = 2^k * c + 1
need: size of polynom <= 2^k
find r so that r^1 .. r^p-1 distinct <- call prr

change for the following
int theta = expmod(prr, (MOD-1)/n); // expmod->exponent
if(sign == -1)theta = expmod(theta, MOD-2);
    w = expmod(theta, irev) // can be saved to array
don’t forget divmod and other mods
*/

const ll MOD = 924844033;
inline ll addmod(ll a, ll b){
    if(a+b<MOD)return a+b;
    return a+b-MOD;
}
inline ll submod(ll a, ll b){
    return addmod(a, MOD-b);
}
inline ll mulmod(ll a, ll b){
    return (a*b)%MOD;
}
inline ll expmod(ll a, ll e){
    ll ret = 1;
    while(e){
        if(e&1)ret = mulmod(ret, a);
        a = mulmod(a, a);
        e >>= 1;
    }
    return ret;
}
inline ll divmod(ll a, ll b){
    return mulmod(a, expmod(b, MOD-2));
}

const int prr = 5;
void FFT(vector<int>& a, int sign = 1) {
    int n = a.size(); // n should be a power of two
    int theta = expmod(prr, (MOD-1)/n);
    if(sign == -1)theta = expmod(theta, MOD-2);

    for(int i = 0, j = 1; j < n - 1; ++j) {
        for(int k = n >> 1; k > (i ^= k); k >>= 1);
        if(j < i) swap(a[i], a[j]);
    }
    for(int m, mh = 1; (m = mh << 1) <= n; mh = m) {
        int irev = 0;
        for(int i = 0; i < n; i += m) {
            int  w = expmod(theta, irev);
            for(int k = n >> 2; k > (irev ^= k); k >>= 1);
            for(int j = i; j < mh + i; ++j) {
                int k = addmod(j, mh);
                int x = submod(a[j], a[k]);
                a[j] = addmod(a[j], a[k]);
                a[k] = mulmod(w, x);
            }
        }
    }
    if(sign == -1) FOR(i,n)a[i] = divmod(a[i], n);
}

void vector_multiply(vector<int>& res, vector<int>& a, vector<int>& b){ // multiplies, stores to a
    res.clear();
    int n = a.size() + b.size() - 1;
    for(int i=1; i<n; i<<=1)if(n&i)n += i;
    a.resize(n);
    b.resize(n);

    FFT(a);
    FFT(b);
    FOR(i,n)res.pb(mulmod(a[i], b[i]));
    FFT(res, -1);
}

