int powM(int V,int T=MOD-2ll){
	int R=1;
	while(T){
		if(T&1) R=(LL)R*(LL)V%MOD;
		T>>=1;
		V=(LL)V*(LL)V%MOD;
	}
	return R;
}
void ntt(int *a,int l,bool r){
    int i,j=l/2,k;
    for(i=1;i<l;++i){
        if(i<j) swap(a[i],a[j]);
        for(k=l/2;j&k;k>>=1) j^=k;
        j^=k;
    }
    for(i=1;(1<<i)<=l;++i){
        int cl=(1<<i);
        int w=powM(G,(MOD-1)/cl);
        if(r) w=powM(w,MOD-2);
        for(j=0;j*cl<l;++j){
            int cur=1;
            for(k=0;k<(cl>>1);k++){
                int v1=a[j*cl+k],v2=((LL)a[j*cl+k+(cl>>1)]*(LL)cur)%MOD;
                a[j*cl+k]=(v1+v2)%MOD;
                a[j*cl+k+(cl>>1)]=(v1-v2+MOD)%MOD;
                cur=((LL)cur*(LL)w)%(LL)MOD;
            }
        }
    }
