int ksm(int x, int y)
{
    int ans=1;
    while(y)
    {
        if(y&1) ans=1LL*ans*x%p;
        x=1LL*x*x%p; y>>=1;
    }
    return ans;
}

void ntt(int a[], int n, int op)
{
    for(rint i=0; i<n; ++i)
        if(i<pos[i]) swap(a[i], a[pos[i]]);
    for(rint i=1; i<n; i<<=1)
    {
        int del=ksm(g, (op*(p-1)/(i<<1)+(p-1))%(p-1));
        for(rint j=0; j<n; j+=(i<<1))
        {
            int t=1;
            for(rint k=0; k<i; ++k, t=1LL*t*del%p)
            {
                int x=a[j+k], y=1LL*t*a[j+k+i]%p;
                a[j+k]=(x+y)%p, a[j+k+i]=(x-y+p)%p;
            }
        }
    }
    if(op==-1)
    {
        int INV=ksm(n, p-2);
        for(rint i=0; i<n; ++i) a[i]=1LL*a[i]*INV%p;
    }
}

