		fac[i]=1ll*fac[i-1]*i%mod;
	inv[lim]=qp(fac[lim],mod-2);
	for(int i=lim-1;i;i--)
		inv[i]=1ll*inv[i+1]*(i+1)%mod;
}
void ntt(int f[],int opt)
{
	for(int i=0;i<lim;i++)
		if(i<rev[i])
			swap(f[i],f[rev[i]]);
	for(int i=1;i<lim;i<<=1)
	{
		int tmp=i<<1;
		int w=qp(5,opt?(mod-1)/tmp:mod-1-(mod-1)/tmp);
		for(int j=0;j<lim;j+=tmp)
		{
			int wn=1;
			for(int k=0;k<i;k++,wn=1ll*w*wn%mod)
			{
				int x=1ll*wn*f[i+j+k]%mod;
				f[i+j+k]=(f[j+k]-x+mod)%mod;
				f[j+k]=(f[j+k]+x)%mod;
			}
		}
	}
	if(!opt)
	{
		int inv=qp(lim,mod-2);
		for(int i=0;i<lim;i++)
			f[i]=1ll*f[i]*inv%mod;
	}
}
