int dfs(int v, int prev) {
        int sum = 0;
        for (auto u : g[v]) if (u != prev) {
                int get = dfs(u, v);
                cnt[get] ++;
                sum += get;
        }
        cnt[n - 1 - sum] ++;
        return sum + 1;
}

void solve() {
        cin >> n;
