int w[N],R[N],A[N],B[N];
void FFT(int a[N],int n){
	for (int i=0;i<n;i++)
		if (R[i]<i)
			swap(a[i],a[R[i]]);
	for (int t=n>>1,d=1;d<n;d<<=1,t>>=1)
		for (int i=0;i<n;i+=(d<<1))
			for (int j=0;j<d;j++){
				int tmp=1LL*w[t*j]*a[i+j+d]%mod;
				a[i+j+d]=(a[i+j]-tmp+mod)%mod;
				a[i+j]=(a[i+j]+tmp)%mod;
			}
}
void Mul(){
	int m,d;
	for (d=0,m=1;m<n*2;m<<=1,d++);
	w[0]=1,w[1]=Pow(5,(mod-1)/m);
	for (int i=2;i<m;i++)
		w[i]=1LL*w[i-1]*w[1]%mod;
	for (int i=0;i<m;i++)
		R[i]=(R[i>>1]>>1)|((i&1)<<(d-1));
	FFT(A,m);
	FFT(B,m);
	for (int i=0;i<m;i++)
		A[i]=1LL*A[i]*B[i]%mod;
	w[1]=Pow(w[1],mod-2);
	for (int i=2;i<m;i++)
		w[i]=1LL*w[i-1]*w[1]%mod;
	FFT(A,m);
	int inv=Pow(m,mod-2);
	for (int i=0;i<m;i++)
		A[i]=1LL*A[i]*inv%mod;
}
