void dft(int *a,int n,int type)
{
	int wei=0; while ((1<<wei)!=n) wei++;
	for (int i=0;i<n;i++)
	{
		rev[i]=0;
		for (int j=0;j<wei;j++) rev[i]|=((i>>j)&1)<<(wei-j-1);
	}
	for (int i=0;i<n;i++) if (i<rev[i]) a[i]^=a[rev[i]]^=a[i]^=a[rev[i]];
	for (int i=1;i<n;i<<=1)
	{
		int t=powmod(G,(mod-1)/(i*2));
		if (type==-1) t=powmod(t,mod-2);
		for (int j=0,p=i<<1;j<n;j+=p)
		{
			int tmp=1;
			for (int k=0;k<i;k++,tmp=1ll*tmp*t%mod)
			{
				int now=1ll*tmp*a[j+k+i]%mod;
				a[j+k+i]=(a[j+k]+mod-now)%mod;
				a[j+k]=(a[j+k]+now)%mod;
			}
		}
	}
	if (type==-1)
	{
		int ni=powmod(n,mod-2);
		for (int i=0;i<n;i++) a[i]=1ll*a[i]*ni%mod;
	}
