inline int add(int x,int y){
	if(x + y < mod) return x + y;
	else return x + y - mod;
}
inline int dec(int x,int y){
	if(x - y >= 0) return x - y;
	else return x - y + mod;
}
int qpow(int x,int k){
	int d = 1,t = x;
	while(k){
		if(k & 1) d = 1ll * d * t % mod;
		t = 1ll * t * t % mod,k >>= 1;
	}
	return d;
}
void NTT_init(int n){
	N = 1;
	int cnt = 0;
	while(N <= n) N <<= 1,cnt ++;
	for(int i = 0; i < N; i ++) rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (cnt - 1));
}
void NTT(int *F,int n,int p){
	for(int i = 0; i < n; i ++) if(i < rev[i]) swap(F[i],F[rev[i]]);
	int cnt = 1;
	for(int i = 1; i < n; i <<= 1){
		int w1 = (p == 1 ? W[cnt] : inv_W[cnt]);
		for(int j = 0; j < n; j += i << 1){
			int w = 1;
			for(int k = j; k < j + i; k ++){
				int t1 = F[k],t2 = 1ll * w * F[k + i] % mod;
				F[k] = add(t1,t2),F[k + i] = dec(t1,t2);
				w = 1ll * w * w1 % mod;
			}
		}
		cnt ++;
	}
	if(p == -1) for(int i = 0; i < n; i ++) F[i] = 1ll * F[i] * inv[cnt - 1] % mod;
}
void Mul(int *F,int *G,int n){
	NTT_init(n << 1);
