namespace NTT{
	inline int powmod(LL x, int y){
		LL ret=1;
		while(y){
			if(y&1){
				if(MOD<=(ret*=x)) ret%=MOD;
			}
			y>>=1;
			if(MOD<=(x*=x)) x%=MOD;
		}
		return int(ret);
	}
	inline int inverse(int x){
		return powmod(x, MOD - 2);
	}
	void NFT(int P[], int n, int oper) {
		for (int i = 1, j = 0; i < n - 1; ++i) {
			for (int s = n; j ^= s >>= 1, ~j & s;);
			if (i < j) {
				swap(P[i], P[j]);
			}
		}
		for (int d = 0; (1 << d) < n; ++d) {
			int m = 1 << d, m2 = m * 2;
			int unit_p0 = powmod(R, (MOD - 1) / m2);
			if (oper < 0) {
				unit_p0 = inverse(unit_p0); 
			}
			for (int i = 0; i < n; i += m2) {
				int unit = 1;
				for (int j = 0; j < m; ++j) {
					int &P1 = P[i + j + m], 
						&P2 = P[i + j];
					int t = (long long)unit * P1 % MOD;
					P1 = (P2 - t + MOD) % MOD;
					P2 = (P2 + t) % MOD;
					unit = (long long)unit * unit_p0 % MOD;
				}
			}
		}
	}
	int A[MAXN],B[MAXN];
	void NTT(int FA[],int FB[],int len){
		int N=1;
		while(N<len*2){
			N<<=1;
		}
		for(int i=0;i<len;++i){
			A[i]=FA[i];
			B[i]=FB[i];
		}
		for(int i=len;i<N;++i){
			A[i]=B[i]=0;
		}
		NFT(A,N,1);
		NFT(B,N,1);
		for(int i=0;i<N;++i) A[i]=1LL*A[i]*B[i]%MOD;
		NFT(A,N,-1);
		long long tmp=inverse(N);
		for(int i=0;i<N;++i){
			FA[i]=A[i]*tmp%MOD;
		}
	}
}
