	int inv_mod(int a, int b) {
		if (a == 1) return b;
		int div = mmod / a + 1;
		return inv_mod((a * (long long)div) % mmod, (b * (long long)div) % mmod);
	}

void go(int now, int prv) {
  sz[now] = 1;
  parent[now] = prv;
  for (int i=0; i<G[now].size(); i++) {
    if (prv == G[now][i]) continue;
    go(G[now][i], now);
    sz[now] += sz[G[now][i]];
  }
//  printf("sz[%d] = %d %d\n", now, sz[now], parent[now]);
}

long long combi(int a, int b) {
  if (b < 0 || b > a) return 0;
  long long res = fac[a];
  res = (res * inv_fac[b]) % mmod;
  res = (res * inv_fac[a-b]) % mmod;
  return res;
}

long long partial_combi(int a, int b) {
  if (b < 0 || b > a) return 0;
  long long res = fac[a];
//  res = (res * inv_fac[b]) % mmod;
  res = (res * inv_fac[a-b]) % mmod;
  return res;
}

