struct NTT{
	LL a[M],b[M],c[M],bitrev[M],m,g[M],ng[M];
	LL qmod(LL a,LL b)
	{
		LL t=1;
		while(b)
		{
			if(b%2) t=1ll*t*a%mmod;
			b/=2;
			a=1ll*a*a%mmod;
		}
		return t;
	}
	void ntt_pre(LL n)
	{
		LL len=0;
		while((1<<len)<n) len++;
		len--;
		for(LL i=0;i<n;i++)
		{
			LL k=0;
			for(LL j=0;j<=len;j++) if(i&(1<<j)) k|=1<<(len-j);
			bitrev[i]=k;
		}
	}
	void ntt(LL *x,LL n,LL o)
	{
		for(LL i=0;i<n;i++) if(i>bitrev[i]) swap(x[i],x[bitrev[i]]);
		for(LL s=2;s<=n;s*=2)
		{
			if(o==1 && g[s]==0) g[s]=qmod(grt,(mmod-1)/s);
			if(o==-1 && ng[s]==0) ng[s]=qmod(grt,mmod-1-(mmod-1)/s);
			LL wn;
			if(o==1) wn=g[s];
			else wn=ng[s];
			for(LL i=0;i<n;i+=s)
			{
				LL w=1;
				for(LL j=0;j<s/2;j++)
				{
					LL t1=x[i+j],t2=1ll*w*x[i+j+s/2]%mmod;
					x[i+j]=(t1+t2)%mmod;
					x[i+j+s/2]=(t1-t2)%mmod;
					w=1ll*w*wn%mmod;
				}
			}
		}
	}
	void work()
	{
		m*=2;
		LL n=1;
		while(n-1<m) n*=2;
		ntt_pre(n);
		ntt(a,n,1);ntt(b,n,1);
		for(LL i=0;i<n;i++) c[i]=1ll*a[i]*b[i]%mmod;
		ntt(c,n,-1);
		LL ny=qmod(n,mmod-2);
		for(LL i=0;i<n;i++) c[i]=1ll*c[i]*ny%mmod;
		LL oo=1;
	}
}g;
