    for (int i=0; i<=n; i++) {
        if(con[i] < 0)  con[i] += M;
        a[i] = (1LL*con[i]*fac[i])%M;
        b[i] = invfac[i];
    }
    reverse(b.begin(), b.end());

    vector<int> mul = NTT::multiply(a, b);
    for (int i=1; i<=n; i++) {
        int ans = mul[n+i];
        ans = (1LL*ans*invfac[i])%M;
        ans = (ans + C(n, i))%M;
        cout<<ans<<"\n";
    }

}

