	for (int i = 2, p = 1; i <= n; p = i, i <<= 1) {
		int wn = ty == 1 ? powg[i] : ipowg[i];
		for (int j = 0; j < n; j += i) {
			int w = 1;
			Rep(k, p) {
				int x = a[j + k], y = (LL)a[j + k + p] * w % MOD;
				a[j + k] = add(x, y), a[j + k + p] = sub(x, y);
				w = (LL)w * wn % MOD;
			}
		}
	}
	if (ty == -1) {
		int inv = fpm(n);
		Rep(i, n) a[i] = (LL)a[i] * inv % MOD;
	}
}

int n;

int beg[MAXN], v[MAXN << 1], nex[MAXN << 1], e = 1;
void addedge(int uu, int vv) {
	v[++ e] = vv, nex[e] = beg[uu], beg[uu] = e;
}

int b[MAXN];
int getsize(int u, int pa) {
	int sz = 1;
	for (int i = beg[u]; i; i = nex[i])
		if (v[i] != pa) sz += getsize(v[i], u);
	if (pa) -- b[sz], -- b[n - sz];
	return sz;
}

int fac[MAXN], ifac[MAXN];
void getfactorial() {
	fac[0] = 1;
	For(i, 1, n) fac[i] = (LL)fac[i - 1] * i % MOD;
	ifac[n] = fpm(fac[n]);
	Fordown(i, n, 1) ifac[i - 1] = (LL)ifac[i] * i % MOD;
}

void initialize() {
	For(i, 2, n = read<int>()) {
		int u = read<int>(), v = read<int>();
		addedge(u, v), addedge(v, u);
	}
	getsize(1, 0), b[n] = n;
	getfactorial();
}

int f[MAXN << 2], g[MAXN << 2];
void solve() {
	For(i, 0, n) {
		f[i] = (LL)add(b[i], MOD) * fac[i] % MOD;
		g[n - i] = ifac[i];
	}
	int N, pt;
	for (N = 1, pt = 0; N <= (n << 1); ++ pt, N <<= 1);
	ig0 = fpm(g0);
	For(i, 1, pt) {
		powg[1 << i] = fpm(g0, (MOD - 1) >> i);
		ipowg[1 << i] = fpm(ig0, (MOD - 1) >> i);
	}
	Rep(i, N) rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (pt - 1));
	NTT(f, N, 1), NTT(g, N, 1);
	Rep(i, N) f[i] = (LL)f[i] * g[i] % MOD;
	NTT(f, N, -1);
	For(i, 1, n) printf("%lld\n", (LL)f[i + n] * ifac[i] % MOD);
}

int main() {
