int qpow(int x,int y)
{
	int ret=1;
	while(y)
	{
		if(y&1)ret=(ll)ret*x%mod;
		x=(ll)x*x%mod;y>>=1;
	}
	return ret;
}
void init()
{
	jc[0]=njc[0]=1;
	for(int i=1;i<=n;i++)jc[i]=(ll)jc[i-1]*i%mod;
	njc[n]=qpow(jc[n],mod-2);
	for(int i=n-1;i>=1;i--)njc[i]=(ll)njc[i+1]*(i+1)%mod;
	for(len=1;len<(n+1)*2;len<<=1);
}
