using namespace std;
typedef long long ll;
typedef double db;
const db pi=acos(-1);
const int maxn=2000000+10,mo=924844033,smo=floor(sqrt(mo));
struct node{
	db x,y;
	friend node operator +(node a,node b){
		node c;
		c.x=a.x+b.x;
		c.y=a.y+b.y;
		return c;
	}
	friend node operator -(node a,node b){
		node c;
		c.x=a.x-b.x;
		c.y=a.y-b.y;
		return c;
	}
	friend node operator *(node a,node b){
		node c;
		c.x=a.x*b.x-a.y*b.y;
		c.y=a.x*b.y+a.y*b.x;
		return c;
	}
};
node a[maxn],b[maxn],a1[maxn],a2[maxn],b1[maxn],b2[maxn],c[maxn],tt[maxn],w[maxn];
int rev[maxn],ans[maxn],sta[maxn],fac[maxn],inv[maxn];
int h[maxn],go[maxn*2],nxt[maxn*2],size[maxn];
int i,j,k,l,t,n,m,tot,top,len;
db ce;
int read(){
	int x=0,f=1;
	char ch=getchar();
	while (ch<'0'||ch>'9'){
		if (ch=='-') f=-1;
		ch=getchar();
	}
	while (ch>='0'&&ch<='9'){
		x=x*10+ch-'0';
		ch=getchar();
	}
	return x*f;
}
void add(int x,int y){
	go[++tot]=y;
	nxt[tot]=h[x];
	h[x]=tot;
}
int qsm(int x,int y){
	if (!y) return 1;
	int t=qsm(x,y/2);
	t=(ll)t*t%mo;
	if (y%2) t=(ll)t*x%mo;
	return t;
}
void dfs(int x,int y){
	int t=h[x];
	while (t){
		if (go[t]!=y){
			dfs(go[t],x);
			a[size[go[t]]].x--;
			size[x]+=size[go[t]];
		}
		t=nxt[t];
	}
	size[x]++;
	a[n-size[x]].x--;
	a[n].x++;
}
void prepare(){
	fo(i,0,len-1){
		int p=0;
		for(int j=0,tp=i;j<ce;j++,tp/=2) p=(p<<1)+(tp%2);
		rev[i]=p;
	}
	w[0].x=1;w[0].y=0;
	w[1].x=cos(2*pi/len);w[1].y=sin(2*pi/len);
	fo(i,2,len) w[i]=w[i-1]*w[1];
}
void DFT(node *a,int sig){
	int i;
	fo(i,0,len-1) tt[rev[i]]=a[i];
	for(int m=2;m<=len;m*=2){
		int half=m/2,bei=len/m;
		fo(i,0,half-1){
			node wi=sig>0?w[i*bei]:w[len-i*bei];
			for(int j=i;j<len;j+=m){
				node u=tt[j],v=tt[j+half]*wi;
				tt[j]=u+v;
				tt[j+half]=u-v;
			}
		}
	}
	if (sig==-1)
		fo(i,0,len-1) tt[i].x/=len;
	fo(i,0,len-1) a[i]=tt[i];
}
void FFT(){
	fo(i,0,len-1){
		t=int(a[i].x);
		a1[i].x=t/smo;
		a2[i].x=t%smo;
		t=int(b[i].x);
		b1[i].x=t/smo;
		b2[i].x=t%smo;
	}
	DFT(a1,1);DFT(a2,1);
	DFT(b1,1);DFT(b2,1);
	fo(i,0,len-1) c[i]=a1[i]*b1[i];
	DFT(c,-1);
	t=(ll)smo*smo%mo;
	fo(i,n+1,2*n) (ans[i-n]+=(ll)round(c[i].x)*t%mo)%=mo;
	fo(i,0,len-1) c[i]=a1[i]*b2[i];
	DFT(c,-1);
	t=smo;
	fo(i,n+1,2*n) (ans[i-n]+=(ll)round(c[i].x)*t%mo)%=mo;
	fo(i,0,len-1) c[i]=a2[i]*b1[i];
	DFT(c,-1);
	t=smo;
	fo(i,n+1,2*n) (ans[i-n]+=(ll)round(c[i].x)*t%mo)%=mo;
	fo(i,0,len-1) c[i]=a2[i]*b2[i];
	DFT(c,-1);
	t=1;
	fo(i,n+1,2*n) (ans[i-n]+=(ll)round(c[i].x)*t%mo)%=mo;
}
void write(int x){
	if (!x){
		putchar('0');
		putchar('\n');
		return;
	}
	top=0;
	while (x){
		sta[++top]=x%10;
		x/=10;
	}
	while (top){
		putchar('0'+sta[top]);
		top--;
	}
	putchar('\n');
}
int main(){
	//freopen("tree.in","r",stdin);freopen("tree.out","w",stdout);
	n=read();
	fac[0]=1;
	fo(i,1,n) fac[i]=(ll)fac[i-1]*i%mo;
	inv[n]=qsm(fac[n],mo-2);
	fd(i,n-1,0) inv[i]=(ll)inv[i+1]*(i+1)%mo;
	fo(i,1,n-1){
		j=read();k=read();
		add(j,k);add(k,j);
	}
	dfs(1,0);
	len=1;
	while (len<=2*n) len*=2;
	ce=log(len)/log(2);
	prepare();
	fo(i,0,n){
		t=int(a[i].x);
		a[i].x=(ll)t*fac[i]%mo;
	}
	fd(i,n,0) b[n-i].x=inv[i];
	FFT();
	fo(i,1,n){
		ans[i]=(ll)ans[i]*inv[i]%mo;
		(ans[i]+=mo)%=mo;
		write(ans[i]);
	}
}

#include<bits/stdc++.h>
using namespace std;
const int mod=924844033,maxn=200010;
int hea[maxn],nxt[maxn<<1],to[maxn<<1],a[maxn<<2],b[maxn<<2],n,tot;
inline int read()
{
