void NTT(int a[], bool inverse) {
    rep(i, N)
        if (rev[i] > i)
            swap(a[rev[i]], a[i]);
    for (int len = 2; len <= N; len <<= 1) {
        int wn = pw(3, (mod - 1) / len);
        if (inverse)
            wn = pw(wn, mod - 2);
        for (int j = 0; j < N; j += len) {
            int w = 1;
            for (int x = j, y = j + len / 2; y < j + len; ++x, ++y) {
                int u = a[x], v = ll(a[y]) * w % mod;
                a[x] = u + v; 
                a[y] = u - v + mod;
                while (a[x] >= mod)
                    a[x] -= mod;
                while (a[y] >= mod)
                    a[y] -= mod;
                w = ll(w) * wn % mod;
            }
        }
    }
    if (inverse) {
        int div = pw(N, mod - 2);
        rep(i, N)
            a[i] = ll(a[i]) * div % mod;
    }
}

