template <class T>
inline T modularExp(T base, T exp)
{
	T ret(1);

	while(exp)
	{
		if(exp & 1)
			ret = 1LL * ret * base % MOD ;
		base = 1LL * base * base % MOD ;
		exp = exp >> 1;
	}

	return ret;
}

namespace NumberTheoryTransformation
