const int mod = 924844033, maxn = 1e6 + 10, maxm = 4e5 + 10;

int Pow(int x, int p)
{
	int r = 1;
	while(p)
	{
		if(p & 1) r = 1LL * x * r % mod;
		x = 1LL * x * x % mod; p >>= 1;
	}
	return r;
}

int to[maxm], nxt[maxm], head[maxn], e, n;
int sz[maxn], cnt[maxn], rev[maxn], g[maxn], inv;

void add(int x, int y)
{
	to[++e] = y; nxt[e] = head[x]; head[x] = e;
	to[++e] = x; nxt[e] = head[y]; head[y] = e;
}

void dfs(int u, int fa)
{
	sz[u] = 1;
	for(int i = head[u]; i; i = nxt[i])
	{
		int v = to[i];
		if(v == fa) continue;
		dfs(v, u); sz[u] += sz[v];
	}
	--cnt[sz[u]]; --cnt[n - sz[u]];
}

void init(int len)
{
	int z = __builtin_ctz(len);
	for(int i = 0; i < len; ++i)
		rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (z - 1));

	int G = Pow(5, (mod - 1) / len); g[0] = 1;
	for(int i = 1; i <= len; ++i) g[i] = 1LL * g[i - 1] * G % mod;
	inv = Pow(len, mod - 2);
}

void DFT(int *a, int len, int fg)
{
	for(int i = 0; i < len; ++i) if(rev[i] > i) swap(a[i], a[rev[i]]);
	for(int i = 2; i <= len; i <<= 1)
		for(int j = 0; j < len; j += i)
			for(int k = 0; k < i / 2; ++k)
			{
				int y = 1LL * (fg ? g[len / i * k] : g[len - len / i * k]) * a[j + k + i / 2] % mod;
				int x = a[j + k];
				a[j + k] = (x + y) % mod;
				a[j + k + i / 2] = (x - y) % mod;
			}
	if(fg == 0) for(int i = 0; i < len; ++i) a[i] = 1LL * a[i] * inv % mod;
}

int a[maxn], b[maxn];
int fac[maxn], ifac[maxn];

int main()
{
	n = read();
	for(int i = 1; i < n; ++i) add(read(), read());
	dfs(1, 0); cnt[n] = n;
	for(int i = 0; i < n; ++i) cnt[i] += mod;

	fac[0] = 1; ifac[0] = 1;
	for(int i = 1; i <= n; ++i) fac[i] = 1LL * i * fac[i - 1] % mod;
	ifac[n] = Pow(fac[n], mod - 2);
	for(int i = n - 1; i >= 0; --i) ifac[i] = 1LL * ifac[i + 1] * (i + 1) % mod;

	for(int i = 0; i <= n; ++i)
	{
		a[i] = 1LL * cnt[i] * fac[i] % mod;
	   	b[i] = ifac[n - i];
	}

	int len = 1;
	while(len <= (n + n)) len <<= 1;
	init(len);
	DFT(a, len, 1); DFT(b, len, 1);
	for(int i = 0; i < len; ++i) a[i] = 1LL * a[i] * b[i] % mod;
	DFT(a, len, 0);

	for(int i = 1; i <= n; ++i)
	{
		int ans = 1LL * a[n + i] * ifac[i] % mod;
		ans = (ans + mod) % mod;
		printf("%d\n", ans);
	}

	return 0;
}

