}
const int N = 2e5 + 10, Mod = 924844033;
int siz[N], n;
struct node { int to, nxt; } g[N << 1];
int lst[N], gl, cnt[N];
void add(int x, int y) {
	g[++gl] = (node) {y, lst[x]}; lst[x] = gl;
	g[++gl] = (node) {x, lst[y]}; lst[y] = gl;
}
void dfs(int u, int ff) {
	siz[u] = 1;
	for (int i = lst[u]; i; i = g[i].nxt) {
		int v = g[i].to; if (v == ff) continue;
		dfs(v, u); siz[u] += siz[v]; cnt[siz[v]]++;
	}
	cnt[n - siz[u]]++;
}
int fac[N], ifac[N];
int fpow(int a, int b) {
	int res = 1;
	for (; b; b >>= 1, a = 1ll * a * a % Mod)
		if (b & 1) res = 1ll * res * a % Mod;
	return res;
}
int A[N << 2], B[N << 2], lim, rev[N << 2];
void NTT(int *a, int op) {
	for (int i = 0; i < lim; i++)
		if (i < rev[i]) swap(a[i], a[rev[i]]);
	for (int i = 1; i < lim; i <<= 1)
		for (int j = 0, w = fpow(5, (Mod - 1) / (i << 1)); j < lim; j += i << 1)
			for (int k = j, s = 1; k < i + j; k++, s = 1ll * s * w % Mod) {
				int t = 1ll * a[i + k] * s % Mod;
				a[i + k] = (a[k] - t + Mod) % Mod;
				a[k] = (a[k] + t) % Mod;
			}
	if (op == -1) {
		reverse(a + 1, a + lim);
		for (int i = 0, inv = fpow(lim, Mod - 2); i < lim; i++)
			a[i] = 1ll * a[i] * inv % Mod;
	}
	return ;
}
int C(int n, int m) {
	if (n < m) return 0;
	return 1ll * fac[n] * ifac[m] % Mod * ifac[n - m] % Mod;
}
int main() {
	//freopen(".in", "r", stdin);
