	n = gi<int>();
	for (int i = 1; i < n; i++) add(gi<int>(), gi<int>());
	fac[0] = 1;
	for (int i = 1; i <= n; i++) fac[i] = 1ll * fac[i - 1] * i % Mod;
	ifac[n] = fpow(fac[n], Mod - 2);
	for (int i = n; i >= 1; i--) ifac[i - 1] = 1ll * ifac[i] * i % Mod;
	dfs(1, 0);
	for (int i = 1; i <= n; i++) A[i] = 1ll * cnt[i] * fac[i] % Mod;
	for (int i = 0; i <= n; i++) B[n - i] = ifac[i];
	int l = -1; lim = 1;
	while (lim <= 2 * n) lim <<= 1, l++;
	for (int i = 0; i < lim; i++) rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << l);
	NTT(A, 1), NTT(B, 1);
	for (int i = 0; i < lim; i++) A[i] = 1ll * A[i] * B[i] % Mod;
	NTT(A, -1);
	for (int i = 1; i <= n; i++)
		printf("%d\n", (1ll * n * C(n, i) % Mod - 1ll * A[n + i] * ifac[i] % Mod + Mod) % Mod);
	return 0;
}

