const int maxn = 2e5, maxm = 19;
const int mod = 924844033, gen = 5;

int n;
vector<int> g[maxn];
int size[maxn], cnt[maxn];
int fact[maxn + 1], ifact[maxn + 1];
int a[1 << maxm], b[1 << maxm];

void Dfs(int u, int p) {
  size[u] = 1;
  for (int v : g[u]) {
    if (v == p) continue;
    Dfs(v, u);
    size[u] += size[v];
