inline int Mul(int a, int b) {
  return (long long)a * b % mod;
}

inline int Add(int a) {
  return a >= mod ? a - mod : a;
}

inline int Sub(int a) {
  return a < 0 ? a + mod : a;
}

int Pow(int a, int b) {
  int c = 1;
  for (; b; b >>= 1) {
    if (b & 1) c = Mul(c, a);
    a = Mul(a, a);
  }
  return c;
}

void FFT(int *a, int n) {
  for (int i = 0; i < 1 << n; ++i) {
    int j = 0, x = i;
    for (int k = 0; k < n; ++k) {
      j = (j << 1) | (x & 1);
      x >>= 1;
    }
    if (i < j) {
      swap(a[i], a[j]);
    }
  }
  for (int i = 0; i < n; ++i) {
    int root = Pow(gen, (mod - 1) / (2 << i));
    for (int j = 0; j < 1 << n; j += 2 << i) {
      int *l = a + j, *r = l + (1 << i), w = 1;
      for (int k = 0; k < 1 << i; ++k, w = Mul(w, root)) {
        int t = Mul(w, r[k]);
        r[k] = Sub(l[k] - t);
        l[k] = Add(l[k] + t);
      }
    }
  }
}

void IFFT(int *a, int n) {
  reverse(a + 1, a + (1 << n));
  FFT(a, n);
  int inv = Pow(1 << n, mod - 2);
  for (int i = 0; i < 1 << n; ++i) {
    a[i] = Mul(a[i], inv);
  }
}

int main(void) {
  scanf("%d", &n);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    scanf("%d%d", &a, &b); --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  Dfs(0, -1);
  fact[0] = 1;
  for (int i = 1; i <= n; ++i) {
    fact[i] = Mul(fact[i - 1], i);
  }
  ifact[n] = Pow(fact[n], mod - 2);
  for (int i = n; i >= 1; --i) {
    ifact[i - 1] = Mul(ifact[i], i);
  }
  for (int i = 0; i < n; ++i) {
    a[i] = ifact[i];
  }
  for (int i = 1; i < n; ++i) {
    b[i] = Mul(cnt[n - i], fact[n - i]);
  }
  int m = 0;
  while (1 << m < n << 1) {
    ++m;
  }
  FFT(a, m);
  FFT(b, m);
  for (int i = 0; i < 1 << m; ++i) {
    a[i] = Mul(a[i], b[i]);
  }
  IFFT(a, m);
  for (int k = 1; k <= n; ++k) {
    int t = Mul(a[n - k], ifact[k]);
    int c = Mul(fact[n], Mul(ifact[k], ifact[n - k]));
    printf("%d\n", Sub(Mul(n, c) - t));
  }
