	}
	for (int i = 2; i < n; i++) {
		w[i] = (ll)w[i - 1] * w[1] % p;
	}
	for (int i = 1, j = n / 2; i + 1 < n; i++) {
		if (i < j) {
			swap(a[i], a[j]);
		}
		int k = n / 2;
		while (j >= k) {
			j -= k;
			k /= 2;
		}
		j += k;
	}
	for (int l = 1; l < n; l <<= 1) {
		for (int i = 0; i < n; i += l << 1) {
			int t = 0;
			for (int j = i; j < i + l; j++) {
				int u = a[j], v = (ll)a[j + l] * w[t] % p;
				a[j] = (u + v) % p;
				a[j + l] = (u - v + p) % p;
				t += n / l / 2;
			}
		}
	}
	if (x) {
		int t = pow(n, p - 2);
		for (int i = 0; i < n; i++) {
			a[i] = (ll)a[i] * t % p;
		}
	}
}
