	copy(a.begin(), a.end(), A.begin());
	copy(b.begin(), b.end(), B.begin());
	ntt(A);
	ntt(B);
	for (int i = 0; i < m; i++) {
		A[i] = (ll)A[i] * B[i] % p;
	}
	ntt(A, true);
	a = A;
}
