int n, siz[MAXN], cnt[MAXN], rev[MAXN];
LL fac[MAXN], inv[MAXN], finv[MAXN], F[MAXN], G[MAXN];

struct Edge {
	int v, nxt;
}e[MAXN];
int first[MAXN], eCnt;

inline void AddEdge(int u, int v) {
	e[++eCnt].v = v;
	e[eCnt].nxt = first[u];
	first[u] = eCnt;
}

void DFS(int u, int fa) {
	siz[u] = 1;
	for (int i=first[u];i;i=e[i].nxt) {
		int v = e[i].v;
		if (v == fa) continue;
		DFS(v, u);
		siz[u] += siz[v];
	}
}

inline LL ksm(LL x, LL k) {
    LL ret = 1;
    while (k) {
        if (k & 1) ret = ret * x % MOD;
        x = x * x % MOD;
        k >>= 1;
    }
    return ret;
}

inline void NTT_init(int &len, int m) {
    int bit = -1;
    for(len=1;len<m;len<<=1) ++bit;
    for (int i=0;i<len;++i) {
        rev[i] = (rev[i>>1]>>1) | ((i&1)<<bit);
    }
}

void NTT(LL *a, int len, int type) {
    for (int i=0;i<len;++i) {
        if (i < rev[i]) {
            swap(a[i], a[rev[i]]);
        }
    }
    for (int i=1;i<len;i<<=1) {
        int p = (i<<1);
        LL wn = ksm((type==1)? Gi : Ginv, (MOD-1)/p);
        for (int j=0;j<len;j+=p) {
            LL wnk = 1;
            for (int k=0;k<i;++k) {
                LL x = a[j+k], y = wnk * a[j+k+i] % MOD;
                a[j+k] = (x + y) % MOD;
                a[j+k+i] = (x - y + MOD) % MOD;
                wnk = wnk * wn % MOD;
            }
        }
    }
    if (type == 1) return;
    LL Ninv = ksm(len, MOD-2);
    for (int i=0;i<len;++i) {
        a[i] = a[i] * Ninv % MOD;
    }
}

void init() {
	read(n);
	for (int i=1,u,v;i<n;++i) {
		read(u); read(v);
		AddEdge(u, v);
		AddEdge(v, u);
	}
	fac[0] = fac[1] = inv[0] = inv[1] = finv[0] = finv[1] = 1;
	for (int i=2;i<=n;++i) {
		fac[i] = fac[i-1] * i % MOD;
		inv[i] = (MOD-MOD/i) * inv[MOD%i] % MOD;
		finv[i] = finv[i-1] * inv[i] % MOD;
	}
}

void solve() {
	DFS(1, 0);
	for (int i=2;i<=n;++i) {
		++cnt[siz[i]];
		++cnt[n-siz[i]];
	}
	cnt[n] -= n;
	for (int i=0;i<=n;++i) {
		F[n-i] = fac[i] * (MOD-cnt[i]) % MOD;
		G[i] = finv[i];
	}
	int len; NTT_init(len, (n+1)<<1);
	NTT(F, len, 1); NTT(G, len, 1);
	for (int i=0;i<len;++i) {
		F[i] = F[i] * G[i] % MOD;
	}
	NTT(F, len, -1);
	for (int i=1;i<=n;++i) {
		printf("%lld\n", F[n-i] * finv[i] % MOD);
	}
}

int main() {
	init();
	solve();
	return 0;
}

