void ntt(ll A[],int n,int mode){
    for(int i=1,j=0;i<n;i++){
        for(int s=n;j^=s>>=1,~j&s;);
        if(i<j) swap(A[i],A[j]);
    }
    for(int i=1;i<n;i<<=1){
        ll w1=ksm(G,(MOD-1)/(i<<1)),w=1;
        if(mode==-1) w1=ksm(w1,MOD-2);
        for(int j=0;j<i;j++,w=(1ll*w*w1)%MOD)
            for(int l=j,r=l+i;l<n;l+=(i<<1),r=l+i){
                int temp=1ll*A[r]*w%MOD;
                A[r]=(A[l]-temp+MOD)%MOD;
                A[l]=(A[l]+temp)%MOD;
            }
    }
    if(mode==-1){
        ll inv=ksm(n,MOD-2);
        for(int i=0;i<n;i++)
            A[i]=1ll*inv*A[i]%MOD;
    }
}

