	fac[0] = fac[1] = inv[0] = inv[1] = 1;
	for(int i = 2; i <= n; ++i) {
		fac[i] = 1LL * i * fac[i-1] % P;
		inv[i] = 1LL * (P - P / i) * inv[P % i] % P;
	}
	for(int i = 2; i <= n; ++i) inv[i] = 1LL * inv[i] * inv[i-1] % P;
	for(int i = 0; i <= n; ++i) {
		A[i] = 1LL * A[i] * fac[i] % P;
		B[i] = inv[n-i];
	}

	Mul();

	for(int i = 1; i <= n; ++i) printf("%d\n", ans[i]);
	return 0;
}

