NTT<MOD, 5> ntt;

std::map<int, std::vector<int> > beki; // polynomial (x + 1) ^ i
void init(int n2) {
	beki[1] = {1, 1};
	for (int i = 2; i <= n2; i <<= 1) {
		auto tmp = beki[i / 2];
		tmp.resize(tmp.size() * 2);
		ntt.ntt(tmp, false);
		for (auto &i : tmp) i = (int64_t) i * i % MOD;
		ntt.ntt(tmp, true);
		beki[i] = tmp;
	}
}

std::vector<int> solve(int l, int r) {
	if (r - l == 1) return { count[l] };
	int mid = l + ((r - l) >> 1);
	auto r0 = solve(l, mid);
	auto r1 = ntt.conv(solve(mid, r), beki[mid - l]);
	for (int i = 0; i < (int) r0.size(); i++) {
		r1[i] += r0[i];
		if (r1[i] >= MOD) r1[i] -= MOD;
	}
	r1.resize(r - l + 1);
	return r1;
}

