const int N = 524288 + 5;
const int mo = 924844033;
const int g = 5;

int n, len;
int sz[N], rev[N];
vector<int> v[N];
LL c[N], a[N], b[N], f[N], wn[N];

void dfs(int x, int p) {
	sz[x] = 1;
	for (int i = 0; i < (int)v[x].size(); i++) {
		int y = v[x][i];
		if (y == p) continue;
		dfs(y, x);
		sz[x] += sz[y];
		c[sz[y]]--;
		c[n - sz[y]]--;
	}
}

LL get_pow(LL a, LL b) {
	LL ans = 1; a %= mo;
	while (b) {
		if (b & 1) ans = ans * a % mo;
		a = a * a % mo;
		b >>= 1;
	}
	return ans % mo;
}

LL getinv(LL x) {return get_pow(x, mo - 2);}

void NTT(LL *a, int len, int d = 1) {
	for (int i = 0; i < len; i++) if (i < rev[i]) swap(a[i], a[rev[i]]);
	int id = 0;
	for (int m = 2; m <= len; m <<= 1) {
		id++;
		LL wm = get_pow(g, (d * (mo - 1) / m) + mo - 1);
		for (int i = 0; i < len; i += m) {
			LL w = 1;
			for (int j = i; j < i + m / 2; j++) {
				LL u = a[j], v = w * a[j + m / 2] % mo;
				a[j] = (u + v) % mo;
				a[j + m / 2] = (u - v) % mo;
				w = w * wm % mo;
			}
		}
	}
	if (d == -1) {LL inv = getinv(len); for (int i = 0; i < len; i++) a[i] = a[i] * inv % mo;}
}

void pre() {
	for (int i = 1; i < len; i++) rev[i] = (rev[i >> 1] >> 1) | (i & 1 ? (len >> 1) : 0);
}

int main() {
	read(n);
