	}
	dfs(1, 0); c[n] = n; f[0] = 1;
	for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % mo;
	for (int i = 0; i <= n; i++) a[i] = c[i] * f[i] % mo;
	for (int i = 0; i <= n; i++) b[i] = getinv(f[i]);
	for (int i = 0; i <= n / 2; i++) swap(a[i], a[n - i]);
	for (len = 1; len < 2 * (n + 1); len <<= 1);
	pre(); NTT(a, len); NTT(b, len);
	for (int i = 0; i < len; i++) c[i] = a[i] * b[i] % mo;
	NTT(c, len, -1);
	for (int i = n - 1; i >= 0; i--) {
		LL ans = c[i];
		ans = ans * getinv(f[n - i]) % mo;
		printf("%lld\n", (ans + mo) % mo);
	}
	return 0;
}

