LL cheng(LL a,LL b)
{
	LL res=1;
	for(;b;b>>=1,a=a*a%mo)
	if(b&1)
	res=res*a%mo;
	return res;
}

void Init(int lim)
{
	int k=-1;
	n=1;
	while(n<lim)
	n<<=1,k++;
	for(int i=1;i<n;i++)
	rev[i]=(rev[i>>1]>>1) | ((i&1)<<k); 

	I[1]=1;
	Ijc[0]=jc[0]=1;

	for(int i=2;i<=n;i++)
	I[i]=(mo-mo/i)*I[mo%i]%mo;
	for(int i=1;i<=n;i++)
	jc[i]=jc[i-1]*i%mo,Ijc[i]=Ijc[i-1]*I[i]%mo;
}

void ntt(LL *a,int ops)
{
	for(int i=0;i<n;i++)
	if(i<rev[i])
	swap(a[i],a[rev[i]]);

	for(int l=2;l<=n;l<<=1)
	{
		int m=l>>1;
		LL wn=(ops) ? cheng(5,(mo-1)/l) : cheng(5,mo-1-(mo-1)/l);
		for(int i=0;i<n;i+=l)
		{
			LL w=1;
			for(int k=0;k<m;k++)
			{
				LL t=a[i+k+m]*w%mo;
				a[i+k+m]=(a[i+k]-t+mo)%mo;
				a[i+k]=(a[i+k]+t)%mo;
				w=w*wn%mo;
			}
		}
	}
	if(!ops)
	for(int i=0;i<n;i++)
	a[i]=a[i]*I[n]%mo;
}

