namespace NTT{
	const int M=524288;
	int rt,w[M],a[M],b[M];
	inline void fft(int *x,int n){
		for(int i=0,j=0;i<n;i++){
			if(i<j) swap(x[i],x[j]);
			for(int k=n>>1;(j^=k)<k;k>>=1);
		}
		for(int i=2;i<=n;i<<=1){
			int c=i>>1,now=n/i;
			for(int j=0;j<n;j+=i)
				for(int k=0;k<c;k++){
					int t=(ll)x[j+k+c]*w[now*k]%mod;
					x[j+k+c]=(x[j+k]-t)%mod;
					x[j+k]=(x[j+k]+t)%mod;
				}
		}
	}
	inline void mul(int *x,int *y,int n,int m,int *res,int k){
//		gmin(k,m+n);
		int maxx=1,wn;
		while(maxx<=(n+m)) maxx<<=1;
		for(int i=0;i<maxx;i++) a[i]=b[i]=0;
		for(int i=0;i<=n;i++) a[i]=x[i];
		for(int i=0;i<=m;i++) b[i]=y[i];
		w[0]=1;wn=exp(rt,(mod-1)/maxx);
		for(int i=1;i<=maxx;i++) w[i]=(ll)w[i-1]*wn%mod;
		fft(a,maxx);fft(b,maxx);
		for(int i=0;i<maxx;i++) a[i]=(ll)a[i]*b[i]%mod;
		reverse(w+1,w+maxx);
		fft(a,maxx);
		int inv=exp(maxx,mod-2);
		for(int i=0;i<=m+n&&i<=k;i++) res[i]=((ll)a[i]*inv%mod+mod)%mod;
		for(int i=m+n+1;i<=k;i++) res[i]=0;
	}
	inline void poly_inv(int *a,const int n,int *b){
		if(n==1){
			b[0]=exp(a[0],mod-2);
			return;
		}
		int b0[n+15],m=(n+1)/2;clr(b0,0);
		poly_inv(a,m,b0);
		mul(b0,b0,m-1,m-1,b,n-1);
		mul(a,b,n-1,n-1,b,n-1);
		for(int i=0;i<n;i++)
			b[i]=((ll)b0[i]*2-b[i]+mod)%mod;
	}
	inline void poly_div(int *a,int *b,int n,int m,int *d,int *r){
		reverse(a,a+n+1);reverse(b,b+m+1);
		poly_inv(b,n-m+1,d);
		mul(a,d,n-m,n-m,d,n-m);
		reverse(a,a+n+1);reverse(b,b+m+1);reverse(d,d+n-m+1);
		mul(b,d,m,n-m,r,n);
		for(int i=0;i<=n;i++)
			r[i]=(a[i]-r[i]+mod)%mod;
	}
