int qPow(int x, int k) {
    int rtn = 1;
    for (; k; k >>= 1, x = (ll)x * x % P)
        if (k & 1) rtn = (ll)rtn * x % P;
    return rtn;
}
namespace NTT {
    const int G = 5;

    int n;
    int rev[N<<2];
    int a[N<<2], b[N<<2], t[N<<2];

    void init(int m) {
        int len = 0;
        for (n = 1; n < m; n <<= 1)
            len++;
        for (int i = 0; i < n; i++)
            rev[i] = rev[i>>1] >> 1 | (i&1) << len-1;
    }

    void NTT(int f[], int sgn) {
        for (int i = 0; i < n; i++)
            if (rev[i] > i) std::swap(f[rev[i]], f[i]);
        for (int i = 1; i < n; i <<= 1) {
            int gn = qPow(G, (P-1)/(i*2));
            if (sgn == -1) gn = qPow(gn, P-2);
            for (int j = 0; j < n; j += i*2) {
                int g = 1;
                for (int k = 0; k < i; k++, g = (ll)g * gn % P) {
                    int x = f[j+k], y = (ll)g * f[j+i+k] % P;
                    f[j+k] = (x + y) % P;
                    f[j+i+k] = (x - y) % P;
                }
            }
        }
        if (sgn == -1) {
            int invn = qPow(n, P-2);
            for (int i = 0; i < n; i++)
                f[i] = (ll)f[i] * invn % P;
        }
        for (int i = 0; i < n; i++)
            f[i] = (f[i] + P) % P;
    }

    void mul(int la, int ta[], int lb, int tb[], int res[]) {
        init(la+lb-1);
        memset(a, 0, sizeof a);
        memset(b, 0, sizeof b);
        for (int i = 0; i < la; i++)
            a[i] = ta[i];
        for (int i = 0; i < lb; i++)
            b[i] = tb[i];
        NTT(a, 1);
        NTT(b, 1);
        for (int i = 0; i < n; i++)
            t[i] = (ll)a[i] * b[i] % P;
        NTT(t, -1);
        for (int i = 0; i < la+lb-1; i++)
            res[i] = t[i];
    }
}
