int A[MAXM], B[MAXM], rev[MAXM];

int quick_pow(int a, int x) {
    int res = 1;
    while (x) {
        if (x & 1)
            res = 1ll * res * a % MOD;
        a = 1ll * a * a % MOD, x >>= 1;
    }
    return res;
}

void link(int u, int v) {
    to[++et] = v, ne[et] = fir[u], fir[u] = et;
}

void dfs(int o, int fa) {
    siz[o] = 1;
    for (int i = fir[o]; i; i = ne[i])
        if (to[i] != fa) {
            dfs(to[i], o);
            siz[o] += siz[to[i]];
        }
}

void ntt(int *A, int n, bool t) {
    for (int i = 0; i < n; i++)
        if (i < rev[i])
            swap(A[i], A[rev[i]]);
    for (int i = 1, gn, g, x, y; i < n; i <<= 1) {
        gn = quick_pow(G, (MOD - 1) / (i << 1));
        for (int j = 0; j < n; j += i << 1) {
            g = 1;
            for (int k = 0; k < i; k++) {
                x = A[j + k], y = 1ll * A[j + k + i] * g % MOD;
                A[j + k] = (x + y) % MOD, A[j + k + i] = (x - y + MOD) % MOD;
                g = 1ll * g * gn % MOD;
            }
        }
    }
    if (!t) {
        reverse(A + 1, A + n);
        int inv = quick_pow(n, MOD - 2);
        for (int i = 0; i < n; i++)
            A[i] = 1ll * A[i] * inv % MOD;
    }
}

void mul(int n, int m) {
    m += n, n = 1;
    int Log = 0;
    while (n <= m)
        n <<= 1, Log++;
    for (int i = 0; i < n; i++)
        rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (Log - 1));
    ntt(A, n, 1), ntt(B, n, 1);
    for (int i = 0; i < n; i++)
        A[i] = 1ll * A[i] * B[i] % MOD;
    ntt(A, n, 0);
}

ll calc_C(int n, int r) {
    return n < r ? 0 : 1ll * jc[n] * inv[r] % MOD * inv[n - r] % MOD;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
        jc[i] = 1ll * jc[i - 1] * i % MOD;
    inv[n] = quick_pow(jc[n], MOD - 2);
    for (int i = n; i; i--)
        inv[i - 1] = 1ll * i * inv[i] % MOD;
    for (int i = 1, x, y; i < n; i++) {
        scanf("%d %d", &x, &y);
        link(x, y), link(y, x);
    }
    dfs(1, 0);
    for (int i = 2; i <= n; i++) {
        A[siz[i]] = (A[siz[i]] + jc[siz[i]]) % MOD;
        A[n - siz[i]] = (A[n - siz[i]] + jc[n - siz[i]]) % MOD;
    }
    for (int i = 0; i <= n; i++)
        B[n - i] = inv[i];
    mul(n, n);
    for (int i = n + 1; i <= n << 1; i++) {
        A[i] = 1ll * A[i] * inv[i - n] % MOD;
        printf("%lld\n", (n * calc_C(n, i - n) % MOD - A[i] + MOD) % MOD);
    }
    return 0;
}

