const int GG = 5;

void FFT(int *num, int N, int tp)
{
	int L = -1;
	for (int m = 1; m < N; m <<= 1) L++;
	FOR(i, 1, N - 1) rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << L);

	FOR(i, 0, N - 1) if (i < rev[i]) std::swap(num[i], num[rev[i]]);

	for (int i = 1; i < N; i <<= 1) {
		int wn = power(GG, (MOD - 1) / (i << 1));
		if (tp == -1) wn = power(wn, MOD - 2);
		for (int j = 0, p = i << 1; j < N; j += p) {
			int w = 1;
			for (int k = 0; k < i; k++, w = 1ll * w * wn % MOD) {
				int x = num[j + k], y = 1ll * num[j + k + i] * w % MOD;
				num[j + k] = (x + y) % MOD;
				num[j + k + i] = (x - y + MOD) % MOD;
			}
		}
	}

	if (tp == -1) {
		int invN = power(N, MOD - 2);
		FOR(i, 0, N - 1) num[i] = 1ll * num[i] * invN % MOD;
	}
}

