int pw(int a,int x)
{
	int ans=1;
	for(;x;x>>=1,a=1ll*a*a%P)
		if(x&1)ans=1ll*ans*a%P;
	return ans;
}

void dfs(int u,int fa)
{
	size[u]=1;
	for(int i=fst[u];i;i=nxt[i])
		if(to[i]!=fa)
		{
