			size[u]+=size[to[i]];
		}
	if(fa)d[size[u]]++,d[n-size[u]]++;
}

void ntt(int *a,int n,int inv)
{
	for(int i=0,j=0;i<n;i++)
	{
		if(i>j)swap(a[i],a[j]);
		for(int k=n>>1;(j^=k)<k;k>>=1);
	}
	for(int i=2;i<=n;i<<=1)
	{
		int m=i>>1,wn=pw(G,(P-1)+inv*(P-1)/i);
		for(int *p=a;p<a+n;p+=i)
		{
			int w=1;
			for(int j=0;j<m;j++)
			{
				int t=1ll*w*p[m+j]%P;
				p[m+j]=(p[j]-t)%P;
				p[j]=(p[j]+t)%P;
				w=1ll*w*wn%P;
			}
		}
	}
	if(inv==-1)
	{
		int t=pw(n,P-2);
		for(int i=0;i<n;i++)a[i]=1ll*a[i]*t%P;
	}
}

