constexpr int MOD = 924844033;
vector<mint<MOD> > solve(int n, const vector<vector<int> > & g_) {
    // list edges and calculate frequency
    vector<int> freq(n + 1);
    auto go = [&](auto && go, int x, int parent) -> int {
        int size = 1;
        for (int y : g_[x]) if (y != parent) {
            int a = go(go, y, x);
            int b = n - a;
            freq[a] += 1;
            freq[b] += 1;
            size += a;
        }
        return size;
    };
    go(go, 0, -1);

    // dp
    // equivalent to: REP (k, n + 1) REP3 (a, k, n + 1) dp[k] += freq[a] * choose<MOD>(a, k);  // O(N^2)
    vector<mint<MOD> > dp(n + 1);
    vector<mint<MOD> > f(n + 1);
    vector<mint<MOD> > g(n + 1);
    REP (i, n + 1) {
        f[i] = fact<MOD>(i) * freq[i];
        g[i] = inv_fact<MOD>((n + 1) - i - 1);
    }
    vector<mint<MOD> > h = ntt_convolution(f, g);
    REP (i, n + 1) {
        dp[i] = h[n + i] * inv_fact<MOD>(i);
    }

    // count vertices instead of edges
    vector<mint<MOD> > ans(n + 1);
    REP3 (k, 1, n + 1) {
        ans[k] = (1 + n - 1) * choose<MOD>(n, k) - dp[k];
    }
    return ans;
}

