	while(N<=n*2) N<<=1;
	REP(i,0,N-1) rev[i]=(rev[i>>1]>>1)|((i&1)*(N>>1));
	for(int k=1,t=0;k<=N;k<<=1,t++){
		g[t][1]=ksm(g0,(mod-1)/k);
		g[t][0]=ksm(g[t][1],mod-2);
	}
	ntt(A,1),ntt(B,1);
	REP(i,0,N-1) A[i]=1ll*A[i]*B[i]%mod;
	ntt(A,0);
	int inv=ksm(N,mod-2);
	REP(i,0,N-1) A[i]=1ll*A[i]*inv%mod;
	REP(i,1,n){
		ans[i]=1ll*n*fac[n]%mod*ifac[n-i]%mod;
		ans[i]=1ll*(ans[i]+mod-A[n-i])%mod*ifac[i]%mod;
	}
	REP(i,1,n) printf("%d\n",ans[i]);
	return 0;
}

