void Addcon(int o, int f)
{
	A[o] += f;
	if(A[o] < 0) A[o] += mod;
	if(A[o] >= mod) A[o] -= mod;
}

void dfs_Modulus(int u, int fa)
{
	Addcon(n, +1);
	size[u] = 1;

	for(int i = Begin[u]; i; i = E[i].next){
		int v = E[i].to;
		if(v == fa) continue;
		dfs_Modulus(v, u);
		size[u] += size[v];

		Addcon(size[v], -1);
	}

	Addcon(n-size[u], -1);
}

void Init()
{
	read(n);
	for(int i = 1; i < n; ++i){
		int u, v; 
		read(u), read(v);
		add_edge(u, v);
	}

	bit_cnt = 0;
	Len = 1; 
	for(; Len <= n + n; Len <<= 1, ++bit_cnt) {}

	REP(i, Len){
		rev[i] = (rev[i>>1] >> 1) | ((i&1) << (bit_cnt-1));
	}

	return ;
}

void Work()
{
	dfs_Modulus(1, 0);

	int fac = 1;
	for(int i = 1; i <= n; ++i){
		fac = (LL)fac * i % mod;
		A[i] = (LL)A[i] * fac % mod;
	}
	fac = 1;
	for(int i = 0; i < n; ++i){
		if(i) fac = (LL)fac * i % mod;
		B[n - i] = fpm(fac, mod - 2);
	}

	NTT(A, Len, 0), NTT(B, Len, 0);
	REP(i, Len) A[i] = (LL)A[i] * B[i] % mod;
	NTT(A, Len, 1);

	fac = 1;
	for(int i = 1; i <= n; ++i){
		fac = (LL)fac * i % mod;
		printf("%lld\n", (LL)A[n + i] * fpm(fac, mod-2) % mod);
	}

	return ;
}

