using namespace std;

struct FFT{
	const int mod, g;
	FFT(int a, int b):mod(a), g(b){}
	long long mul(long long a, long long b){
		return (a * b) % mod;
	}
	long long ex(long long a, long long e){
		long long ans = 1, tmp = a;
		while(e > 0){
			if(e % 2 == 1){
				ans = mul(ans, tmp);
			}
			tmp = mul(tmp, tmp);
			e /= 2;
		}
		return ans;
	}
	long long inv(long long a){
		return ex(a, mod - 2);
	}
	void fft(vector<long long> &a, long long h){
		int N = a.size();
		for(int m = N; m >= 2; m /= 2){
			int mh = m / 2;
			long long w = 1;
			for(int i = 0; i < mh; ++i){
				for(int j = i; j < N; j += m){
					int k = j + mh;
					long long x = a[j] - a[k];
					a[j] += a[k];
					if(a[j] > mod) a[j] -= mod;
					a[k] = mul(w, x);
					if(a[k] < 0) a[k] += mod;
				}
				w = mul(w, h);
			}
			h = mul(h, h);
		}
		int i = 0;
		for(int j = 1; j < N - 1; ++j){
			for(int k = N / 2; k > (i ^= k); k /= 2);
			if(j > i) swap(a[i], a[j]);
		}
	}
	vector<long long> convolution(vector<long long> a, vector<long long> b){
		int n = a.size() + b.size();
		int N = 1;
		while(N < n) N *= 2;
		a.resize(N);
		b.resize(N);
		long long h = ex(g, (mod - 1) / N);
		fft(a, h);
		fft(b, h);
		for(int i = 0; i < N; ++i) a[i] = mul(a[i], b[i]);
		h = inv(h);
		fft(a, h);
		long long iN = inv(N);
		for(int i = 0; i < N; ++i) a[i] = mul(a[i], iN);
		return a;
	}
};

const long long mod = 924844033;

long long fact[200200];
long long ifact[200200];
long long is[200200];

inline long long mul(long long a, long long b){
	return (a * b) % mod;
}

void init(){
	int MA = 200200;
	fact[0] = 1;
	for(int i = 1; i < MA; ++i){
		fact[i] = mul(fact[i - 1], i);
	}
	is[1] = 1;
	for(int i = 2; i < MA; ++i){
		int k = mod / i;
		int r = mod % i;
		long long tmp = is[r] * (-k);
		tmp %= mod;
		if(tmp < 0) tmp += mod;
		is[i] = tmp;
	}
	ifact[0] = 1;
	for(int i = 1; i < MA; ++i){
		ifact[i] = mul(ifact[i - 1], is[i]);
	}
}

long long C(int n, int k){
	long long ans = fact[n];
	ans = mul(ans, ifact[k]);
	ans = mul(ans, ifact[n - k]);
	return ans;
}

vector<int> G[200200];
int N;

void input(){
