void dfs(int v, int p){
	sz[v] = 1;
	par[v] = p;
	for(int i = 0; i < G[v].size(); ++i){
		int u = G[v][i];
		if(u == p) continue;
		dfs(u, v);
		sz[v] += sz[u];
	}
}

long long ans[200200];

void solve(){
	dfs(0, -1);
	for(int v = 1; v < N; ++v){
		cnt[sz[v]]++;
		cnt[N - sz[v]]++;
	}
	vector<long long> a, b;
	for(int i = 1; i < N; ++i){
		a.push_back(mul(cnt[i], fact[i]));
	}
	for(int i = N - 2; i >= 0; --i){
		b.push_back(ifact[i]);
	}
	FFT fft(mod, 44009197);
	vector<long long> c = fft.convolution(a, b);
	for(int i = 1; i <= N; ++i){
		long long tmp = c[N - 3 + i];
		ans[i] = mul(N, C(N, i)) - mul(tmp, ifact[i]);
		ans[i] %= mod;
		ans[i] += mod;
		ans[i] %= mod;
	}
}

