void fft(Pol&a,bool inv)    {
    int n = sz(a);
    for(int i = 0 ; i < n ; ++i)    {
        int x = i;
        for(int j = 0, k = log2(n) - 1 ; j < k ; ++j, --k)
            if((x >> j & 1) != (x >> k & 1))    {
                x ^= (1 << j);
                x ^= (1 << k);
            }
        if (i < x)  swap(a[i],a[x]);
    }
    for(int k = 1 ; k < n ; k <<= 1)
    for(int i = 0 ; i < n ; i += k + k) {
        int idx = 0;
        int gap = N / k;

        for(int j = 0 ; j < k ; ++j, idx += gap)    {
            int x = a[i + j];
            int y = mul(a[i + j + k],inv ? I[idx] : W[idx]);

            add(a[i + j],y);    a[i + j + k] = x;
            sub(a[i + j + k],y);
        }
    }
    if (inv)    {
        int m = Pow(n,mod - 2);

        for(int&x : a)
            x = mul(x,m);
    }
}
