    int n = sz(a) + sz(b) - 1;
    int m = (2 << (int)(log2(n)));

    a.resize(m);    fft(a,0);
    b.resize(m);    fft(b,0);

    for(int i = 0 ; i < m ; ++i)
        a[i] = mul(a[i],b[i]);

    fft(a,1);   a.resize(n);

