using Mint = ModInt<MOD>;
const int MN = 2000010;
Mint fact[MN], iFac[MN];

void first() {
    fact[0] = Mint(1);
    for (int i = 1; i < MN; i++)
        fact[i] = fact[i - 1] * Mint(i);
    iFac[MN - 1] = fact[MN - 1].inv();
    for (int i = MN - 1; i >= 1; i--) {
        iFac[i - 1] = iFac[i] * Mint(i);
    }
    assert(fact[2345] * iFac[2345] == Mint(1));
}
Mint C(int n, int k) {
    if (n < k || k < 0)
        return Mint(0);
    return fact[n] * iFac[k] * iFac[n - k];
}

void solve() {
    vi ident;
    ReRooting<vector<int>, int> g(
        N,
        [](vi x, vi y) {
            if (x.size() > y.size()) {
                x.insert(x.end(), all(y));
                return x;
            } else {
                y.insert(y.end(), all(x));
                return y;
            }
        },
        [](vi x, int) {
            vi ret{accumulate(all(x), 0) + 1};
            return ret;
        },
        ident);
    for (int i = 0; i < N - 1; i++) {
        g.add_edge(a[i], b[i], 0);
    }
    vector<Mint> cnt(N, Mint{0});
    for (auto& V : g.build()) {
        for (auto& x : V)
            cnt[x] += 1;
    }

    first();
    vector<int> A(N, 0), B(N + 1, 0);
    for (int i = 0; i < N; i++) {
        A[i] = (fact[i] * cnt[i]).v;
    }
    for (int i = 0; i <= N; i++) {
        B[i] = iFac[N - i].v;
    }

    NumberTheoreticTransform<MOD> ntt;
    auto ans = ntt.multiply(A, B);


    for (int K = 1; K <= N; K++) {
        cout << C(N, K) * N - iFac[K] * ans[N + K] << endl;
    }
}


