void ntt(int *x,int sz,int tp){
	for(int i=sz>>1,j=1;j<sz;j++){
		if(i<j)swap(x[i],x[j]);
		int k;
		for(k=sz>>1;i&k;i^=k,k>>=1);i^=k;
	}
	for(int m=2;m<=sz;m<<=1){
		int w;
		if(tp>0)w=quickpow(5,(mod-1)/m);
		else w=quickpow(5,mod-1-(mod-1)/m);
		for(int i=0;i<sz;i+=m){
			int cur=1;
			for(int j=i;j<i+(m>>1);j++){
				int u=x[j],v=1LL*x[j+(m>>1)]*cur%mod;
				x[j]=(u+v)%mod;x[j+(m>>1)]=(u-v+mod)%mod;cur=1LL*cur*w%mod;
			}
		}
	}
	if(tp<0){
		int inv=quickpow(sz,mod-2);
		rep(i,sz)x[i]=1LL*x[i]*inv%mod;
	}
}

