		a[x].push_back(y);
		a[y].push_back(x);
	}
	work(1, 0);
	for (int i = 0; i < n; i++)
		b[i] = (b[i] + P) % P;
	b[n] = n;
	fac[0] = 1;
	for (int i = 1; i <= n; i++)
		fac[i] = fac[i - 1] * i % P;
	inv[n] = power(fac[n], P - 2);
	for (int i = n - 1; i >= 0; i--)
		inv[i] = inv[i + 1] * (i + 1) % P;
	for (int i = 0; i <= n; i++) {
		c[i] = (number) {fac[n - i] * b[n - i] % P};
		d[i] = (number) {inv[i]};
	}
	N = 1, Log = 0;
	while (N <= 2 * n + 2) {
		N <<= 1;
		Log++;
	}
	PREBRC();
	NTT(c, 1);
	NTT(d, 1);
	for (int i = 0; i < N; i++)
		res[i] = c[i] * d[i];
	NTT(res, -1);
	for (int i = 1; i <= n; i++)
		printf("%lld\n", inv[i] * res[n - i].x % P);
	return 0;
}

