}

int Kasumi(int A, int B) {
	int Ans = 1, Base = A;
	B = (B + (Mod - 1)) % (Mod - 1);
	while(B) {
		if(B & 1) Ans = Base * Ans % Mod;
		Base = Base * Base % Mod;
		B >>= 1;
	}
	return Ans;
} 

int Fac[MaxN], Inv[MaxN];

void Init() {
	Fac[0] = 1; Inv[0] = 1;
	for(int i = 1; i <= N << 1; i++) Fac[i] = Fac[i - 1] * i % Mod;
	for(int i = 1; i <= N << 1; i++) Inv[i] = Kasumi(Fac[i], Mod - 2);
}

int C(int A, int B) {
	return Fac[A] % Mod * Inv[B] % Mod * Inv[A - B] % Mod;
} 

int Rev[MaxN];

#define Swap(A, B) A ^= B ^= A ^= B

void Ntt(int *A, int N, int Flag) {
    for(int i = 0; i < N; i++) 
        if(i < Rev[i]) Swap(A[i], A[Rev[i]]);
    for(int i = 1; i < N; i <<= 1) {
        int W = Kasumi(G, Flag * (Mod - 1) / (i << 1));
        for(int j = 0; j < N; j += (i << 1)) {
            int Wn = 1;
            for(int k = 0; k < i; k++, Wn = Wn * W % Mod) {
                int x = A[j + k], y = A[i + j + k] * Wn % Mod;
                A[j + k] = (x + y) % Mod;
                A[i + j + k] = (x - y + Mod) % Mod;
            }
        }
    }
    if(!~Flag) {
        int T = Kasumi(N, Mod - 2);
        for(int i = 0; i < N; i++) A[i] = A[i] * T % Mod;
    }
}

int Ans[MaxN];
int A[MaxN], B[MaxN];

main() {
	scanf("%lld", &N);
	for(int i = 1, A, B; i <= N - 1; i++) scanf("%lld%lld", &A, &B), Add(A, B), Add(B, A);
	Init(); Dfs(1, 0);
	for(int i = 0; i <= N; i++) A[i] = Coe[i] * Fac[i] % Mod, B[i] = Inv[i];
	std::reverse(B, B + N + 1);
	int Len = 1, Log = 0;
	while(Len <= (N << 1)) Len <<= 1, Log += 1;
	for(int i = 0; i < Len; i++) Rev[i] = (Rev[i >> 1] >> 1) | ((i & 1) << (Log - 1));	
	Ntt(A, Len, 1); Ntt(B, Len, 1);
	for(int i = 0; i < Len; i++) A[i] = A[i] * B[i] % Mod;
	Ntt(A, Len, -1);
	for(int i = 0; i < Len; i++) Ans[i] = A[i];
	for(int i = 1; i <= N; i++) {
		int P = Ans[N + i] * Inv[i] % Mod;
		P = (P + Mod) % Mod;
		printf("%lld\n", P % Mod);
	}
}

