vector <int> adj[1 << 19];
int sz[1 << 19];
int S[1 << 19];
int fac[1 << 19];

void dfs(int u, int p) {
	sz[u] = 1;
	rep(i, adj[u].size()) {
		int v = adj[u][i];
		if (v == p) continue;
		dfs(v, u);
		S[sz[v]] ++;
		sz[u] += sz[v];
	}
	S[n - sz[u]] ++;
}

int main() {
	rep(i, 1 << 19) fac[i] = i ? 1LL * i * fac[i - 1] % mod : 1;
	scanf("%d", &n);
	rep(i, n - 1) {
		int u, v; scanf("%d %d", &u, &v);
		-- u; -- v; adj[u].pb(v); adj[v].pb(u);
	}
	dfs(0, -1);
	poly a(n + 1); rep(i, n + 1) a[i] = 1LL * S[i] * fac[i] % mod;
	poly b(n + 1); rep(i, n + 1) b[n - i] = inv(fac[i]);
	poly c = a * b;
	rep(k, n + 1) if (k) {
		int ans = 1LL * n * fac[n] % mod * inv(fac[k]) % mod * inv(fac[n - k]) % mod;
		ans = (ans + mod - (1LL * c[n + k] * inv(fac[k]) % mod)) % mod;
		printf("%d\n", ans);
	}
	return 0;
}

