{
    int ret=1;
    for (; k; k>>=1,x=LL(x)*x%p)
        if (k&1)
            ret=LL(ret)*x%p;
    return ret;
}

void ntt(int *a,int n,int flag)
{
    static int rev[530000];
    repu(i,0,n-1)
        if (i<(rev[i]=(rev[i>>1]>>1)|(i&1)*(n>>1)))
            swap(a[i],a[rev[i]]);
    for (int i=1; i<n; i<<=1)
    {
        int wn=power(5,(p-1)/i/2);
        if (flag==-1)
            wn=power(wn,p-2);
        for (int j=0; j<n; j+=i*2)
        {
            int w=1,t;
            repu(k,0,i-1)
            {
                t=LL(w)*a[j+k+i]%p,w=LL(w)*wn%p;
                a[j+k+i]=(a[j+k]+p-t)%p,(a[j+k]+=t)%=p;
            }
        }
    }
    if (flag==1)
        return;
    int inv=power(n,p-2);
    repu(i,0,n-1)
        a[i]=LL(a[i])*inv%p;
}

