template <signed mod>
struct NumberTheoreticTransform {
private:
    vector<signed> rev, rts;  //swap計算用の配列, \omega^iに相当するもの
    signed base, max_base, root;
    inline signed mod_add(signed a, signed b) {
        a += b;
        if (a >= mod)
            a -= mod;
        return a;
    }
    inline signed mod_mul(signed a, signed b) {
        return (1ull * a * b) % (unsigned long long)mod;
    }
    inline signed mod_pow(signed a, signed n) {
        signed ret = 1;
        while (n) {
            if (n & 1)
                ret = mod_mul(ret, a);
            a = mod_mul(a, a);
            n >>= 1;
        }
        return ret;
    }
    inline signed mod_inv(signed a) {
        return mod_pow(a, mod - 2);
    }
    //
public:
    NumberTheoreticTransform() : base(1), rev{0, 1}, rts{0, 1} {
        assert(mod >= 3 && mod & 1 == 1);
        signed tmp = mod - 1;
        max_base = 0;
        while (tmp % 2 == 0) {
            tmp >>= 1;
            max_base++;
        }
        root = 2;
        while (mod_pow(root, (mod - 1) >> 1) == 1)
            root++;
        assert(mod_pow(root, mod - 1) == 1);
        root = mod_pow(root, (mod - 1) >> max_base);
    }
    //
private:
    void ensure_base(signed nbase) {
        if (nbase <= base)
            return;
        assert(nbase <= max_base);
        rev.resize(1 << nbase);
        rts.resize(1 << nbase);
        for (signed i = 0; i < (1 << nbase); i++) {
            rev[i] = (rev[i >> 1] >> 1) + ((i & 1) << (nbase - 1));
        }
        while (base < nbase) {
            signed z = mod_pow(root, 1 << (max_base - 1 - base));
            for (signed i = 1 << (base - 1); i < (1 << base); i++) {
                rts[i << 1] = rts[i];
                rts[(i << 1) + 1] = mod_mul(rts[i], z);
            }
            base++;
        }
    }
    void ntt(vector<signed>& a) {
        const signed n = (signed)a.size();
        assert((n & (n - 1)) == 0);
        signed zeros = __builtin_ctz(n);
        ensure_base(zeros);
        signed shift = base - zeros;
        for (signed i = 0; i < n; i++) {
            if (i < (rev[i] >> shift))
                swap(a[i], a[rev[i] >> shift]);
        }
        for (signed k = 1; k < n; k <<= 1) {
            for (signed i = 0; i < n; i += 2 * k) {
                for (signed j = 0; j < k; j++) {
                    signed z = mod_mul(a[i + j + k], rts[j + k]);
                    a[i + j + k] = mod_add(a[i + j], mod - z);
                    a[i + j] = mod_add(a[i + j], z);
                }
            }
        }
    }
    //
public:
    vector<signed> multiply(vector<signed> a, vector<signed> b) {
        if (a.empty() || b.empty())
            return {};
        bool eq = (a == b);
        signed need = a.size() + b.size() - 1;
        signed nbase = 1;
        while ((1 << nbase) < need)
            nbase++;
        ensure_base(nbase);
        signed sz = 1 << nbase;
        a.resize(sz, 0);
        b.resize(sz, 0);
        ntt(a);
        if (eq)
            b = a;
        else
            ntt(b);
        signed inv_sz = mod_inv(sz);
        for (signed i = 0; i < sz; i++) {
            a[i] = mod_mul(a[i], mod_mul(b[i], inv_sz));
        }
        reverse(a.begin() + 1, a.end());
        ntt(a);
        a.resize(need);
        return a;
    }
    vector<long long> multiply(vector<long long> a, vector<long long> b) {
        vector<signed> A(a.size()), B(b.size());
        for (signed i = 0; i < a.size(); i++) {
            A[i] = a[i];
        }
        for (signed i = 0; i < b.size(); i++) {
            B[i] = b[i];
        }
        A = multiply(A, B);
        a.resize(A.size());
        for (signed i = 0; i < A.size(); i++)
            a[i] = A[i];
        return a;
    }
};

template <typename sum_t, typename key_t>
struct ReRooting {
    struct Edge {
        int to;
        key_t data;
        sum_t dp, ndp;
    };

    using F = function<sum_t(sum_t, sum_t)>;
    using G = function<sum_t(sum_t, key_t)>;

    vector<vector<Edge>> g;
    vector<sum_t> subdp, dp;
    const sum_t ident;
    const F f;
    const G gg;

    ReRooting(int V, const F f, const G g, const sum_t& ident)
        : g(V), f(f), gg(g), ident(ident), subdp(V, ident), dp(V, ident) {}

    void add_edge(int u, int v, const key_t& d) {
        g[u].emplace_back((Edge){v, d, ident, ident});
        g[v].emplace_back((Edge){u, d, ident, ident});
    }

    void add_edge_bi(int u, int v, const key_t& d, const key_t& e) {
        g[u].emplace_back((Edge){v, d, ident, ident});
        g[v].emplace_back((Edge){u, e, ident, ident});
    }

    void dfs_sub(int idx, int par) {
        for (auto& e : g[idx]) {
            if (e.to == par)
                continue;
            dfs_sub(e.to, idx);
            subdp[idx] = f(subdp[idx], gg(subdp[e.to], e.data));
        }
    }

    void dfs_all(int idx, int par, const sum_t& top) {
        sum_t buff{ident};
        for (int i = 0; i < (int)g[idx].size(); i++) {
            auto& e = g[idx][i];
            e.ndp = buff;
            e.dp = gg(par == e.to ? top : subdp[e.to], e.data);
            buff = f(buff, e.dp);
        }
        dp[idx] = buff;
        buff = ident;
        for (int i = (int)g[idx].size() - 1; i >= 0; i--) {
            auto& e = g[idx][i];
            if (e.to != par)
                dfs_all(e.to, idx, f(e.ndp, buff));
            e.ndp = f(e.ndp, buff);
            buff = f(buff, e.dp);
        }
    }

    vector<sum_t> build() {
        dfs_sub(0, -1);
        dfs_all(0, -1, ident);
        return dp;
    }
};

