using Mint = ModInt<MOD>;
const int MN = 2000010;
Mint fact[MN], iFac[MN];

void first() {
    fact[0] = Mint(1);
    for (int i = 1; i < MN; i++)
        fact[i] = fact[i - 1] * Mint(i);
    iFac[MN - 1] = fact[MN - 1].inv();
    for (int i = MN - 1; i >= 1; i--) {
        iFac[i - 1] = iFac[i] * Mint(i);
    }
    assert(fact[2345] * iFac[2345] == Mint(1));
}
Mint C(int n, int k) {
    if (n < k || k < 0)
        return Mint(0);
    return fact[n] * iFac[k] * iFac[n - k];
}

void solve() {
    int memo[202020] = {};
    vector<Mint> cnt(N, Mint{0});
    ReRooting<int, int> g(
        N,
        [](int a, int b) { return a + b; },
        [&](int x, int i) {
            memo[i] = x + 1;
            return x + 1;
        },
        0);
    for (int i = 0; i < N - 1; i++) {
        g.add_edge(a[i], b[i], i);
    }
    g.build();

    for (int i = 0; i < N - 1; i++) {
        if (memo[i] == 0)
            continue;
        cnt[memo[i]] += 1;
        cnt[N - memo[i]] += 1;
    }

    first();
    vector<int> A(N, 0), B(N + 1, 0);
    for (int i = 0; i < N; i++) {
        A[i] = (fact[i] * cnt[i]).v;
    }
    for (int i = 0; i <= N; i++) {
        B[i] = iFac[N - i].v;
    }

    //NumberTheoreticTransform<MOD> ntt;
    //auto ans = ntt.multiply(A, B);
    ans.resize(A.size() + B.size());


    for (int K = 1; K <= N; K++) {
        cout << (int)(C(N, K) * N - iFac[K] * ans[N + K]).v << endl;
    }
}


signed main() {

    cin >> N;
    for (int i = 0; i < N - 1; i++) {
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
    }


    solve();
    return 0;
}

