long long qpow(long long a,int b)
{
    long long ret=1;
    while (b)
    {
        if (b&1)
            (ret*=a)%=MOD;
        (a*=a)%=MOD;
        b>>=1;
    }
    return ret;
}
void dft(int arr[524288],bool rev)
{
    for (int i=0;i<524288;++i)
    {
        int t=i,rev=0;
        for (int j=0;j<19;++j)
        {
            (rev<<=1)^=t&1;
            t>>=1;
        }
        if (rev>i)
            swap(arr[i],arr[rev]);
    }
    for (int i=0;i<19;++i)
    {
        int w=qpow(5,(MOD-1)/(1<<(i+1)));
        if (rev)
            w=qpow(w,MOD-2);
        for (int j=0;j<524288;j+=1<<(i+1))
        {
            int cur=1;
            for (int k=j;k<j+(1<<i);++k)
            {
                int v2=(long long)cur*arr[k+(1<<i)]%MOD;
                arr[k+(1<<i)]=arr[k]-v2;
                if (arr[k+(1<<i)]<0)
                    arr[k+(1<<i)]+=MOD;
                arr[k]+=v2;
                if (arr[k]>=MOD)
                    arr[k]-=MOD;
                cur=(long long)cur*w%MOD;
            }
        }
    }
    if (rev)
    {
        int inv=qpow(524288,MOD-2);
        for (int i=0;i<524288;++i)
            arr[i]=(long long)arr[i]*inv%MOD;
    }
}
