int n_,lgn_;
int rev_[N];
void FFT_init(int n){
	lgn_=32-clz(n);n_=1<<lgn_;
	rev_[0]=0;omg_[0]=C(1,0);
	for(int i=1;i<n_;i<<=1)omg_[i]=C(cos(2.*i*M_PI/n_),sin(2.*i*M_PI/n_));
	for(int i=1;i<n_;i++){
		omg_[i]=omg_[i^(i&-i)]*omg_[i&-i];
		rev_[i]=rev_[i/2]>>1|(i&1)<<lgn_-1;
	}
}
C ww[N];
void FFT(C*a){
	for(int i=0;i<n_;i++)if(rev_[i]<i)swap(a[i],a[rev_[i]]);
	register int t;
	register C s;
	for(int i=0;i<lgn_;i++){
		t=1<<i;
		for(register int j=0;j<t;++j)ww[j]=omg_[j<<lgn_-i-1];
		for(register int j=0;j<n_;j+=t<<1){
			register C* at=a+j,*bt=a+j+t;
			for(register int k=0;k<t;++k){
				s=bt[k]*ww[k];
				bt[k]=at[k]-s;
				at[k]=at[k]+s;
			}
		}
	}
}
C s3[N],s4[N];
void mul(int*a,int*b,int n,int m){
	FFT_init(n+m-2);memset(s1,0,sizeof s1);memset(s2,0,sizeof s2);
	for(int i=0;i<n;i++)s1[i]=C(a[i]&32767,a[i]>>15);
	for(int i=0;i<m;i++)s2[i]=C(b[i]&32767,b[i]>>15);
	FFT(s1);FFT(s2);
	for(int i=0;i<n_;i++){
		int j=(n_-1)&(n_-i);
		C da,db,dc,dd;
		da = (s1[i] + s1[j].conj()) * C(0.5, 0);
		db = (s1[i] - s1[j].conj()) * C(0, -0.5);
		dc = (s2[i] + s2[j].conj()) * C(0.5, 0);
		dd = (s2[i] - s2[j].conj()) * C(0, -0.5);
		s3[j] = da*dc+da*dd*C(0,1);
		s4[j] = db*dc+db*dd*C(0,1);
	}
	FFT(s3);FFT(s4);
	for(int i=0;i<n_;i++){
		int da = (ll)(s3[i].x / n_ + 0.5) % mod;
		int db = (ll)(s3[i].y / n_ + 0.5) % mod;
		int dc = (ll)(s4[i].x / n_ + 0.5) % mod;
		int dd = (ll)(s4[i].y / n_ + 0.5) % mod;
		a[i] = (da + ((ll)(db + dc) << 15) + ((ll)dd << 30)) % mod;
		(a[i]+=mod)%=mod;
	}
}
