namespace mod_op {

	ll MOD = 924844033;

	class modll {
	private:
		ll val;
		inline ll modify(ll x) { ll ret = x % MOD; if (ret < 0) ret += MOD; return ret; }
		inline ll inv(ll x) {
			if (x == 0) return 1 / x;
			else if (x == 1) return 1;
			else return modify(inv(MOD % x) * modify(-MOD / x));
		}
	public:
		modll(ll init = 0) { val = modify(init); return; }
		modll(const modll& another) { val = another.val; return; }
		inline modll& operator=(const modll &another) { val = another.val; return *this; }
		inline modll operator+(const modll &x) { return modify(val + x.val); }
		inline modll operator-(const modll &x) { return modify(val - x.val); }
		inline modll operator*(const modll &x) { return modify(val * x.val); }
		inline modll operator/(const modll &x) { return modify(val * inv(x.val)); }
		inline modll& operator+=(const modll &x) { val = modify(val + x.val); return *this; }
		inline modll& operator-=(const modll &x) { val = modify(val - x.val); return *this; }
		inline modll& operator*=(const modll &x) { val = modify(val * x.val); return *this; }
		inline modll& operator/=(const modll &x) { val = modify(val * inv(x.val)); return *this; }
		inline bool operator==(const modll &x) { return val == x.val; }
		inline bool operator!=(const modll &x) { return val != x.val; }
		friend inline istream& operator >> (istream &is, modll& x) { is >> x.val; return is; }
		friend inline ostream& operator << (ostream &os, const modll& x) { os << x.val; return os; }
		ll get_val() { return val; }
	};

	modll pow(modll n, ll p) {
		modll ret;
		if (p == 0) ret = 1;
		else if (p == 1) ret = n;
		else {
			ret = pow(n, p / 2);
			ret *= ret;
			if (p % 2 == 1) ret *= n;
		}
		return ret;
	}

	vector<modll> facts;

	inline void make_facts(int n) {
		if (facts.empty()) facts.push_back(modll(1));
		for (int i = (int)facts.size(); i <= n; ++i) facts.push_back(modll(facts.back() * (ll)i));
		return;
	}

	vector<modll> ifacts;
	vector<modll> invs;

	inline void make_invs(int n) {
		if (invs.empty()) {
			invs.push_back(modll(0));
			invs.push_back(modll(1));
		}
		for (int i = (int)invs.size(); i <= n; ++i) {
			// because 0 = MOD = kq + r, 1/k = -q/r
			invs.push_back(invs[(int)MOD % i] * ((int)MOD - (int)MOD / i));
		}
		return;
	}

	inline void make_ifacts(int n) {
		make_invs(n);
		if (ifacts.empty()) ifacts.push_back(modll(1));
		for (int i = (int)ifacts.size(); i <= n; ++i) ifacts.push_back(modll(ifacts.back() * invs[i]));
		return;
	}

	//nCr
	modll combination(ll n, ll r) {
		if (n >= r && r >= 0) {
			modll ret;
			make_facts((int)n);
			make_ifacts((int)n);
			ret = facts[(unsigned)n] * ifacts[(unsigned)r] * ifacts[(unsigned)(n - r)];
			return ret;
		}
		else return 0;
	}

	modll get_fact(ll n) {
		make_facts((int)n);
		return facts[(int)n];
	}

	modll get_ifact(ll n) {
		make_ifacts((int)n);
		return ifacts[(int)n];
	}

	//log_a(b), if x does not exist, return -1
	ll disc_log(modll a, modll b) {
		ll ret = -1;
		ll m = ceilsqrt(MOD);
		unordered_map<ll, ll> mp;
		modll x = 1;
		Loop(i, m) {
			mp[x.get_val()] = i;
			x *= a;
		}
		x = modll(1) / pow(a, m);
		modll k = b;
		Loop(i, m) {
			if (mp.find(k.get_val()) == mp.end()) k *= x;
			else {
				ret = i * m + mp[k.get_val()];
				break;
			}
		}
		return ret;
	}
}

using namespace mod_op;
typedef vector<modll> vmodll;
typedef vector<vector<modll>> vvmodll;

namespace number_theoretic_transform {

	ll mod_backup;
	modll min_omega;
	int min_omega_depth;
	modll mod_half;

	void make_base(int mode) {
		mod_backup = MOD;
		switch (mode) {
		case 0:
			MOD = 167772161;
			min_omega = 17;
			min_omega_depth = 25;
			mod_half = 83886081;
			break;
		case 1:
			MOD = 469762049;
			min_omega = 30;
			min_omega_depth = 26;
			mod_half = 234881025;
			break;
		default:
			MOD = 1224736769;
			min_omega = 149;
			min_omega_depth = 24;
			mod_half = 612368385;
		}
	}

	void recover_base() {
		MOD = mod_backup;
	}

	vector<modll> omegas, iomegas;

	inline int bit_reverse(int x, int digit) {
		int ret = digit ? x & 1 : 0;
		Loop(i, digit - 1) { ret <<= 1; x >>= 1; ret |= x & 1; }
		return ret;
	}

	inline void make_omegas(int n) {
		if (omegas.size() != n) {
			omegas.resize(n);
			modll omega = pow(min_omega, (1 << min_omega_depth) / n);
			Loop(i, n) {
				if (i == 0) omegas[i] = 1;
				else omegas[i] = omegas[i - 1] * omega;
			}
		}
	}

	inline void make_iomegas(int n) {
		if (iomegas.size() != n) {
			iomegas.resize(n);
			modll iomega = modll(1) / pow(min_omega, (1 << min_omega_depth) / n);
			Loop(i, n) {
				if (i == 0) iomegas[i] = 1;
				else iomegas[i] = iomegas[i - 1] * iomega;
			}
		}
	}

	// a.size() should be 2^digit
	vector<modll> NTT(const vector<modll> a, int mode = 0) {
		int n = int(a.size());
		int digit = int(rndf(log2(n)));
		vector<modll> ret = a;
		make_omegas(n);
		Loop(i, n) {
			int j = bit_reverse(i, digit);
			if (j > i) swap(ret[i], ret[j]);
		}
		Loop(i, digit) {
			int j = 0, m = 1 << i, mw = (digit - i - 1);
			Loop(group_id, n >> (i + 1)) {
				Loop(k, m) {
					modll x = ret[j] + omegas[k << mw] * ret[j + m];
					modll y = ret[j] - omegas[k << mw] * ret[j + m];
					ret[j] = x; ret[j + m] = y;
					++j;
				}
				j += m;
			}
		}
		return ret;
	}

	// f.size() should be 2^digit
	vector<modll> INTT(const vector<modll>& f, int mode = 0) {
		int n = int(f.size());
		int digit = int(rndf(log2(n)));
		vector<modll> ret = f;
		make_iomegas(n);
		Loopr(i, digit) {
			int j = 0, m = 1 << i, mw = (digit - i - 1);
			Loop(group_id, n >> (i + 1)) {
				Loop(k, m) {
					modll q = (ret[j] + ret[j + m]) * mod_half;
					modll r = (ret[j] - ret[j + m]) * mod_half * iomegas[k << mw];
					ret[j] = q; ret[j + m] = r;
					++j;
				}
				j += m;
			}
		}
		Loop(i, n) {
			int j = bit_reverse(i, digit);
			if (j > i) swap(ret[i], ret[j]);
		}
		return ret;
	}

	// a.size() = b.size() should be 2^digit
	vector<modll> mul_convolution(const vector<modll> &a, const vector<modll> &b) {
		int n = int(a.size());
		vector<modll> ret;
		make_base(0);
		vector<modll> g = NTT(a), h = NTT(b);
		Loop(i, n) g[i] *= h[i];
		ret = INTT(g);
		recover_base();
		return ret;
	}

	int legal_size_of(int n) {
		int ret = 1 << (int)log2(n);
		if (ret < n) ret <<= 1;
		return ret;
	}
}

using namespace number_theoretic_transform;


typedef ll nodeval_t;
typedef ll edgeval_t;

struct tree_t {
	int n;           // |V|, index begins with 0
	vector<P> edges; // E
	vector<nodeval_t> vals; // value of nodes
	vector<edgeval_t> costs; // cost, distance, or weight of edges
};

class Tree {
private:
	struct node {
		int id; vi childs; int parent = -1;
		int deg = -1; // the number of edges of the path to the root
		int eid = -1; // edge id of the edge connected by its parent and itself
		int subtree_n = 1; // the number of nodes of the partial tree rooted by itself
		nodeval_t val; // value of the node itself
		edgeval_t cost; // cost of the edge connected by its parent and itself
		bool operator<(const node & another) const {
			return deg != another.deg ? deg < another.deg : id < another.id;
		}
	};
	struct edgeinfo {
		int eid; int to; edgeval_t cost;
	};
	int n;
	static const nodeval_t init_val = 0;
	static const edgeval_t init_cost = 1;
	vector<vector<edgeinfo>> edges;
	void tree_construction() {
		leaves = {};
		queue<int> que;
		que.push(root);
		while (que.size()) {
			int a = que.front(); que.pop();
			deg_order.push_back(a);
			if (a == Tree::root) nodes[a].deg = 0;
			int leaf_flag = true;
			Loop(i, edges[a].size()) {
				int b = edges[a][i].to;
				if (nodes[b].deg != -1) {
					nodes[a].parent = b;
					nodes[a].eid = edges[a][i].eid;
					nodes[a].cost = edges[a][i].cost;
					nodes[a].deg = nodes[b].deg + 1;
				}
				else {
					leaf_flag = false;
					nodes[a].childs.push_back(b);
					que.push(b);
				}
			}
			if (leaf_flag) leaves.push_back(a);
		}
		Loopr(i, n) {
			int a = deg_order[i];
			Loop(j, nodes[a].childs.size()) {
				int b = nodes[a].childs[j];
				nodes[a].subtree_n += nodes[b].subtree_n;
			}
		}
	}
public:
	vector<node> nodes;
	vi deg_order; // node ids, sorted by deg
	vi leaves;
	int root;
	// T should be non-empty tree
	Tree(tree_t T, int root) {
		n = T.n;
		nodes.resize(n);
		Loop(i, n) {
			nodes[i].id = i;
			nodes[i].val = (int)(T.vals.size()) > i ? T.vals[i] : init_val;
			nodes[i].cost = init_cost;
		}
		edges.resize(n);
		Loop(i, n - 1) {
			edges[T.edges[i].first].push_back({ i, T.edges[i].second, ((int)(T.costs.size()) > i ? T.costs[i] : init_cost) });
			edges[T.edges[i].second].push_back({ i, T.edges[i].first, ((int)(T.costs.size()) > i ? T.costs[i] : init_cost) });
		}
		Tree::root = root;
		tree_construction();
		return;
	}
	pair<vmodll, vll> solve() {
		pair<vmodll, vll> ret;
		ret.first.resize(n + 1);
		ret.second.resize(n + 1);
		Loop(i, n) {
			ret.first[i] = (combination(n - 1, i + 1) + combination(n - 1, i)) * n;
		}
		Loop(i, n) {
			ret.second[n - nodes[i].subtree_n]++;
			Loop(j, nodes[i].childs.size()) {
				int t = nodes[i].childs[j];
				int cnt = nodes[t].subtree_n;
				ret.second[cnt]++;
			}
			if (nodes[i].childs.size() == 0) ret.second[0]++;
		}
		return ret;
	}
};


int main() {
	int n; cin >> n;
	tree_t T;
	T.n = n;
	Loop(i, n - 1) {
		int s, t; cin >> s >> t;
		s--; t--;
		T.edges.push_back({ s, t });
	}
	Tree tree(T, 0);
	auto step1 = tree.solve();
	int N = legal_size_of(n * 2);
	vector<modll> a(N), b(N);
	Loop(i, n) {
		a[i] = get_fact(n - i - 1).get_val() * step1.second[n - i - 1];
		b[i] = get_ifact(i).get_val();
	}
	vector<modll> c = mul_convolution(a, b);
	vmodll ans = step1.first;
	Loop(i, n - 1) {
		ans[i] -= c[n - 2 - i] * get_ifact(i + 1);
	}
	Loop(i, n) {
		cout << ans[i] << endl;
	}
}

