const int mmod = 924844033;

vector<vector<int> > G;
vector<int> sz;
vector<int> parent;

  const int max_n = 499999;
    int fac[max_n], inv_fac[max_n];

	int inv_mod(int a, int b) {
		if (a == 1) return b;
		int div = mmod / a + 1;
		return inv_mod((a * (long long)div) % mmod, (b * (long long)div) % mmod);
	}

void go(int now, int prv) {
  sz[now] = 1;
  parent[now] = prv;
  for (int i=0; i<G[now].size(); i++) {
    if (prv == G[now][i]) continue;
    go(G[now][i], now);
    sz[now] += sz[G[now][i]];
  }
//  printf("sz[%d] = %d %d\n", now, sz[now], parent[now]);
}

long long combi(int a, int b) {
  if (b < 0 || b > a) return 0;
  long long res = fac[a];
  res = (res * inv_fac[b]) % mmod;
  res = (res * inv_fac[a-b]) % mmod;
  return res;
}

long long partial_combi(int a, int b) {
  if (b < 0 || b > a) return 0;
  long long res = fac[a];
//  res = (res * inv_fac[b]) % mmod;
  res = (res * inv_fac[a-b]) % mmod;
  return res;
}

int main()
{
  int N;
  cin >> N;
  G.resize(N);
  sz.resize(N);
  parent.resize(N);
  for (int i=0; i<N-1; i++) {
    int a, b;
    cin >> a >> b;
    a --;
    b --;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  go(0, -1);

  map<int, int> M;
  for (int i=0; i<N; i++) {
    int remain = N-1;
    for (int j=0; j<G[i].size(); j++) {
      int ssz = sz[G[i][j]];
      if (G[i][j] == parent[i]) continue;
      remain -= ssz;
      M[ssz] ++;
    }
    if (remain) M[remain] ++;
  }

  vector<int> what ,occ;
  for (auto a : M) {
//    printf("%d %d\n", a.first, a.second);
    what.push_back(a.first);
    occ.push_back(a.second);
  }

  fac[0] = inv_fac[0] = 1;
  for (int i=1; i<max_n; i++) {
    fac[i] = (fac[i-1] * 1LL * i) % mmod;
    inv_fac[i] = inv_mod(fac[i], 1);
  }

  for (int K=1; K<=N; K++) {
    int res = 0;
    for (int idx = 0; idx < what.size(); idx ++) {
      int ww = what[idx];
      int oo = occ[idx];
      res = (res - 1LL * partial_combi(ww, K) * oo) % mmod;
    }
    res = (res * inv_fac[K]) % mmod;
    res = (res + 1LL * combi(N, K) * N) % mmod;
    res = (res + mmod) % mmod;
    printf("%lld\n", res);
  }
}

