inline void NTT(ll *a,int len,int opt){
	for(int i=0;i<len;++i) if(i<r[i]) swap(a[i],a[r[i]]);
	for(int i=1;i<len;i<<=1){
		ll u=qpow(7,opt*(mod-1)/(i<<1)+mod-1);
		for(int j=0,w=1;j<len;j+=i<<1,w=1) for(int k=0;k<i;++k,w=w*u%mod){
			ll x=a[j+k],y=a[j+k+i]*w%mod;
			a[j+k]=(x+y)%mod,a[j+k+i]=(x-y)%mod;
		}
	}
	if(~opt) return;
	for(int i=0,inv=qpow(len,mod-2);i<len;++i) a[i]=a[i]*inv%mod;
}
