inline void ntt(poly &a,int len,int opt){
	a.resize(len);
	for(int i=0;i<len;++i) if(i<rev[i]) swap(a[i],a[rev[i]]);
	for(int i=1;i<len;i<<=1) for(int j=0;j<len;j+=i<<1) for(int k=0;k<i;++k){
		int x=a[j+k],y=a[j+k+i]*g[i+k]%mod;
		a[j+k]=x+y>=mod?x+y-mod:x+y; a[j+k+i]=x-y<0?x-y+mod:x-y;
	}
	if(~opt) return ;
	reverse(a.begin()+1,a.end());
	const int inv=qpow(len,mod-2);
	for(int i=0;i<len;++i) a[i]=a[i]*inv%mod;
}
