inline void NTT(ll *a,int len,int opt){
	for(int i=0;i<len;++i) if(i<r[i]) swap(a[i],a[r[i]]);
	for(int i=1;i<len;i<<=1){
		ll u=qpow(7,opt*(mod-1)/(i<<1)+mod-1);
