			a[j+k]=(x+y)%mod,a[j+k+i]=(x-y)%mod;
		}
	}
	if(~opt) return;
	for(int i=0,inv=qpow(len,mod-2);i<len;++i) a[i]=a[i]*inv%mod;
}
