fun gcd(a: Long, b: Long): Long = if (b == 0L) a else gcd(b, a%b)

fun power(a: Long, b: Long, p: Long): Long
{
	if (b == 0L) return 1L
	var t = power(a, b/2, p)
	t = t*t%p
	if (b%2 == 1L) t = t*a%p
	return t
}

var factorial = arrayOf<ModInt>()
var invFactorial = arrayOf<ModInt>()

fun prepareFactorials(n: Int)
{
	factorial = Array<ModInt>(n+1, {0.toModInt()})
	invFactorial = Array<ModInt>(n+1, {0.toModInt()})
	factorial[0] = 1.toModInt()
	for (i in 1..n) factorial[i] = factorial[i-1]*i.toModInt()
	invFactorial[n] = factorial[n].inverse()
	for (i in n-1 downTo 0) invFactorial[i] = invFactorial[i+1]*(i+1).toModInt()
}

fun choose(n: Int, m: Int): ModInt
{
	if (m < 0 || m > n) return 0.toModInt()
	return factorial[n]*invFactorial[m]*invFactorial[n-m]
}

class ModInt
{
	var x: Int

	constructor (value: Int = 0)
	{
		x = value
	}
	constructor (modInt: ModInt)
	{
		x = modInt.x
	}

	operator fun unaryPlus() = ModInt(x)
	operator fun unaryMinus() = if (x != 0) ModInt(MOD-x) else ModInt(0)
	operator fun inc() = if (x == MOD-1) ModInt(0) else ModInt(x+1)
	operator fun dec() = if (x == 0) ModInt(MOD-1) else ModInt(x-1)

	operator fun plus(rhs: ModInt): ModInt
	{
		var c = x+rhs.x
		if (c >= MOD) c -= MOD
		return ModInt(c)
	}
	operator fun minus(rhs: ModInt): ModInt
	{
		var c = x-rhs.x
		if (c < 0) c += MOD
		return ModInt(c)
	}
	operator fun times(rhs: ModInt): ModInt
	{
		return ModInt((x.toLong()*rhs.x%MOD).toInt())
	}

	fun toInt() = this.x
	override fun toString() = this.x.toString()
	fun power(e: Int): ModInt
	{
		var ret = ModInt(1)
		var exp = e
		var base = ModInt(x)
		while (exp != 0)
		{
			if (exp and 1 == 1) ret *= base
			exp = exp shr 1
			base *= base
		}
		return ret
	}
	fun inverse() = power(MOD-2)
}

fun Int.toModInt() = ModInt(this)

class NTT
{
	var roots = arrayOf(0.toModInt(), 1.toModInt())
	var bitReverse = emptyArray<Int>()
	var maxSize = -1
	var root = 0.toModInt()

	fun getLength(n: Int): Int = if (n == 1) 0 else getLength(n/2)+1
	fun roundUpPowerTwo(n: Int): Int
	{
		var x = n
		while (x and -x != x) x += x and -x
		return x
	}

	fun findRoot()
	{
		var order = MOD-1
		maxSize = 1
		while (order%2 == 0)
		{
			order /= 2
			maxSize *= 2
		}
		root = 2.toModInt()
		while (!(root.power(maxSize).toInt() == 1 && root.power(maxSize/2).toInt() != 1))
		{
			root ++
		}
	}

	fun prepareRoots(n: Int)
	{
		if (maxSize == -1) findRoot()
		if (roots.size >= n) return
		var len = getLength(roots.size)
		roots += Array<ModInt>(n-len, {0.toModInt()});
		while (1 shl len < n)
		{
			var z = root.power(maxSize shr (len+1))
			for (i in (1 shl (len-1))..(1 shl len)-1)
			{
				roots[2*i] = roots[i]
				roots[2*i+1] = roots[i]*z
			}
			len ++
		}
	}

	fun bitReorder(n: Int, values: Array<ModInt>)
	{
		if (bitReverse.size != n)
		{
			var len = getLength(n)
			bitReverse = Array<Int>(n, {0})
			for (i in 0..n-1) bitReverse[i] = (bitReverse[i shr 1] shr 1)+((i and 1) shl (len-1))
		}
		for (i in 0..n-1)
			if (i < bitReverse[i])
			{
				val tmp = values[i]
				values[i] = values[bitReverse[i]]
				values[bitReverse[i]] = tmp
			}
	}

	fun fft(N: Int, values: Array<ModInt>)
	{
		prepareRoots(N)
		bitReorder(N, values)
		var n = 1
		while (n < N)
		{
			var start = 0
			while (start < N)
			{
				for (i in 0..n-1)
				{
					var even = values[start+i]
					var odd = values[start+n+i]*roots[n+i]
					values[start+n+i] = even-odd
					values[start+i] = even+odd
				}
				start += 2*n
			}
			n *= 2
		}
	}

	fun multiply(lhs: Array<ModInt>, rhs: Array<ModInt>): Array<ModInt>
	{
		var n = lhs.size
		var m = rhs.size
		var N = roundUpPowerTwo(n+m-1)
		var left = Array<ModInt>(N, { x -> if (x < n) lhs[x] else 0.toModInt() })
		var right = Array<ModInt>(N, { x -> if (x < m) rhs[x] else 0.toModInt() })
		fft(N, left)
		fft(N, right)
		var invN = N.toModInt().inverse()
		for (i in 0..N-1) left[i] *= right[i]*invN
		for (i in 1..N/2-1)
		{
			var tmp = left[i]
			left[i] = left[N-i]
			left[N-i] = tmp
		}
		fft(N, left)
		return Array<ModInt>(n+m-1, { x -> left[x] })
	}
}

