    private static ArrayList<Integer> [] E;
    private static int [] fact,rev;

    private static int add(int a,int b) {
        a += b;
        if (a >= mod) a -= mod;
        if (a < 0) a += mod;
        return a;
    }

    private static int mul(int a,int b) {
        return (int)((a*(long)b)%mod);
    }
    private static void init() throws Exception{
        fr = new int[n-1];
        to = new int[n-1];
        val = new int[n-1];
        siz = new int[n+1];
        E = new ArrayList[n+1];
        for (int u = 1;u <= n;u++)
            E[u] = new ArrayList<>();

        fact = new int[n+1];
        fact[0] = 1;
        for (int i = 1;i <= n;i++)
            fact[i] = mul(fact[i-1],i);

        int [] r = new int[n+1];
        rev = new int[n+1];
        rev[0] = rev[1] = r[1] = 1;
        for (int i = 2;i <= n;i++) {
            r[i] = add(mod ,-mul(mod/i, r[mod%i]));
            rev[i] = mul(rev[i-1],r[i]);
            if (mul(fact[i],rev[i]) != 1)
                throw new Exception("!= 1");
        }

    }

    private static int C(int n,int k) {
        if (k > n) return 0;
        int res = fact[n];
        res = mul(res,rev[k]);
        res = mul(res,rev[n-k]);
        return res;
    }

    private static int powmod(int x,int p) {
        if (p == 0) return 1;
        int y = 1;
        for (;p > 1;p >>= 1) {
            if (p%2 == 1) y = mul(x,y);
            x = mul(x,x);
        }
        return mul(x,y);
    }

    private static void dfs(int u,int p){
        siz[u] = 1;
        for (int e : E[u]) {
            int v = fr[e] + to[e] - u;
            if (v == p) continue;
            fr[e] = u; to[e] = v;
            dfs(v,u);
            siz[u] += siz[v];
        }
    }

